-- Cutaneous Allergy
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (1, 1, 'In which of the following types of angioedema is the C4 level usually within the normal range?', 'Acquired angioedema associated with B-cell lymphoma.', 'Hereditary angioedema type I.', 'Hereditary angioedema type II.', 'Hereditary angioedema type III.', 'None of the above.', 'D', 'An easy way to remember this is that all types of angioedema, with the exception of hereditary angioedema type III, angioedema as part of urticaria, and ACE inhibitor angiooedema are usually associated with low levels of C4.
In hereditary angioedema type I, Cl esterase inhibitor levels are reduced, however in type II the Cl esterase inhibitor levels may be normal or elevated but the functional Cl inhibitor activity is decreased.
Type III hereditary angioedema is exceptionally rare and is associated with norm.:il levels of both C4 and Cl esterase inhibitor. It is caused by mutation in factor XII.
Type III hereditary angioedema is mostly seen in female patients and can be aggravated by oestrogens. Diagnosis is often difficult and requires identification of factor XII mutation.
Acquired angioedema can occur secondary to lymphoproliferative disorders, or systemic lupus erythematosus. This is associated with low leveis of both C4 and Cl esterase inhibitor levels and a positive anti-Clq antibody.
The presence of anti-Clq antibody will help differentiate acquired angioedema (secondary to lymphoproliferative disorders or systemic lupus erythematosus) frcm hereditary angioedema in new cases where there is no family history.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (2, 1, 'Which of the following is not a physical urticaria?', 'Cold urticaria.', 'Delayed pressure urticaria.', 'Dermographism.', 'Hereditary angioedema.', 'Solar urticaria.', 'D', 'Other forms of physical urticarias include: cholinergic, vibratory, aquagenic and exercise-induced urticaria (exercise following the ingestion of shell fish and wheat are the commonest triggers).
Hereditary angioedema should be considered in isolated angioedema unresponsive to anti-histamines or corticosteroids.
Low complement 4 levels are always found during the attacks (except in type 3 hereditary angioedema).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (3, 1, 'Latex can cross-react with all of the following except:', 'Avocado.', 'Banana.', 'Chestnut.', 'Kiwi.', 'Peanuts.', 'E', 'Peanuts are legumes and can cross-react with beans, soya, peas and lentils.
Cross-reaction with "tree nuts" may also occur.
Cross-reaction of latex with certain fruits give rise to the "latex-fruit allergy syndrome" in which the symptoms are similar to the "oral allergy syndrome" that occurs due to the cross-reaction of birch pollen with certain fruits such as apples and pears.
The symptoms are mainly of contact urticaria (typP.-1 allergy).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (4, 1, 'A 65-year-old man presents with photo-distributed eczema that is worse each time he works in his garden. You therefore suspect allergic contact dermatitis and perform patch testing to series which include chemicals and plants. Which of the following chemicals is found predominantly in wood?', 'Dalbergiones.', 'Parthenoline.', 'Parthenoline.', 'Primin.', 'Sesquiterpene lactone mix.', 'A', 'Dalberglones are chemicals found mainly in wood and should therefore be suspected in wood cutters.
Tulpulin-A is the main allergen found in Tulips.
Primin is the main allergen in the Primula plant.
Sesquiterpene lactone mix is an allergen found in many plants and therefore can serve in many cases as a "screening" for possible plant allergy.
Other chemicals that can be found in plants or trees include oak, moss, terpenes and propolis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (5, 1, 'A 46-year-old woman has been complaining of intractable vulval dermatitis for the last five years for which she has tried several prescribed and over-the-counter preparations, some of which aggravates her dermatitis. You suspect allergic contact dermatitis and therefore advise patch testing. Which of the following allergens is least likely to be relevant in thiscase?', 'Balsam of Peru.', 'Neomycin.', 'Caine mix.', 'Nickel Sulphate.', 'Parabens.', 'D', 'Nickel Sulphate is the most commonly found allergen including in patients who have been patched for vulval contact dermatitis however, it is the least likely to be relevant in this situation.
Vulval contact dermatitis is often caused by preservatives, topical anaesthetics, perfumes, neomycin and patients'' own products.
More recently, in the United Kingdom, positive patch test reactions to sodium metablsulphite, as in trimovate cream, have been increasingly seen in this condition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (6, 1, 'Peri-orbital oedema is most likely to occur in which of the following conditions?', 'Actinic prurigo.', 'Chronic actinic dermatitis.', 'Hydroa vacciniforme.', 'Photo-contact allergy.', 'Polymorphic light eruption.', 'D', 'Other causes of peri-orbital oedema include allergic contact dermatitis to cosmetics or PPD with or without overt scalp dermatitis, dermatomyositis,angio-oedema, erysipelas, nephrotic syndrome and hypothyroidism.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (7, 1, 'Which of the following chemicals is not a preservative?', 'Formaldehyde.', 'Mercaptobenzothiazole.', 'Methyldibromoglutaronitrile.', 'Methylparaben.', 'Phenoxyethanol.', 'B', 'Mercaptobenzothiazole is a rubber allergen. It should therefore be suspected in cases where there is a suspicion of rubber allergy such as the use of glov s or in suspected shoe dematitis.
Other rubber allergens include carba and thiuram mix.
Other preservatives include the isothlozilinones, gluteraldehyde and all the formaldehyde releasers.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (8, 1, 'You patch test a 36-year-old lady who gave a history of worsening of her eczema with the use of certain topical preparations and you found a strong positive reaction to benzalkonium chloride. Which of the following topical preparations is safe to use?', 'Dermol9 500 lotion.', 'Dermol9 cream.', 'EmulsidermtDemulsion.', 'Oilatum9 gel.', 'Oilatum9 plus.', 'D', 'Benzalkonium chloride is an anti-microbial chemical added in many preparations of emollients and antiseptics.
Oilatum plus contains benzalkonium chloride however, all other products of oilatum do not contain this chemical.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (9, 1, 'Which of the following statements regarding poison ivy is correct?', 'Poison ivy sensitive individuals can develop peri-oral dermatitis from eating bananas.', 'Rubber gloves are safe to use in sensitized individuals when in contact with the plant.', 'The allergen responsible following contact with the plant is urushiol.', 'The allergen responsible for the dermatitis following contact with the plant is primin.', 'The highest rate of sensitization is found in South East Asia.', 'C', 'Primin is the allergen found in the primula plant.
Peri-oral dermatitis to mangoes may occur in sensitized individuals.
Banana can cross react with latex.
The highest rate of sensitization to urushiol (responsible for poison ivy) is in North America.
Urushiol is soluble in rubber and therefore vinyl gloves should be worn for protection.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (10, 1, 'Which of the following tattoo pigments should be avoided in a patient with a known contact allergy tc cement?', 'Chromium.', 'Ferric hydrate.', 'Ferric oxide.', 'Manganese.', 'Mercury.', 'A', 'Chromium and cobalt are both present in cement.
Red tattoos can contain mercury, ferric hydrate and/or oxide.
Manganese is an inorganir. salt often found in purple tattoos.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (11, 1, 'Which of the following delayed reactions to tattoos is the commonest?', 'Allergic contact dermatitis.', 'Granulomatous.', 'Lichenoid.', 'Photo-induced.', 'Pseudoplymphomatous.', 'A', 'Reactions to tattoos can either be acute or delayed.
The majority of allergic contact dermatitis is related to red tattoos.
Red tattoos are either due to inorganic salts of metals such as mercury or cinnabar; or due to organic preparations such as sandalwood and brazilwood.
Patch testing will only be positive to the inorganic salts (i.e. mercury) and not to the organic salts due to the water insolubility of the latter.
Mercury pigment is also responsible for the delayed lichenoid reactions to tattoos but patch testing will be negative and the clinical and histological appearances will differ from those of allergic contact dermatitis.
In pseudolymphomas the lymphocytes are polyclonal as opposed to monoclonal in cutaneous lymphomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (12, 1, 'A patient is said to have chronic urticaria if the urticaria symptoms occur for more than 6 weeks. In addition, which of the following criteria should be fulfilled for urticaria to be classified as ''chronic''?', 'Urticaria occurring at least once a week off treatment.', 'Urticaria occurring at least twice a week off treatment.', 'Urticaria occurring at least twice a week on treatment.', 'Urticaria occurring at least three times a week off treatment.', 'Urticaria occurring at least three times a week on treatment.', 'B', 'The term ''chronic urticaria'' is applied to continuous urticaria occurring at least twice a week off treatment.
Urticaria occurring less frequently than this is called episodic (or recurrent).
Episodic urticaria is more likely to have an identifiable environmental trigger.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (13, 1, 'Physical urticarias are induced by an exogenous physical stimulus. Which of the following is the most common physical urticaria?', 'Cholinergic urticaria.', 'Delayed dermographism.', 'Delayed pressure urticaria.', 'Exercise-induced anaphylaxis.', 'Immediate symptomatic dermographism.', 'E', 'Immediate dermographism can be either simple or symptomatic.
Simple immediate dermographism occurs in about 5% of normal people.
It occurs in response to moderate stroking of the skin.
Symptomatic dermographism is the most common type of the physical urticarias.
It manifests as linear wheals at sites of scratching or friction.
Delayed dermographism often occurs after 30 mins of stroking the skin.
Delayed pressure urticaria is characterized by the development of deep erythematous swellings at sites of sustained pressure to the skin, 30 minutes to 12 hours later.
Cholinergic urticaria presents with multiple transient papular wheals 2-3 mm in diameter which occur within 15 minutes of physical exertion, hot baths, or emotional stress.
Exercise-induced anaphylaxis (EIA) and Food-and exercise-induced anaphylaxis (FEIA) are increasingly recognized syndromes.
In FEIA, angioedema and/or anaphylaxis occur within minutes of exercise if it follows either prior ingestion of a specific food (e.g. wheat), or sometimes within 4 hours of a heavy meal.
EIA is produced by exercise, but unlike cholinergic urticaria, not by an increase in core temperature induced by other means.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (14, 1, 'A 23-year man presents with severe facial dermatitis. The problem appeared during a recent camping holiday during which time he used safety matches on a daily basis. Type-4 hypersensitivity has likely developed to which of the following agents?', 'Phosphorus sesquisulfide.', 'DMDM hydantoin.', 'Imidazo!idinyl urea.', 'Diazolidinyl urea.', 'Quaternium 15.', 'A', 'Phosphorus sesquisulfide is found in match tips and friction strips of safety match boxes.
The other agents listed are formaldehyde releasers.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (15, 1, 'Skin prick testing in a 21-year-old female nurse confirms the clinical suspicion of latex allergy. Which of the following factors carries the greatest risk of mortality during any future anaphylactic attack?', 'Poorly-controlled asthma.', 'Poor concordance with prescribed anti-histamines.', 'Level of anti-latex serum IgE.', 'Strength of skin prick response to latex.', 'Family history of death during anaphylaxis.', 'A', 'Poorly controlled asthma is cited as the single most important risk factor for fatal anaphylaxis, especially in children and young adults, and can be an indication for self-in jectable adrenaline.
The life-saving intervention during anaphylaxis is adrenaline, delivered via the intramuscular route.
In adults the dose is 500 micrograms (0.S ml of 1:1000 adrenaline).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (16, 1, 'All of the following drugs can aggravate spontaneous urticaria except:', 'Aspirin.', 'Codeine phosphate.', 'Ibuprofen.', 'Montelukast.', 'Ramipril.', 'D', 'Several drugs may trigger or aggravate an attack of urticaria which include non-steroidal anti-inflammatory drugs, opiates and ACE-inhibitors.
Alcohol and stress can have a similar effect.
Montelukast is a leukotriene antagonist often used in addition to the anti-histamines in the treatment of urticaria.
ACE-inhibitors can also produce isolated angioedema in absence of any wheals due to the inhibition of the breakdown of bradykinin which is different from the urticarial
wheals triggered by ACE-inhibitors through histamine released from mast cells.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (17, 1, 'Which of the following food allergies are most likely to persist into adulthood when seen in childhood (particularly in the presence of atopic dermatitis)?', 'Egg.', 'Milk.', 'Peanuts.', 'Soya.', 'Wheat.', 'C', 'Food allergies are common in children with atopic background which in some children can worsen the eczema or be associated with episodes of urticaria on ingestion of the particular food item.
Allergies to peanuts, fish and shell fish are most likely to persist into adulthood.
Correct diagnosis of food allergy includes a detailed history complemented by skin prick testing and RAST testing in selected cases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (18, 1, 'You patch test a 37-year-old woman due to worsening of her eczema despite the use of several topical treatments and found that she has a ++ reaction to chlorocresol. Which of the following treatments can she use safely?', 'Setnovate Cream.', 'Dermovate Cream.', 'Dermovate Ointment.', 'Eumovate Cream.', 'Fucibet Cream.', 'C', 'Chlorocresol is a preservative found in many topical treatments including Eumovate, Betnovate an-:l Fucibet creams.
Dermovate cream does contain Chlorocresol but the ointment formula does not and is therefore safe to use in this particular case.
Hydrocortisone preparations do not contain Chlorocresol.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (19, 1, 'Which of the following conditions is an example of non-IgE-mediated reactions?', 'Colicky abdominal pain.', 'Eosinophilic oesophagitis.', 'Oral allergy syndrome.', 'Rhinitis.', 'Urticaria.', 'B', 'Eosinophilic oesophagitis is a recently recognised condition in which a large number of eosinophilsinfiltrate the oesophageal mucosa resulting in inflammation.
It has been increasingly found in patients with severe atopic disease and presents with dysphagia and reflux disease.
Colicky abdominal pain can be mediated through IgE to a food allergen in the absence of skin manifestations.
Oral allergy syndrome is a type of IgE-mediated reaction to certain food items, which often cross react with pollen allergy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (20, 1, 'Which of the following is the safest method of administering a drug to avoid sensitization?', 'Intramuscular.', 'Intravenous.', 'Oral.', 'Rectal.', 'Topical.', 'C', 'Oral administration of a drug is least likely to produce sensitization.
Intramuscular is the most likely parenteral way of eliciting drug sensitization.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (21, 1, 'A 26-year-old lady was referred for patch testing with persistent hand and facial eczema for the last year, which responds only partially to topical steroids and emollients. She had strong positive reactions to formaldehyde 1% on patch testing. Avoidance advice should be given for which of the following chemicals?', 'Epoxy resin.', 'Mercaptobenzothiazole.', 'Neomycin Sulphate.', 'Nickel sulphate.', 'Quaternium 15.', 'E', 'Patients who are allergic to formaldehyde should avoid the formaldehyde releas rs which include Quaternium 15, imidazolidinyl urea, DMDM Hydantoin and diazolidinyl urea.
Mercaptobenzothiazole is a rubber accelerator and reacts with carba mix and thiurams.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (22, 1, 'A 45-year-old woman presented with red, pruritic and swollen rash on the periorbital area, scalp and forehead. She had applied a hair dye 2 days before the onset of the rash. Patch testing demonstrates that she is allergic to para-phenyla''.Tline diamine (PPD). PPD can cross-react with the following:', 'Benzocaine.', 'Cobalt.', 'Formaldehyde.', 'Latex.', 'Neomycin sulphate.', 'A', 'PPD cross-reacts with several other para-amine groups such as PADA, benzocaine and azo-dyes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (23, 1, 'A 56-year-old man presented with bilateral eczema affecting the dorsal aspects o( his feet and has been present since he started wearing a pair of new shoes. It has been treated with topical steroids and ha was referred for patch testing. The most likely allergen in this case would be:', 'Formaldehyde 1%.', 'Neomycin sulphate.', 'Nickel sulphate.', 'Potassium dichromate.', 'Quaternium 15.', 'D', 'Potassium dichromate is often the c.ause of shoe allergy, as it is used for tanning of the leathers.
It can also be found in cement, and may often cross react with nickel sulphate and cobalt chloride.
Potassium dichromate can be an irritant, and if this is suspected, then testing to a lower concentration should be done.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (24, 1, 'A 35-year-old lady presented with three episodes of facial swelling, more noticeable in the peri-orbital area and swelling of both hands on one occasion. The swellings were more painful than pruritic, failed to respond to anti-histamines and a short course of oral corticosteroids. Her mother had similar episodes. Laboratory investigations revealed low C4 level, with normal Cl esterase inhibitor levels, but reduced functional Cl esterase levels. Her Clq antibodies were negative. The diagnosis here is:', 'Acquired angio-oedema.', 'Anaphylaxis.', 'Hereditary angio-oedema type 1.', 'Hereditary angio-oedema type 2.', 'Hereditary angio-oedema typ 3.', 'D', 'The history and clinical findings are suggestive of the diagnosis of angio-oedema.
In the absence of urticaria and the lack of response to anti-histamines, one should suspect hereditary or acquired angio-oedema.
Hereditary angio-oedemas are autosomal dominant disorders.
The hallmark of both types 1 and 2 isreduced C4 level.
In hereditary angio-oedema type 1, both Cl inhibitor levels as well as Cl functional levels are reduced.
In hereditary angio-oedema type 2, Cl esterase inhibitor levels can be normal or elevated, but the functional levels are reduced.
Type 3 hereditary angio-oedema is very rare. C4 and Cl esterase inhibitor levels are normal. This condition tends to be precipitated by oestrogens.
A family history and absence of Clq antibodies go against the diagnosis of acquired angio-oedema.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (25, 1, 'A 46-year-old lady with a chronic eczematous rash on the hands and legs was referred for patch testing by a colleague as she gives a clear history of worsening of her "eczema" following the use of certain products. Patch testing showed a strong reaction to budesonide. Which other steroid preparation should be avoided by the patient?', 'Betamethasone.', 'Clobetasolpropionate.', 'Clobetasone butyrate.', 'Hydrocortisone acetate.', 'Triamcinolone.', 'E', 'Corticosteroids belong to 4 different chemical classes (A, B, C and D) which do not correspond to the potency.
Budesonide belongs to group Band therefore all corticosteroids from this group need to be avoided.
Group A consists of hydrocortisone acetate and tixocortolpivalate.
Group C consists of betamethasone and dexamethasone.
Group 01 consists of clobetasolpropionate and clobetasone butyrate.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (26, 1, 'A 23-year-old woman complains of an eczematous eruption on her face, which has been present for over a year and tends to worsen in the summer. She has noticed that the application of some sunscreens worsen her facial eczema. The most appropriate investigation would be:', 'Patch testing.', 'Photo-patch testing.', 'RAST testing.', 'Skin prick testing.', 'Solar simulator provocation testing.', 'B', 'The history and symptoms are suggestive of a photo-contact allergy In which the combination of a chemical (e.g. sunscreen) and ultraviolet light leads to an allergic contact dermatitis.
Although patch testing would be Indicated to exclude any contact allergy to the per fume, preservative or any chemical in the sunscreen, photo-patch testing is the investigation needed in suspected photo-contact allergy.
Skin prick and RAST testing are useful in detecting type-1allergy and are therefore not applicable in this setting.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (27, 1, 'A 23-year-old nurse was referred for patch testing as she has noticed the development of an eczematous eruption following the use of plasters or handling any adhesives. The most likely allergen in this case is:', 'Benzocaine.', 'Colophony.', 'Neomycin sulphate.', 'Primin.', 'Propylene Glycol.', 'B', 'Colophony is found in adhesives and plasters.
Primin is the chemical in the plant Primula obconica.
Propylene glycol is a preservative found in many products.
Benzocaine is found in topical anaesthetics and may cross-react with PPD, PABA and sulphonamides.');

-- Dermatopathology
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (28, 2, 'A colleague has performed a biopsy for a blistering condition and you receive the histology report stating that there is a subepidermal blister with a dense neutrophilic infiltrate; no eosinophils are seen. Direct immunofluoresence is not available. Which of the following disorders is most likely to show this histological appearance?', 'Bullous erythema multiforme.', 'Bullous mastocytosis.', 'Bullous pemphigoid.', 'Epidermolysis bullosa acquisita.', 'Linear IgA disease.', 'E', 'The type of cell infiltrate together with the direct immunofluoresence can be very helpful in establishing a histological differential.
Subepidermal bullae with a predominantly neutrophilic infiltrate include: linear IgA disease, dermatitis herpetiformis, mucous membrane pemphigoid, bullous lupus erythematosus and Sweet''s syndrome.
Bullous mastocytosis has subepidermal bullae with mast cells.
Bullous pemphigoid has a predominantly eosinophilic infiltrate although a neutrophilic infiltrate may occur.
Erythema multiforme has a predominantly lymphocytic infiltrate.
Epidermolysis bullosa acquisita typically is cell-poor but some cases may have a neutrophilic infiltrate.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (29, 2, 'Which of the following alopecias has a predominantly neutrophilic infiltrate?', 'Alopecia areata.', 'Alopecia mucinosa.', 'Folliculitis Decalvans.', 'Lichen planopilaris.', 'Pseudopelade of Brocq.', 'C', 'A predominantly neutrophilic infiltrate is found in folliculitis decalvans and dissecting cellulitis of the scalp.
A lymphocytic infiltrate is found in lichen planopilaris, alopecia mucinosa, cutaneous lupus erythematosus, alopecia areata and pseudopelade of Brocq, though In the iatter there may be little inflammation present.
Early acne necrotica and erosive pustular dermatosis can have a mixed neutrophilic and lymphocytic infiltrate.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (30, 2, 'Which of the following stain positively for cytokeratin?', 'Carcinoma en cuirasse.', 'Epithelial tumours.', 'Lichenoid amyloidosis.', 'Macular amyloidosis.', 'All of the above.', 'E', 'Nodular amyloidosis is a rare primary cutaneous amyloidosis caused by the deposition of the AL amyloids produced by infiltrate of plasma cells. It is therefore often regarded as a plasmacytoma.
The other two types of cutaneous amyloidosis (macular and lichenoid) result from damaged keratinocytes; therefore they stain positively for cytokeratins.
Carcinoma en cuirasse is cutaneous metastasis from breast carcinoma, this like other epithelial tumours stain positively for cytokeratins.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (31, 2, 'In which of the following conditions is there typically no dyskeratosis at the suprabasal layer?', 'Darier''s disease.', 'Grover''s disease.', 'Hailey-Hailey disease.', 'Paraneoplastic pemphigus.', 'Warty dyskeratoma.', 'C', 'In Hailey-Hailey disease, there is acantholysis with usually little or no dyskeratosis.
Other acantholytic disorders in the absence of dyskeratosis include: pemphigus vulgaris, pemphigus vegetans and the acantholytic variant of actinic keratosis.
Conditions that can have both acontholysis and dyskeratosis include Darier''s disease, Grover''s disease, paraneoplastic pemphigus and warty dyskeratoma.
It is worth mentioning that in Hailey-Hailey disease, direct immunofluorescence is negative, which differentiates this condition from pemphigus vulgaris.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (32, 2, 'Mucin deposition is seen in which of the following cutaneous conditions?', 'Follicular mucinosis.', 'Pretibialmyxoedema.', 'Scleroedema.', 'Scleromyxoedema.', 'All of the above.', 'E', 'Other conditions in which mucin deposition is found include reticular erythematous mucinosis, lichen myxoedema, sclerodermoid GVHD, granuloma annulare, and lupus erythematosus.
Myxoid cyst is the commonest mucin deposition condition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (33, 2, 'Which of the following best represent corps ronds in Darier''s disease?', 'Acantholytic cells.', 'Apoptotic keratinocytes.', 'Oyskeratotic melanocytes.', 'Eosinophilic basal cells.', 'Inclusion cysts.', 'B', 'Histological features of Darier''s disease include:
Hyperkeratosis.
Focal dyskeratosis (premature, abnormal keratinisation of keratinocytes).
Eosinophilic dyskeratotic cells - corps ronds in the stratum spinosum, grains in the upper layers of the epidermis.
Corps ronds and grains correspond to apoptotic keratinocytes.
Suprabasal acantholysis and clefts.
Electron microscopy shows separation of the keratin filaments from the desmosomes and clumping of perinucleartonofilaments.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (34, 2, 'CD56 is a marker for which of the following cells?', 'B-Cells.', 'Macrophages.', 'Melanocytes.', 'Natural killer cells.', 'T-Cells.', 'D', 'CD56 is a helpful marker in the diagnosis of natural killer cells.
5100 and Melan-A are markers for melanocytes.
CD68 is a marker for macrophages.
CD20 and CD79a are markers for B-cells.
CO2, CD3, CD4, CDS, CD7 and CD8 are all markers ofT-cells.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (35, 2, 'A 60-year-old man presented with a relatively rapid onset of an erythematous-to-orange coloured eruption, which started initially on his face. It spread distally to involve most of his skin with some islands of normal skin on his trunk and limbs. Hi palms and soles have a shiny orange hue and subungual hyperkeratosis was noted. There is no personal or family history of psoriasis nor is there any joint involvement. What is the likely histological picture?', 'Absence of any hyperkeratosis.', 'Dense infiltrate of plasma cells extending deep into the reticular dermis.', 'Parakeratosis alternating with orthokeratosis in both the horizontal and vertical plains.', 'Superficial peri-vascular eosinophilic infiltrate.', 'Wedge-shaped hypergranulosis and the presence of dyskeratotic cells.', 'C', 'The clinical history here is of pityriasis rubra pilaris.
Histologically, this is characterised by alternating parakeratosis in the vertical and horizontal plains.
The main differential is psoriasis although the presence of islands of normal skin and the orange discolouration of the palms and soles favour the diagnosis of pityriasis rubra pilaris.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (36, 2, 'Parakeratosis is not a feature of which of the following?', 'Classical lichen planus.', 'Hypertrophic lichen planus.', 'Lichen planopilaris.', 'Pityriasis rubra pilaris.', 'Plaque psoriasis.', 'A', 'Classic lichen planus is characterised by its absence of parakeratosis and eosinophils.
Parakeratosis can be found in all of the other listeci conditions.
Eosinophils in the context of a lichenoid infiltrate should raise the suspicion of a drug aetiology.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (37, 2, 'Sarcoidal granulomas can be seen in all of the following except?', 'Crohn''s disease.', 'Granuloma annulare.', 'Granulomatous rosacea.', 'Sarcoidosis.', 'Silica foreign body reaction.', 'B', 'Sarcoidal granulomas are so-called "naked" granulomas, which are characterised by the absence of necrosis.
Sarcoidal granulomas can be seen in Melkerson-Rosenthal syndrome and foreign body reaction to silica, beryllium and tattoo granulomas.
Granuloma annulare is characterised histologically by necrobiotic granulomas, which may also be seen in necrobiosis lipoidica, rheumatoid nodule and necrobiotic xanthogranuloma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (38, 2, 'When differentiating between granuloma annulare and necrobiosis lipoidica histologically, which of the following statements is correct?', 'Abundant plasma cells may be seen in granuloma annulare.', 'Abundant plasma cells may be seen in necrobiosis lipoidica.', 'Necrobiosis lipoidica often has increased mucin deposition in the dermis.', 'Subcutaneousinvolvement is only a feature found in granuloma annulare.', 'The type of granuloma in granuloma annulare is sarcoidal.', 'B', 'Necrobiosis lipoidica can be differentiated from granuloma annulare by the abundance of plasma cells, sclerosis and the absence of mucin.
Whilst some cases of granuloma annulare can extend deep into the subcutis it is typically more superficilal than necrobiosis lipoidica and subcutaneous involvement is generally not a feature.
Both granuloma annulare and necrobiosis lipoidica are "necrobiotic" granulomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (39, 2, 'Spongiosis is least likely to be present in:', 'Id" reaction.', 'Contact dermatitis.', 'Cutaneous B cell lymphoma.', 'Pityriasis rosea.', 'Tinea corporis.', 'C', 'Although mild spongiosis can sometimes be found in cutaneous T celllymphoma, this is absent In cutaneous B cell lymphomas.
Other causes of spongiosis include pigmented purpuric dermatosis, erythroderma, Zoon''s balanitis, insect bites and the pre-bullous stage of immunobullous disorders.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (40, 2, 'CD30 positivity can be seen in all of the following except:', 'Anaplastic large cell lymphoma.', 'Lymphomatoid papulosis.', 'Marginal zone B cell lymphoma.', 'Scabies.', 'Transformed mycosis fungoides.', 'C', 'Other causes of CD30 positivity include chronic tick bites and Sezary syndrome.
In marginal zone B cell lymphoma the infiltrate is positive for CD20, CD79a and bcl-2; and is negative for bcl-6 (positive in follicle centre B cell lymphoma).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (41, 2, 'Perineural invasion is typically not observed In which of the following:', 'Desmoplastic trichoepithelioma.', 'Infiltrative type basal cell carcinoma.', 'Microcysticadnexal carcinoma.', 'Morphoeic type basal cell carcinoma.', 'Poorly-differentiated squamous cell carcinoma.', 'A', 'Perineural invasion portends a poorer prognosis with increased risk for recurrence and metastasis.
Desmoplastic trichoepithelioma is a rare follicular tumour that histologically is in the differential of microcysticadnexal carcinoma and morphoeic basal cell carcinoma but typically, perineural Invasion is not seen.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (42, 2, 'You diagnose a patient as having pemphigus foliaceous and send the histology specimen to the pathologist. If your clinical diagnosis is correct, he should identify the split at:', 'Basal layer.', 'Corneal layer.', 'Granular layer.', 'No split.', 'Sub-epidermal.', 'C', 'Most patients with pemphigus vulgaris have mucosal membrane erosions.
The blisters of pemphigus vulgaris develop in the deeper portion of the epidermis, just above the basal cell layer.
Patients with pemphlgus foliaceus have only cutaneous involvement without mucosal lesions, and the splits occur in the superficial part of the epidermis, mostly at the granular layer.
154');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (43, 2, 'In which of the following conditions can you see acantholysis in a skin biopsy?', 'Bullous pemphigoid.', 'Dermatitis herpetiformis.', 'Erythema Multiforme.', 'Grover''s disease (benign papular acantholytic dermatosis).', 'Lupus erythematosus.', 'D', 'Grover''s disease characteristicallyshows acantholysis(separation and rounding off of keratinocytes) with or without dyskeratosis (abnormal keratinisatlon).
Bullous Pemphigoid is a sub-epidermal disorder with eosinophils.
Dermatitis herpetiformis is a chronic blistering condition with a sub-epidermal split and neutrophilic microabscesses.
Erythema multiforme and lupus erythematosus show an interface (lichenoid) reaction pattern.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (44, 2, 'Which of the following cysts lacks a granular cell layer?', 'Dermoid cyst.', 'Epidermoid cyst.', 'Eruptive vellus hair cyst.', 'Follicular cyst.', 'Pilar (trichilemmal) cyst.', 'E', 'A pilar/ trichilemmal cyst lacks a granular cell layer and shows trichilemmal keratinlsation. The cyst is filled with homogenous, eosinophilic keratin unlike the laminated keratin found in an epidermoid cyst.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (45, 2, 'Microabscesses are seen in which of the following conditions?', 'Bullous pemphigoid, PLEVA, urticaria.', 'Dermatitis herpetiformis, mycosis fungoides, psoriasis.', 'Dermatitis herpetiformis, PLEVA, bullous pemphigoid.', 'Lupus, psoriasis, PLEVA.', 'Psoriasis, urticaria, lymphomatoid papulosis.', 'B', 'Dermatitis herpetiformis shows papillary neutrophilic microabscesses.
Psoriasis can show Munro''s microabscesses; these are collections of polymorphonuclear inflammatory cell infiltrate in the stratum cornem/ granular cell layer
Pautrier''s microabscesses are a localised epidermal collections of atypical lymphoid cells as seen in T-cell lymphoma and mycosis fungoides.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (46, 2, 'Which of the following antibodies is used to highlight pagetoid spread in superficial spreading malignant melanoma?', 'Alpha SMA.', 'CD30.', 'CD31.', 'Melan-A.', 'MNF116.', 'D', 'CD31is a vascular marker.
CD30 is a marker for lymphomatoid papulosis and anaplastic large cell lymphoma.
MNF116 is a broad spectrum cytokeratin.
Alpha SMA (Smooth Muscle Actin) is a marker of smooth muscle tumours and myoepithelial tumours.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (47, 2, 'A 50-year-old male presents with a papular skin rash. Histological examination reveals granulomatous inflammation in the dermis. Which of the following markers or special stains will help in the diagnosis:', 'Ber-EP4.', 'Melan-A.', 'PAS-Alcian Blue.', 'Verhoeff-Van Gieson Stain.', 'Zelehl Neelsen.', 'C', 'If there is granulmatous inflammation on skinbiopsy an infection should be excluded by performing special stains.
Mycobacterium tuberculosis can be visualised using the Ziehl-Neetsen stain.
PAS-Alcian blue is a pan-mucin combination.
Ber-EP4 and Melan-A are immunohistochemical antibodies.
Verhoeff-Van Gieson Stain is an elastic stain.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (48, 2, 'Select the marker most useful in differentiating basal cell carcinoma from basaloid squamous cell carcinoma:', 'Ber-EP4.', 'Carcino Embryonic Antigen (CEA).', 'HMB-45.', 'MelanA.', 'SlOO protein.', 'A', 'Ber-EP4 is positive In basal cell carcinoma and negative in squamous cell carcinoma.
Epithelial membrane antigen (EMA) is positive in squamous cellcaniinoma and negative in basal cell carcinoma.
CEA is a marker of ductal differentiation.
Sl00 protein, HMB-45 and Melan-A are metanocytic markers.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (49, 2, 'A 45-year-old female presented with an itchy erythematous rash. Histological examination revealed a spongiotic dermatitis with neutrophils in the superficial keratin layer. Which of the following markers or special stains will help in the diagnosis:', 'Ber-EP4.', 'Melan-A.', 'PASO.', 'Verhoeff-Van Gieson Stain.', 'Zeiehl Neelsen.', 'D', 'If you see neutrophil polymorphs in the stratum corneum always rule out a dermatophyte infection by performing a PASO(Periodic acid-Schiff stain) with diastase. Diastase removes glycogen in keratinocytes making the fungi easier to see.
With PASD the,ell walls of fungi stain magenta.
Alternative fungal stain is Grocott''s methenamine silver.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (50, 2, 'A 25-year-old female presents clinically with a changing mole. Skin biopsy reveals a lympho-histiocytic infiltrate with residual bland melanocytes. Which of the following is the most likely diagnosis?', 'Halo naevus.', 'Intradermal melanocytic naevus.', 'Malignant melanoma.', 'Reed''s naevus.', 'Spitz naevus.', 'A', 'A halo naevus on biopsy shows a dense lymphocytic Infiltrate at the dermo-epider mal junction which often obscures the melanocytic component.
Reed''s naevus is a variant of a Spitz''s naevus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (51, 2, 'A 44-year-old female presents with papules showing interface change and Civatte bodies on skin biopsy. What is your preferred diagnosis?', 'Bowen''s disease.', 'Eczema.', 'Lichen planus.', 'Psoriasis.', 'Sarcoidosis.', 'C', 'Lichen planus has a band of chronic inflammatory cells at the dermo-epidermal junction with numerous Civatte bodies.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (52, 2, 'Which of the following statements about psoriasis is false:', 'Histologically shows spongiform pustule of Kogoj.', 'Pustular form exists.', 'Sacrum affected.', 'Shows interface change on skin biopsy.', 'Vascular ectasia is seen with margination of neutrophils.', 'D', 'Interface change/ lichenoid reaction pattern is not seen in psoriasis.
A biopsy showingaombined reaction pattern such as Interface change with psoriasiform hyperplasia or psoriasiform hyperplasia with spongiosis etc. one should consider a drug reaction.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (53, 2, 'In which of the following is Miescher radial granuloma a histopathological feature?', 'Alpha-1-antitrypsin-deficienc-; panniculitis.', 'Cutaneous vasculitis.', 'Erythema nodosum.', 'Neutrophilic lobular panniculitis.', 'Tuberculosis.', 'C', 'Miescher radial granuloma is composed of small, round, well-defined nodular aggregations of small histiocytes which are radially arranged around a minute silt.
It is a characteristic hlstopathologic marker of erythema nodosum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (54, 2, 'A 26-year-old man of Jewish origin developed multiple shallow painful erosions In his mouth, multiple erosions on his trunk and limbs that start as flaccid bullae. Multiple swabs taken from the bullae and erosions showed commensals only. He has been referred for a diagno:.1ic biopsy, including immunofluorescence. Histologic.:al appearance of the biopsy would be:', 'A lichenoid reaction.', 'Acantholysis with intra-epidermal blistering.', 'Acanthosis and spongiosis throughout the epidermis.', 'Hyperkeratosis with acanthosis.', 'Sub-epidermal blistering and neutrophilic infiltrate.', 'B', 'The diagnosis is pemphigus vulgaris and therefore when blistering diseases are suspected, immunofluorescence samples should be taken.
In the case of pemphigus vulgaris, classic histological appearance would be of acantholysis and intra-epidermal blistering with positive immunofluorescence within the epidermis.
In pemphigus foliaceus, the split would be in the subcorneal layer with mucosal in volvement being typically absent.
The desmoglein is of type 1 in pemphlgus foliaceus and ispredominantly of type 3 in pemphigus vulgaris; however, desmoglein 1 can also be involved.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (55, 2, 'Which of the following is not an intra-epidermal blistering process?', 'Bullous amyloid.', 'Coma blisters.', 'Friction blisters.', 'Herpes simplex.', 'Palmoplantar pustulosis.', 'A', 'The split in bullous amyloidosis is subepidermal. The blistering in other listed disorders is intra-epidemal.
In coma, the blistering may be subepidermal.
The thick corneal layers of the palms and soles are responsible for the "intact" blisters in the epidermis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (56, 2, 'The blistering process in which of the following disorders is not subcorneal?', 'Pemphigus erythematosus.', 'Pemphigus foliaceous.', 'Staphylococcal scalded skin syndrome.', 'Streptococcal toxic syndrome.', 'Toxic epidermal necrolysis.', 'E', 'Toxic epidermal necrolysis results in full thickness epidermal necrosis.
Other conditions which result in subcorneal blistering include impetigo, subcorneal pustular dermatosis, infantile acropustulosis, erythema toxicumneonatorum, acute generalized exanthematous pustulosis and miliaria crystallina.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (57, 2, 'Which of the following conditions is not a true granulomatous disorder?', 'Fisr tank granuloma.', 'Granuloma annulare.', 'Granuloma faciale.', 'Necrobiotic xanthogranuloma.', 'Sarcoidosis.', 'C', 'Granuloma faciale typically shows a vasculitic histology with no granulomas and the term "granuloma" here is therefore misleading.
A high-index of suspicion may be required to diagnose:1sh tank granuloma and if suspected, skin biopsy should be sent for mycobacterial cultures which can take several weeks.');

-- Dermoscopy
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (58, 3, 'You examine a lesion with a dermatoscope and find several maple leaf-like areas and arborising vessels. Which of the following do the above features best describe?', 'Amelanotic melanoma.', 'Basal cell carcinoma.', 'Melanoma.', 'Seborrhoeic keratosis.', 'Squamous cell carcinoma in situ.', 'B', 'Other desmoplastic features of basal cell carcinoma (BCC) include blue-gray blotches, ovoid nests and globules in pigmented BCC, pink white shiny areas and spoke wheels.
131');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (59, 3, 'Blue-grey ovoid nests and spoke wheeled pigmentation are evident on dermoscopic examination of a lesion. To which of the following do these features most likely relate?', 'Malignant melanoma.', 'Seborrhoeic keratosis.', 'Junctional melanocytic naevus.', 'Pigmented basal cell carcinoma.', 'Blue naevus.', 'D', 'Other dermoscopic features of pigmented basal cell carcinomas, relating to melanin inclusion, may include: Absence of a true pigment network, blue-grey dots and globules, homogenous pigmented areas, peripheral leaf-like structures and specks of brown and grey pigment.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (60, 3, 'Which of the following would you not expect to see on dermatoscopic examination of a seborrhoeic keratosis?', 'Cerebriform pattern.', 'Pigment network.', 'Fingerprint structures.', 'Hairpin vessels.', 'Moth-eaten border.', 'B', 'Other dermoscopic features of seborrhoeic keratoses include: Comedo-like openings, homogenous pigmentation and milia-like cysts.
Presence of a pigment network is an atypical feature and raises the suspicion of a seborrhoeic keratosis-like (or verrucous) malignant melanoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (61, 3, 'A 65-year-old lady attends your clinic for review of an itchy erythematous plaque over her right upper chest. Examination under dermoscopy reveals a scattered grey granular pattern. What is the most likely diagnosis?', 'Lichenoid keratosis.', 'Pigmented basal cell carcinoma.', 'Lichen simplex.', 'Malignant melanoma in-situ.', 'Squamous cell carcinoma in-situ.', 'A', 'Lichenoid keratosis is a benign lesion that is thought to develop from such lesions as a regressing solar lentigo or seborrhoeic keratosis.
They typically occur as a solitary lesion on the upper trunk and can resemble superficial basal cell crtrcinoma, Bowen''s disease or even malignant melanoma.
The presence of a grey granular pattern under dermoscopy is a clue to diagnosisut alone is not enough to exclude more serious differentials.
Histological features include acanthosis and a band-like lichenoid lymphocytic infiltrate.
Parakeratosis may also be seen,serving as a distinguishingfeature from lichen planus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (62, 3, 'A 1.9-year-old patient is referred for review of a lesion overlying her posterior shoulder. Her attention was first drawn to this when planning a tattoo of two intertwined serpents at the site. Examination under dermoscopy reveals streaks of pigmentation forming a peripheral starburst pattern. What is the most probable diagnosis?', 'Naevus of Ito.', 'Blue naevus.', 'Spitz naevus.', 'Superficial spreading malignant melanoma.', 'Naevus of Oto.', 'C', 'Spitz or Reed naevi are relatively uncommon, mostly appear during childhood or early adult life.
They may be pigmented or non-pigmented.
The pigmented variety demonstrates a classic starburst pattern.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (63, 3, 'Which of the following vascular patterns would you expect on dermoscopic examination of a dear cell acanthoma?', 'Polymorphous vessels.', 'Uniform lacunes.', 'Arborizing telangiectasia.', 'Dot vessels lined up in a string of pearls.', 'Glomerular vessels.', 'D', 'Clear cell acanthoma (or Degas acanthoma) is a benign epithelial skin tumour.
Typical presentation is with a solitary shiny pink nodule, with wafer-like scaling around its edge.
Most common sites are the lower legs.
Histology demonstrates epidermal accumulation of clear glycogen-containing cells.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (64, 3, 'A 60-year-old man, with skin phenotype 3, is referred for urgent review of a solitary plaque on his left shin which he first noticed after a weekend gardening. Dermoscopy shows a central thrombosedlacune. Surrounding this are multiple smaller thrombosed and purple lacunes, over which there is a blue-white veil. What is the most likely diagnosis?', 'Haemangioma.', 'Malignant melanoma.', 'Angiokeratoma.', 'Lymphangioma.', 'Ink spot lentigo.', 'C', 'Sporadic angiokeratoma typically present as solitary dark red to purple plaques, often with a scaly surface
They are composed of dilated capillaries and are often only come to medical attention after trauma leads to bleeding, thrombosis and sudden darkening.');

-- Formulary & Systemic Therapy
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (65, 5, 'A 30-year-old, 24-weeks pregnant patient has severe atopic eczema not responding to topical emollients alone. Which of the following drugs is an absolute contra-indication in pregnancy?', 'Chlorphenamine.', 'Ciclosporin.', 'Mycophenolate mofetil.', 'Prednisolone.', 'Topical clobetasone butyrate.', 'C', 'Although generally systemic treatments should be avoided in pregnancy if possible, all the above, with the exception of mycophenolate mofetil, can be used in pregnancy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (66, 5, 'Rifampicin may be an effective treatment for which of the following types of pruritus:', 'Brachio-radial.', 'Cholestatic.', 'Lymphoproliferative.', 'Neurop.ithic.', 'Uraemic.', 'B', 'Rifampicin is an inducer of hepatic enzymes and can be effective in the treatmer.t of cholestatic pruritus.
Other treatments include cholestyramine and opioid receptor antagonists such as naltrexone.
UVB phototherapy, naltrexone and gabapentin can be used in uraemic pruritus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (67, 5, 'A patient with severe psoriasis who is currently well-controlled on the anti- TNF biologic Etanercept (Enbrel) is planning to travel abroad and has asked your advice with regards to immunisations. Which vaccine is safe in this context?', 'Measles.', 'Pneumococcal.', 'Typhoid.', 'Varicella.', 'Yellow fever.', 'B', 'Knowledge about vaccines in immunosuppressed patients is important as more pa tients are receiving anti-TNF therapy in dermatology.
Live vaccines must be avoided in patients who are receiving therapy with anti-TNF and these include: measles, mumps, rubella, small pox, yellow fever, dengue fever, BCG, polio, rabies, typhoid and varicella.
Pneumococcal vaccine can be used safely in this patient.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (68, 5, 'The mortality related to methotrexate has been primarily attributed to:', 'Acute liver failure.', 'Bone marrow suppression.', 'Liver cirrhosis.', 'Oral ulcerations.', 'Renal failure.', 'B', 'Idiosyncratic reactions can occur with any dose and are therefore dose-independent.
Oral ulcers may indicate methotrexate toxicity or folate deficiency.
Methotrexate should be used with caution in renal impairment.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (69, 5, 'A 58-year-old man complains of blurring of vision. He has been using a medication for hyperhidrosis. Which of the following is the most likely cause of his symptoms?', 'Aluminum chloride.', 'Botulinum toxin.', 'Glutaraldehyde.', 'Glycopyrrolate.', 'Potassium permanganate.', 'D', 'Glycopyrrolate is an anticholinergic agent which can be used in the treatment of compensatory, craniofacial, and diabetic gustatory hyperhidrosis.
It acts by preventing the acetylcholine-induced stimulation of the sweat gland receptors.
Its inability to cross the blood brain barrier, results in fewer side effects.
Systemically administered anticholinergic agents may result in dry mouth, visual disturbances, urinary retention and urgency, flushing and constipation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (70, 5, 'A 56-year-old patient is commenced on ciclosporin for psoriasis. Which of the following is true regarding monitoring of ciclosporin therapy?', 'Ciclosporin dose should be reduced if serum creatinine increases by 30% above the baseline value.', 'Cliclosporinbloavailablllty remains uniform irrespective of the brand used.', 'GFR measurement should be carried out every 6 months for patients on long term ciclosporin.', 'Intake of grapefruit Juice should be encouraged.', 'Rise in blood pressure always necessitates additional drug therapy.', 'A', 'Ciclosporin dose should be reduced if serum creatinine increases by 30% above the baseline value (even if this increase is within the laboratory normal range).
Grapefruit juice interferes with gut cytochrome P-450 enzymes, which are important in metabolizing ciclosporin and therefore it should not beadministered simultaneously with ciclosporin.
Only a minority of patients (5-12%) develop new-onset hypertension during short course ciclosporin therapy, and the overwhelming majority of these cases respond to dose reduction and/or anti-hypertensive medication.
As ciclosporin nephropathy is closely related to duration of therapy, GFR should be assessed annually In patients receiving long-term continuous ciclosporin treatr:,ent.
Ciclosporin has formulation-dependent bioavailability with a wide inter-individual variability in absorption. Appropriate brand of ciclosporin should be consistently dispensed.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (71, 5, 'Which of the following drugs is implicated in the causation of ingrown toe nails?', 'Ciclosporin.', 'Clofazamine.', 'Dapsone.', 'Isotretinoin.', 'Mycophenolate.', 'D', 'Ingrowing toenails can be caused by prescribed medications including retinoids, in dinavir and methotrexate.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (72, 5, 'In order to be "eligible" for funding to use biological therapy In severe chronic plaque psoriasis the patient must have tried and failed at least 2 systemic therapies and have:', 'DLQI <10 and PASI >10.', 'DLQI > 10 and PASI <10,', 'DLQI > 20 and PASI < 10.', 'DLQI and PASI both are equal to or more than 10.', 'DLQI and PASI both less than 10.', 'D', 'The current guidelines state that in order to be eligible for biological therapy a patient must have severe disease and have a DLQI and a PASI equal to or greater than 10. Intolerance to or lack of response to systemic agents is?.n additional requirement. The NICE guidelines suggest that infliximab can be considered when the PASI is equal to or greater than 20 and the DLQI is over 18.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (73, 5, 'Which of the following biological therapies for psoriasis is administered intravenously?', 'Adalimumab.', 'Efalizumab.', 'Etanercept.', 'Infliximab.', 'Ustekinumab.', 'D', 'infliximab is administered intravenously as a dose of 5 mg/kg at weeks 0, 2, 6 and every 8 weeks thereafter.
Dosing of ustekinumab is also weight-based: (i) 45 mg for patients under 100 kg, and, (ii)90 mg for those over 100 kg. It is administered subcutaneously.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (74, 5, 'With regards to anti-TNFtherapy in severe psoriasis in patients with congestive cardiac failure, the current British Association of Dermatologists recommendations are:', 'Avoidance in any New York Heart Association (NYHA) class.', 'Avoidance in class IV only.', 'Avoidance in NYHA class II and above.', 'Avoidance in NYHA class III and IV.', 'Safe to use with no risks in patients with cardiac failure.', 'D', 'Anti-TNF therapy should be avoided in patients with New York Heart Association (NYHA) class III and IV congestive cardiac failure.
Avoidance should also include patients with NYHA class I or II who have an ejection fraction of less than 50%.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (75, 5, 'Acitretin is a retinoid that can be used in psoriasis. Which of the following statements regarding this drug is true?', 'Combination with methotrexate increases the risk of hepatotoxicity.', 'Combination with tetracyclines increases the risk of benign intracranial hypertension.', 'Contraception should be continued for 2-3 years following discontinuation.', 'Hyperlipidaemia is one of the possible side-effects.', 'All of the above.', 'E', 'Acitretin can be used In psoriasis, Darier''s disease, keratodermas, palmo-plantar pustulosis, hyperkeratotic hand eczema, and severe congenital ichthyoses.
The drug isvery teratogenic and should not be considered in women of child-bearing age. In extreme cases when it has to be used in this group, contraception must be ccntinued for at least 2-3 years following discontinuation of the drug.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (76, 5, 'Antibodies are most likely to be formed against which of the following drugs?', 'Adalimumab.', 'Etanercept.', 'Infliximab.', 'Methotrexate.', 'Ustekinumab.', 'C', 'infliximab is a chimeric monoclonal antibody and therefore there is a high risk of developing antibodies against it in a proportion of patients. Reduced efficacy ran result due to the neutralising antibodies.
Antibodies can also be produced again-st adalimumab but to a lesser extent than infliximab.
Methotrex.ite can be combined with infliximab in cases where there is antibody production leading to loss of efficacy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (77, 5, 'Based on available evidence, which of the following is considered the best option for treating morphea?', 'Ciclosporin.', 'Methotrexate.', 'Mycophenolate mofetil.', 'UVB phototherapy.', 'PUVA.', 'B', 'Methotrexate has the best evidence and should be the first-line treatment of choice in cases of generalized or accelerated morphea.
It can be combined with methyl prednisolone or preciinlsolone; the combmation has been shown to be very effective in cases of accelerated morphea.
Topical steroids, tacrolimus ointment or phototherapy can be used for localised morphea.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (78, 5, 'The combination of ciclosporin and statin therapy leads to increased levels oi statin which In turn can lead to statin-lnduced myopathy. Which of the following statins is however safe to combin with ciclosporin due to a different metabolic pathway?', 'Atorvastatin & Simvastatin.', 'Atorvastatin.', 'Pravastatin.', 'Rosuvastatin.', 'Simvastatin.', 'C', 'This is an important reaction that dermatologists should be aware of as ciclosporin is metabolised through the CYP3A4 pathway.
Most statins, with the exception of pravastatin, are metabolised through the same metabolic pathway. Hence, this is the only statin that can be safely combined with ciclosporin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (79, 5, 'Which of the following drugs is an absolute contra-indication in patients with active hepatitis B?', 'Acitretin.', 'Adalimumab.', 'Ciclosporin.', 'Hydroxychloroquine.', 'Usetkinumab.', 'C', 'The use of immunosuppressive therapy should be avoided in patients with active hepatitis B and advice from the hepatologist should be sought.
Ciclosporin is an absolute contra-indication in active hepatitis B.
,.., Anti-TNF therapy can be used provided that adequate anti-viral therapy has been established.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (80, 5, 'A 45-year-old patient has severe pemphigus vulgaris. Which one of the drugs used to treat pemphigus has sterility as a side effect?', 'Azathioprine.', 'Corticosteroids.', 'Cyclophosphamide.', 'Immunoglobulins.', 'Rituximab.', 'C', 'Cyclophosphamide is given at a dose of 1-3 mg/kg/day (usually 50-200 mg/day) and its major side effects are haemorrhagic cystitis, sterility and leukopenia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (81, 5, 'A 40-year-old man has been diagnosed with IgA pemphigus. Which of the following is the drug of choice in this condition?', 'Ciclosporin.', 'Colchicine.', 'Dapsone.', 'Methotrexate.', 'Oral Prednisolone.', 'C', ',., Dapsone is the drug of choice in IgA pemphigus, although colchicine can be used in some c.ases.
,., A clinical response usually occurs within 24-48 hours.
,., Alternatively, sulphapyrldlne or acitretin can be used.
,., Low-to medium-dose prednisone, or photochemotherapy (PUVA) are other alternatives.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (82, 5, 'Which of the following medications is contraindicated in patients with known soya allergy?', 'Isotretinoin.', 'Acitretin.', 'Ciclosporin.', 'Bexarotene.', 'Methotrexate.', 'A', 'Allergy to soya is a contraindication to isotretinoin, as some brands of isotretinoin contain soya oil.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (83, 5, 'Which of the following statements regarding topical retinoidsis incorrect?', 'Their use is associated with increased resistance to the P.acnes bacteria.', 'They can down-regulate tyrosine synthesis', 'They can exhibit an effect on micro-comedones.', 'They can reduce post-inflammatory hyperpigmentation.', 'Stimulation of collagen synthesis may occur.', 'A', 'Topical retinoids are widely used in the treatment of acne due to their effect on comedogenesis, increased collagen synthesis and reduction of post-inflammatory hyperpigmentation.
They can be used in the treatment of melasma due to down-regulation of the tyrosine synthesis which is essential for melanin production.
Its use does not lead to increased resistance to the P.acnes to antibiotics.
Unlicensed uses of topical retinoids include treating photo damaged skin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (84, 5, 'Which of the following can be used as a depigmenting agent In the treatment o''f vitiligo?', 'Dibenzyl ether of hydroquinone.', 'Monobenzyl ether of hydroquinone.', 'Pentabenzyl ether of hydroquinone.', 'Tetrabenzyl ether of hydroquinone.', 'Tribenzyl ether of hydroquinone.', 'B', 'Monobenzyl ether of hydroquinone (Monobenzone) is used for depigmentingresid· ual normal skin in patients with extensive vitiligo.
It is a phenolic toxin that destroys epidermal melanocytes.
it is available as a 20 percent cream.
Allergic and irritant reactions may occur.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (85, 5, 'In the United Kingdom, imiquimod cream (aldara) is not licensed for treatment of which of the following conditions?', 'Actinic keratoses.', 'Bowen''s disease.', 'Genital warts.', 'Superficial basal cell carcinoma.', 'None of the above.', 'B', 'imiquimod cream can be used for Bowen''s disease; however this is an unlicensed treatment in this condition.
Its current licence is for genital warts, superficial basal cell carcinoma and actinic keratoses.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (86, 5, 'A 36-year-old man has been treated successfully with a systemic agent for his blistering disorder and reports a gradual weakness of his right foot, resulting in him trippingover several times. On examination, there was demonstrable motor weakness, with intact sensation. Which of the following drugs is most likely to be implicated in this case?', 'Dapsone.', 'Diclofenac.', 'Hydroxychloroquine.', 'Intravenous immunoglobulins.', 'Mycophenolate Mofetil.', 'A', 'Dapsone is a11 antagonist of dihydropteroate synthetase and prevents the formation of folic acid.
It can be used in several blistering disorders, and motor-neuropathy is one of its possible long-term complications.
Hydroxychloroquine can cause retinopathy and this needs to be monitored for regularly.
Mepacrine is an anti-malarial drug, often used in conjunction with or as an alternative to hydroxychloroquine but does not cause ocular toxicity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (87, 5, 'A 45-year-old man is admitted with severe desquamation of his skin following ingestion of phenytoin for epilepsy. Your consultant decides to start him on intravenous immunoglobulin. In the United Kingdom, intravenous immunoglobulins are licensed for use in which of the following conditions?', 'Bullous pemphigoid.', 'Erythema multiforme.', 'Kawasaki disease.', 'Linear IgA disease.', 'Toxic epidermal necrolysis.', 'C', 'Intravenous immunoglobulins are used in several de;matological diseases, which include toxic epidermal necrolysis, pemphigus vulgaris, dermatomyositis and Kawasaki disease.
Currently, it only has a licence for use in Kawasaki disease among the dermatological conditions.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (88, 5, 'A 45-year-old patient is commenced on a new systemic medication. He returns 2 weeks later complaining of breathlessness and appears cyanosed. A blood film demonstrates methaemoglobulinaemia. Which of the following drugs used in certain dermatological conditions can cause methaemoglobulinaemia?', 'Ciclosporin.', 'Dapsone.', 'Fumaric acid esters.', 'Methotrexate.', 'Mycophenolate mofetil.', 'B', 'Oapsone can cause haemclysis and methaemoglobulinaemia.
Any patient who becomes breathless or cyanosed on dapsone must have his MetHb levels checked.
Methotrexate can cause pulmonary fibrosis (most commonly seen in patients with rheumatoid arthritis) and drug-induced pneumonitis, but can not cause methaemoglobulinaemia.
Fumaric acid esters can cause gastro-intestinal symptoms, flushing and a drop in the lymphocyte count.
Ciclosporin can cause hypertension and renal impairment and these should be regularly monitored.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (89, 5, 'Which of the following antibiotics in the treatment of acne is associated with the least resistance?', 'Doxycycline.', 'Erythromycin.', 'Minocycline.', 'Oxytetracycline.', 'Tetracycline.', 'C', 'Antibiotic resistance is a growing problem in the treatment of acne.
It should be suspected in patients unresponsive to appropriate antibiotic therapy after 6 weeks of treatment.
Propionibacterium acne resistance has been documented with all macrolides and tetracyclines used in the treatment of acne.
Overall resistance is the highest with erythromycin and lowest with minocycline.
Measures to avoid antibiotic resistance should include avoidance of antibiotic monotherapy, limiting long-term use of antibiotics, and combining antibiotics with benzyl peroxide.
Recent studies do not show any benefit of using minocycline over other tetracyclines.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (90, 5, 'A 27-year-old woman with a long history of chronic plaque psoriasis has been suffering from an exacerbation of the disease with plaques covering approximately 40¼ of her body surface area. Her previous therapies included topical corticosteroids and phototherapy. She is due to get married in 2 months and is requesting a treatment that can rapidly help clear her psoriasis before her weddi1,g. She is otherwise well with r10 co-morbidities. The most appropriate systemic drug in the absence of any contra-indications would be:', 'Acitretin.', 'Ciclosporin.', 'Etanercept.', 'Methotrexate.', 'Prednisolone.', 'B', 'Ciclosporin can induce rapid clearance as it acts quicker than most other systemic agents in psoriasis.
Main side-effects/complications that require regular monitoring are renal impairment and hypertension.
Prednisolone should not be used in psoriasis to avoid inducing pustular psoriasis following withdrawal.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (91, 5, 'Which of the following is not a recognized side-effect of the Epidermal Growth Factor Receptor (EGFR) antagonists?', 'Acneiform eruptions.', 'Erythema nodosum.', 'Paronychia.', 'Pyogenic granulomas.', 'Xerosis.', 'B', 'The commonest side-effect of EGFRls is the papulo-pustular acneiform eruption; however comedones are typically absent.
Pyogenic granulomas and paronychiae are typically late-occurring side-effects (> 3 months).
Erythema nodosum can occur following certain drugs with oral contraceptives being the commonest.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (92, 5, 'A 45-year-old patient is commenced on methotrexat for his psoriasis. The action mode of methotrexate is by binding to:', 'Dihydrofolate reductase.', 'Inosine monophosphate dehydrogenase.', 'Interleukin-1.', 'Interleukin-10.', 'Thiopurinemethyltransferase.', 'A', 'Binding of methotrexate to dihdrofolate reductase results in the inhibition of the intracellular reduction of folate to tetrahydrofolate which in turn blocks the production of thymidine and purine biosynthesis.
The above process also leads to the inhibition of adhesion molecules and cytokines.
inosine monophosphate dehydrogenase is blocked by the drug mycophenolate mofetil which leads to the inhibition of the "de novo" biosynthesis of purines, leading to a reduction in DNA synthesis, nitric oxide production and adhesion molecules.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (93, 5, 'You refer a patient on long-term hydroxychloroquine to an ophthalmologist as he complains of some visual disturbances. Long-term, high doses of hydroxychloroquine can give rise to which ocular pathology?', 'Blepharitis.', 'Cataracts.', 'Conjunctivitis.', 'Glaucoma.', 'Retinopathy.', 'E', 'The anti-malarial drug hydroxychloroquine is useful in cutaneous lupus.
Ocular toxicity can occur, particularly if doses exceed 6.5 mg/kg daily.
Regular ophthalmic examination which includes Amsler chart reading is mandatory.
Mepacrine, a drug often used in conjunction with or as a substitute of hydroxychloroquine does not cause ocular toxicity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (94, 5, 'You plan to commence your patient on ciclosporin. The mode of action of ciclosporin is through binding to:', 'Cd20.', 'Cyclophilin-A.', 'Dihydrofolate reductase.', 'Dihydropteroate synthetase.', 'Inosine monophosphate dehydrogenase.', 'B', 'The binding-complex of ciclosporin and cyclophilin-A inhibits calcineurin which in turn inhibits the migration of transcription factor NFAT (nuclear factor of activated Tcells) into the cell nucleusresulting in the inhibition of IL-2.
inosine monophosphate dehydrogenase is Inhibited by mycophenolate mofetil.
Methotrexate binds to dihydrofolate reductase leading to the Inhibition of thymldine and purine biosynthesis.
CD20 is targeted by the relatively new monoclonal antibody drug rituximab which has been used in lupus and pemphigus.
Dihydropteroate synthetase is blocked by dapsone which prevents the formation of folic acid.');

-- General Dermatology
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (95, 6, 'Which of the following pregnancy-related dermatoses is least likely to recur in subsequent pregnancies?', 'Pruritic urticarial papules and plaques of pregnancy (PUPP).', 'Atopic eruption of pregnancy.', 'Intrahepatic cholestasis of pregnancy.', 'Pemphigoid gestationis.', 'B and C.', 'A', 'PUPP which is also called polymorphic eruption of pregnancy occurs in the first pregnancy and seldom recurs in subsequent pregnancies.
Both pemphigoid gestationis and intrahepatic cholestasis of pregnancy can recur with subsequent pregnancies or with the use of oral contraceptives.
Atopic eruption of pregnancy can be the first manifestation of atopic disease in a susceptible person.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (96, 6, 'A 24-year-old woman presents with excessive facial hair and acne. There is a history of menstrual irregularities as well. Which of the following is the most likely diagnosis?', 'Adrenal tumour.', 'Congenital adrenal hyperplasia.', 'Diabetes mellitus.', 'Hyperprolactinaemia.', 'Polycystic ovarian syndrome.', 'E', 'Hirsutism is defined as excessive terminal hair growth in women in the androge,1-sensitive areas.
Polycystic ovarian syndrome is the commonest endocrinological cause for:1irsutism.
Diagnosis of polycystic ovarian syndrome requires two out of three of the following:
positive imaging, menstrual abnormalities and signs of hyperandrogenism, which can be remembered by the acronym SAHA, that stands for Seborrohea, Acne, Hirsut,sm and Androgenetic alopecia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (97, 6, 'Which of the following drugs is most likely to cause drug-induced linear IgA disease?', 'Captopril.', 'Lithium.', 'Penicillamine.', 'Rifampicin.', 'Vancomycin.', 'E', 'Vancomycin is the most common cause of drug induced linear IgA disease.
Penicillamine can cause both drug-induced pemphigus and mucous membrane pemphigoid, and long-term use can result in elastosis perforans serpiginosa, in which elastic fibres extrude through the epidermis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (98, 6, 'Which of the following is not a feature of drug rash (or reaction) with eosinophilia and systemic symptoms (DRESS) syndrome?', 'Fever.', 'Lymphadenopathy.', 'Mucosal ulceration.', 'Oedema of the face.', 'Peripheral eosinophilia.', 'C', 'DRESS is a serious drugeruption that typically presents with an exanthematous eruption with fever, lymphadenopathy, oedema of the face, peripheral eosinophilia, atypical lymphocytes and visceral involvement.
Liver and kidney involvement may be seen.
The latency period may take anywhere between 1-8 weeks, although this may be much earlier with re-exposure to the drug.
A pustular eruption is not a feature of DRESS syndrome and is seen in acute generalized exanthematous pustulosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (99, 6, 'A 20-year-old man presents with acute onset of severe aciie associated with malaise, fever and arthralgia. Which of the following is the most likely diagnosis?', 'Acne conglobata.', 'Acne fulminans.', 'Dissecting cellulitis of the scalp.', 'Hidradenitissuppurativa.', 'Steatocystoma multiplex.', 'B', 'Acne conglobata is a specific variant of acne characterised by large comedones with multiple openings, predominantly on the face and back.
A positive family history is often found and this should not be confused with acne fulminans which is a severe form of acne that tends to affect young males and presents with malaise, fever, arthralgia and liver involvement.
Unlike acne conglobata, haemorrhagic crusted ulcerative lesion can be found in acne fulminans.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (100, 6, 'Which of the following antibodies is most specific for systemic lupus erythematosus?', 'Anti-Jo-1 antibody.', 'Anti-Mi2 antibody.', 'Anti-nuclear antibody.', 'Anti-RNP antibody.', 'Anti-Sm antibody.', 'E', 'In systemic lupus erythematosus (SLE) anti-nuclear antibody is positive in the majority of patients. Immunological abnormalities including the finding of anti-Sm and anti-dsDNA antibodies form one of the criteria for diagnosis of SLE.
Anti-Sm antibodies are specific to SLE and are found in around 20-30% of patients.
Anti-ds-DNA antibodies are also specific to this condition (also in "lupoid" hepatitis) and the titres may correlate with both renal involvement and disease activity (unlike the anti-Sm antibody).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (101, 6, 'Which of the following is associated with an abnormal lipid profile?', 'Eruptive xanthomata.', 'Palrnarxanthoma.', 'Tuberous xanthomata.', 'Xanthelasmata.', 'All of the above.', 'A', 'With the exception of xanthomata disseminatum, and verucciformxanthomas, all other types of xanthomas are associated with an abnormal lipid profile.
Eruptive xanthomata are often associated with elevated triglycerides as opposed to increased cholesterol levels in the other forms of xanthomata.
Xanthomata disseminatum is a histiocytic disorder.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (102, 6, 'A 40-year-old man presents with fever and red/purple tumid plaque 011the face for 3 days. A skin biopsy shows papillary dermal oedema and a dense, diffuse neutrophilic infiltrate in the reticular dermis. What is the most common malignancy associated with this presentation?', 'Essential thrombocythaemia.', 'Lymphocytic leukaemia.', 'Myelogenous leukaemia.', 'Non Hodgkins lymphoma.', 'Polycythaemia.', 'C', 'Ac1Jte febrile neutrophilic dermatosis (Sweet''s syndrome), is a reactive process.
Abrupt onset of tender, red-to-purple papules coalesce to form plaques.
Commonest sites include upper extremities, face, or neck.
The rash is accompanied by fever and peripheral neutrophilia.
Causes include hematopoietic malignancies (most commonly acute myeloid leukemia), non-hematologic malignancies; e.g. genitourinary, breast, and gastrointestinal cancers, infectious most often involving the upper respiratory tract, drugs and systemic illnesses.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (103, 6, 'A 30-year-old woman developed erythematous patches and plaques on her trunk. These were associated with mild pruritus and progressed to become indurated and oedematous with few plaques developing blisters. She reported that previous patches and plaques resolved after several weeks leaving a green hue. She had no mucosal Involvement and laboratory investigations showed marked eosinophilia. A skin biopsy showed oedema, flame figures and an eosinophilic dermal infiltrate. Direct immunofluoresence was negative. The diagnosis is:', 'Dermatitis herpetiformis.', 'Eosinophilic cellulitis.', 'Pemphigoid gestationis.', 'Pemphlgus vulgaris.', 'Urticarial vasculitis.', 'B', 'The history, clinical findings, histology and the presenci= of an eosinophilia fit with the diagnosis of eosinophilic cellulitis (Well''s syndrome).
The condition can be associated with infections, ulcerative colitis, lymphoma and leukaemia.
Localized areas of eosinophilic cellulitis have been reported at injection sites of anti TNF drugs.
Topical or systemic corticosteroids are the treatment of choice.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (104, 6, 'Of which of the following conditions is livedo reticularis not a feature?', 'Anti-phospholipid syndrome.', 'Cholestrol crystal embolization.', 'Cryoglobulinaemia.', 'Kawasaki''s disease.', 'Systemic lupus erythematosus.', 'D', 'Kawasaki''s disease is a medium-vessel vasculitis characterized by fever, conjunctival involvement, cervical lymphadenopathy, maculo-papular eruption on trunk and straw berry tongue.
Other causes of livedo reticularis include polyarteritis nodosa, phaeochromocytoma, multiple sclerosis and amantadine use.
A physiological variant exist-mainly following cold exposure -which disappears with re-warming.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (105, 6, 'Trachyonychia is a recognised feature of which of the following:', 'Acne fulminans.', 'Alopecia areata.', 'Hereditary angioedema.', 'Systemic lupus erythematosus.', 'Xeroderma pigmentosum.', 'B', 'Trachyonychia - sand paper appearance and roughening of the nails.
Spontaneous resolution commonly occurs.
Other causes of trachonychia include: idiopathic, pemphigus vulgaris, psoriasis, li chen planus and eczema.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (106, 6, 'Which of the following does not portend a poor prognosis in alopecia areata?', 'Atopic background.', 'Early onset.', 'Extensive involvement.', 'Male sex.', 'Presence of nail disease.', 'D', 'Other poor prognostic factors include family history and chronicity.
Differential diagnoses include telogen effluvium, anagen effluvium, trichotillomania, loose anagen syndrome, drug-induced alopeda, systemic lupus erythematosus, syphilis and tinea capltis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (107, 6, 'Which of the following is not a neutrophilic dermatosis:', 'Beh et''s disease.', 'Erythema elevatum diutinum.', 'Erythema multiforme.', 'Pyoderma gangrenosum.', 'Sweet''s syndrome.', 'C', 'Erythema multiforme is a reactive self-limiting condition which is predominantly lymphocytic.
Other examples of neutrophilic dermatoses include subcorneal pustular dermatosis and bowel-associateddermatosis-arthritis syndrome.
The neutrophilic derm;;toses can beassociated with internal disease/haematological malignancies and often respond well to systemic corticosteriods.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (108, 6, 'A 39-year-old man developed fever, neutrophilia and a rash, which started in the groins and lower abdomen 10 days after he was prescribed amoxicillin for a presumed chest infection. The rash consisted of small pinhead-sized non-follicular pustules on a background of erythema. The rash desquamated after 2 weeks leaving normal-looking background skin. Liver and kidney function tests were all within normal range. There was no mucosal involvement. What is the most llkel''t diagnosis?', 'Acute generalized exanthematous pustulosis.', 'Drug reaction with eosinophilia and systemic symptoms.', 'Erythema multiforme.', 'Toxic epidermal necrolysis.', 'Urticaria.', 'A', 'The history and clinical findings are typical of AGEP (acute generalized exanthematous pustulosis) whieh is a self-limiting drug eruption that often begins in the flexlires.
Pustular psoriasis is the main differential but a history'' of previous psoriasis and the absence of any drug intake can help differentiate the two conditions.
An eosinophilic infiltrate in the biopsy can sometimes be helpful and would point towards AGEP.
Acanthosis and papillomatosus are often seen in pustular psoriasis and rarely in AGEP, which can also aid in the differentiation.
Drug eruptions that are accompanied by fever include AGEP, toxic epidermal necrolysis/Stevens-Johnson syndrome and DRESS.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (109, 6, 'A 45-year-old man presents to the rheumatologist with severe psoriasis and joint pains. Which of the following is not a recognised form of psoriatic arthritis?', 'Arthritis mutilans.', 'Distal oligoarticular.', 'Peripheral symmetrical.', 'Spondyloarthritis.', 'Symmetrical proximal.', 'E', 'Psoriatic art.hropathy can present in the following forms:
-Distal int-erphal::ingeal joint (commonest).
-Ollgoarticular asymmetrical.
-Polyarticular symmetrical (rheumatoid arthritis like).
-Spondylitis and sacroiliitis.
-Arthritis mutilans.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (110, 6, 'A 55-year-old woman presents with a 5-week history of burning sensation of her feet. Weight bearing was extremely painful. The pain was only partially relieved on cold water soaks. Examination showed erythema of the soles of the feet which was very tender to touch. Pedal pulsations were normal. She had a history of duodenal ulceration for which she took omeprazole. Heamatological investigations showed hae moglobin of 12.Sg/dl, normal white cell and differential count and a platelet count of 550x103 /1. What is the most likely diagnosis?', 'Burning feet syndrome.', 'Erythromelalgia.', 'Omeprazole toxicity.', 'Peripheral neuritis.', 'Shamberg''s disease.', 'B', 'Erythromelalgia is characterised by intense burning pain and erythema (marked redness) of the extremities.
Erythromelalgia is classified into primary and secondary or early-onset and late-on set forms.
Primary erythromelalgia develops spontaneously and is also known as idiopathic erythromelalgia as the cause remains unknown.
Secondary erythromelalgia can be secondary to myeloproliferative disorders, neurological diseases (e.g. multiple sclerosis, peripheral neuropathy), or autoimmune diseases(e.g. lupus, diabetes mellitus).
The most common cause of secondary erythromelalgia are myeloproliferative disorders including polycythaemia vera, and essential thrombocythaemia.
Erythromelalgia may precede the diagnosis of myeloproliferative disorders in 85% of cases.
It is characterised by red, painful, warm hands or feet.
Chilblain-like lesions can occur in myeloproliferative disorders but are cold to touch.
The burning symptoms are exacerbated by warming or hanging the limb downward, and relieved with cooling and elevation.
Systemic treatments include aspirin, serotonin re-uptake inhibitors - venlafaxine, sertraline, fluoxetine, paroxetine; tricyclic antidepressants-amitriptyline, imipramine, gabapentin, nifedipine, diltiazem and prostaglandins-misoprostol.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (111, 6, 'A 58-year-old woman is admitted with deep vein thrombosis. Three days after being commenced on warfarin she develops necrotic and painful bullae on her thighs. What should be the next step in management?', 'Increase warfarin dose.', 'Reduce warfarin dose.', 'Skin biopsy.', 'Start heparin.', 'Stop warfarin.', 'E', 'Warfarin causes inactivation of clotting factors II, VII, IX and X and proteins C and 5.
Cond,tions such as inherited deticiency of protein C, protein S or factor V leidet1, mutations in methylene tetra hydro foiate reduc.tase gene causing hyperhomocysteinaemia, antithrombin 111 deficiency or the presence of antiphospholipid antibodies predispose to warfarin-induced skin necrosis.
The first step in management is to stop the warfarin therapy.
Other measures include administration of vitamin Kor protein C concentrates.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (112, 6, 'A 65-year-old patient presents with velvety pigmented changes in axillary skin and similar changes around the perioral area. You are worried that he may have an internal malignancy. Which of the following is the most common malignancy associated with these cutaneous changes?', 'Bone.', 'Gastric.', 'Haematological.', 'Lung.', 'Renal.', 'B', 'Gastric cancer is the commonest tumour associated with malignant acanthosis nigricans.
The changes may regress if thetumour, usually an adenocarcinoma of the stomach or bowel, is removed.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (113, 6, 'A 55-year-old man is admitted to the hepatology ward and isundergoing investigations for jaundice. Your hepatologist colleague asks you to have a look at his nails, which display a bluish discolouration of the lanulae. Which of the following is associated with azure nails?', 'Criggler Najjar syndrome.', 'Dubin-Johnson syndrome.', 'Primary biliary cirrhosis.', 'Rotor Syndrome.', 'Wilson''s disease.', 'E', 'Azure lanulae, a bluish colour of the lanular portion of nails, occurs In hepatolenticular degeneration (Wilson''s disease).
Similar nail changes and corneal changes resembling Wilson''s Kayser-Fleischer rings may also be evident in patients with argyria or after treatment with busulfan or antimalarials.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (114, 6, 'A 45-year-old patient is diagnosed with Crohn''s disease. He has apthous ulceration. Other cutaneous features of Crohn''s disease include all of the following except:', 'Granulomas in the perineum.', 'Granulomatous cheilitis.', 'Hirsutism.', 'Oral granulomatous nodules.', 'Pyoderma gangrenosum.', 'C', 'Aphthous ulcers may be a presenting feature of Crohn''s disease.
Oral granulomatous nodules are commonly seen in Crohn''s disease, where they may coalesce to give a "cobblestone" appearance.
Granulomatous cheilitis may predate bowel disease by several years.
Granulomas may also occur in the perineum, at colostomy and ileostomy sites, and in association with scars, sinuses, and fistulas.
Granulomas can occur at sites not contiguous with the bowel, such as the trunk and limbs: the so-called "metastatic" cutaneous Crohn''s disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (115, 6, 'A forensic pathologist is examining hair for suspected poisoning. Chronic exposure and cumulative toxicity of which of the following chemicals can be identified in this way?', 'Arsenic.', 'Boric acid.', 'Lead.', 'Phosphorus.', 'Thallium.', 'A', 'Mercury intoxication can lead to hair loss with or without neurological symptoms.
Elevated mercury levels can be found in hair, blood, or urine.
Boric acid intoxir.ation also results in hair loss.
Gastrointestinal, central nervous system, and renal symptoms; a hemorrhagic diathesis; and exfoliation or bullae are also seen with boric acid intoxication.
Blood boric acid levels are elevated In affected patients.
Thallium poisoning leads to dramatic hair loss, with complete epilation occurring 2 to 3 weeks after intoxication.
Neurologic symptoms including irritability, dysesthesia, ataxia, convulsions, and coma can also result following thallium intoxication.
Blood and urine levels of thallium are positive at the time of acute poisoning.
In contrast to the above, arsenic exposure does not cause hair loss.
Arsenic concentrates in the hair, which facilitates a diagnosis long after intoxication may have occurred.
P0..70');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (116, 6, 'A 12-year-old patient is diagnosed with alopecia areata. His parents are interested in knowing the prognosis. The following are associated with a poor prognosis in alopecia areata except:', 'Alopecia totalis.', 'Body hair loss.', 'Nail involvement.', 'Onset in adulthood.', 'Positive family history.', 'D', 'Spontaneous remission is common in most patients with localised patches of alopecia areata.
Poor prognostic factors in alopecia areata include alopecia totalis and universalis, ophiasis pattern, onset in childhood, loss of body hair, nail involvement, atopy, and a positive family history for alopecia areata.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (117, 6, 'A 40-year-old man presents with androgenetic alopecia. He has heard about topical minoxidil solution. Which of the following statements regarding the use of topical minoxidil solution in androgenetic alopecia is not true?', '2% and 5% solution are equally effective.', 'Any hair gained is lost within 4 to 6 months of stopping minoxidil treatment.', 'Mean increase in hair density of 10-12% can be achieved.', 'Minoxidil is effective in treating vertex balding.', 'Minoxidil is not effective in treating frontotemporal recession.', 'A', 'Up to 60 percent of men show improvement in vertex balding using 5 % minoxidil lotion.
A mean increase in hair density of 10 to 12% is obtained.
The response rate with 2 % lotion are lower (the recommended concentration in women).
Any hair gained is lost within 4 to 6 months of stopping treatment.
Minoxidil is not effective in treating frontotemporal recession.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (118, 6, 'A 65-year-old man is seen with transverse depressions in nail plate. He has been undergoing cancer chemotherapy. Where does the abnormality originate?', 'Distal nail matrix.', 'Nail bed.', 'Nail plate.', 'Proximal nail fold.', 'Proximal nail matrix.', 'E', 'Beau''s lines result from a temporary arrest of proximal nail matrix proliferation.
These appear as transverse grooves in the nail plate that move distally with nail growth.
Multiple Beau''s lines in the same nail indicates repetitive insults.
Beau''s lines at the same level in several nails suggest a systemic cause.
The time of the insult leading to Beau''s lines can be dated by measuring the distance of the groove from the proximal nail fold.
Causes of Beau''s lines include local traurria, or can be related to local cutaneous dis ease, particularly eczema and paronychia.
Systemic causes include drugs (especially chemotherapy), high fever, viralillness, surgery, and peripheral ischemia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (119, 6, 'You see a 35-year-old patient with longit1Jdinal melanonychia affecting 2 finger nails. Which of the following is not a recognised cause?', 'Acquired immunodeficiency syndrome.', 'Addison''s disease.', 'Inflammatory nail disorders.', 'Piebaldism.', 'Racial.', 'D', 'Melanonychia signifies the presence of melanin in the nail plate and appears as a single or longitudinal brown to black band.
Caused by activation or proliferation of nail matrix melanocytes.
Causes include racial, acquired immunodeficiency syndrome, inflammatory nail disorders, certain medications, Addison''s disease, pregnancy, Laugier-Huntz;ker syndrome, and trauma.
Single nail melanonychia may be secondary to nail matrix naevus or melanoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (120, 6, 'A 60-year-old woman is referred with scaly, crusted erosions on the malar area of the face and seborrhoeic areas. Skin biopsy shows acantheilysis in the superficial epidermis just below the stratum corneum and in the granular layer. Antinuclear antibodies are detected on serological testing. Which of the following is the correct diagnosis?', 'Fogo selvagem.', 'Paraneoplastic pemphigus.', 'Pemphigus erythematosus.', 'Pemphigus foliaceous.', 'Pemphigus vulgaris.', 'C', 'Senear-llsher syndrome or pemphigus erythematosus is a localized form of pemphigus foliceous.
Scaly and crusted lesions occur across the malar area of the face and in other seborrheic areas.
Pemphigus erythematosus may remain localized for years, or it may evolve into more generalized pemphigus foliaceous.
Many patients with pemphigus erythematosus show serologic findings suggestive of systemic lupus erythematosus, especially the presence of anti-nuclear antibodies.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (121, 6, 'A 70-year-old man is admitted with painful stomatitis and a polymorphous cutaneous eruption with a predominantly blistering rash. A skin biopsy showed Intra-epidermal acantholysis and direct immunofluoresence showed deposition of immunoglobulin G and complement in the epidermal inteniellular space5, and granular/linear complement deposition along the epidermal basement membrane zone. Which of the following is the most common associated diagnosis?', 'Myaesthenia gravis.', 'Non Hodgkin''s lymphoma.', 'Renal cell carcinoma.', 'Thymoma.', 'Ulcerative colitis.', 'B', 'Paraneoplastic pemphigus is an autoimmune disorder.
It is almost always linked to an underlying lymphoproliferative disorder. Its features include painful stomatitis and a polymorphous cutaneous eruption including blistering, lichenoid, erythema multiforme-like lesions. Histologic findings include acantholysis, lichenoid, or interface changes.
Direct immunofluorescence demonstrates deposition of immunoglobulinG (IgG) and complement in the epidermal intercellular spaces, and often granular/linear complement deposition along the epidermal basement membrane zone.
In addition to binding the cell surface of skin and mucosae in a pattern typical for pemphigus, serum auto-antibodies also bind to simple, columnar, and transitional epithelia.
These serum auto-antibodies identify desmogleins 1 and 3 and additionally desmoplakins, envoplakin, and periplakin.
Most commonly associated diseases include non-Hodgkin lymphoma (NHL), chronic lymphocytic leukemia, and Castleman''s disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (122, 6, 'A 45-year-old patient who was commenced on lamotrigine for epilepsy presents with a morbilliform skin rash, fever, facial oedema and lymphadenopathy. Which of the following statements with regards to this drug reaction is incorrect?', 'Atypical lymphocytosis with subsequent eosinophilia may occur during the initial phases.', 'Central nervous system involvement is never seen.', 'Cross-reactivity to the other aromatic anticonvulsants may occur.', 'The reaction most frequently occurs on first exposure to the drug.', 'The susceptibility to develop this reaction may be familial.', 'B', 'Hypersensitivity syndrome reaction (HSR), also called drug reaction with eopsinophilia and systemtic symptoms (DRESS syndrome), is the presence of exarrthematous eruption in conjunction with fever and internal organ involvement (e.g. liver, kidney, central nervous system) which occurs in appoximateiy 1 in 3000 exposures to agents such as aromatic anti-convulsants, lamotrigine, sulfonamide antibiotics, dapsone, nitrofurantoin, nevirapine, minocycline, and allopurinol.
DRESS occurs most frequently on first exposure to the drug, with initial symptoms starting 1 to 6 weeks after exposure.
Fever and malaise are often the presenting symptoms.
Atypical lymphocytosis with subsequent eosinophilia may occur during the initial phases of the reaction in some patients.
Most patients have an exanthematous eruption.
Internal organ involvement can be asymptomatic.
The chemically reactive metabolites of aromatic anti-convulsants that a,e produced are detoxified by epoxidehydroxylases. If detoxification is defective, however, one of the metabolites may act as a hapten and initiate an immune response, stimulate apoptosis, or cause cell necrosis directly.
Approximately 70-75% of patients who develop anticonvulsant HSR in response to one aromatic anti-convulsant show cross-reactivity to the other aromatic anti-convulsants.
In vitro testing shows that there is a familial occurrence of HSR induced by anti-convulsants.
Thus, counselling of family members and disclosure of risk is essential.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (123, 6, 'A 34-year-old Asian man presents with a monomorphic pustular eruption on the face and limbs. Only a few papules and no comedones were seen. He was referred by the infectious diseases team, who had only recently commenced him on anti-tubercular therapy. Which of the following drugs is most commonly implicated?', 'Ethambutol.', 'Isoniazid.', 'Pyrazinamide.', 'Rifampicin.', 'Streptomycin.', 'B', 'Drug-induced acne may appear in atypical areas, such as on the arms and legs.
The lesions are mostly monomorphous and comedones are usually absent.
Topical tretinoin may be useful.
Implicated drugs include iodides, bromides, adrenocorticotropic hormone, glucocorticoids, isoniazid, androgens, and lithium.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (124, 6, 'Which of the following conditions c::in give a "pterygium" if the nail apparatus is affected?', 'Darier''sdisease.', 'Hyperthyroidism.', 'Lichen nitidus.', 'Lichen planus.', 'Lichen striatus.', 'D', 'V-shaped distal nick and leuko - or erythronychia can be seen in Darier''s disease.
Lichen striatus may result in nail dystrophy and trachonychia but not pterygium.
Hyperthyroidism is associated with onycholysis.
Lichen nitidus is not associated with an''/ specific nail changes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (125, 6, 'Which of the following conditions or eruptions is not considered paraneoplastic?', 'Acquired ichthyosis.', 'Dermatomyositis.', 'Erythema chronicum migrans.', 'Erythema gyratumrepens.', 'Necrolytic migratory erythema.', 'C', 'Other paraneoplastic conditions include pruritus, acanthosis nigricans, Sweet''s syn drome, Leser-Trelat sign, palmar tylosis, acquired hypertrichosis lanuginosa, migratory thrombophlebitis and paraneoplastic pemphigus.
Suspect malignancy in acanthosis nigricans in the presence of weight loss and nor moglycaemia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (126, 6, 'Which pattern of drug eruptions is the commonest?', 'Drug-induced lupus.', 'Exanthematous.', 'Fixed drug eruption.', 'Toxic epidermal necrolysis.', 'Urticarial.', 'B', 'A maculo-papular drug exanthem is the commonest pattern of drug reaction occuring mostly within 2 weeks of drug ingestion.
Urticarial eruptions are the second most common followed by vasculitis.
Other patterns of drugeruptions include generalized exanthematous pustulosis, photosensitivity, lichenoid eruptions, xerosis, hair loss, bullous and exfoliative.
Some drugs can worsen existent skin diseases such as psoriasis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (127, 6, 'Acquired ichthyosis can occur in which of the following?', 'Graft-versus-host disease.', 'Hypothyroidism.', 'Lymphoma.', 'Sarcoidosis.', 'All of the above.', 'E', 'Suddrm-onset of acquired ichthyosis should alert the dermatologist to look for an underlying malignancy.
Other causes include drugs and HIV infection.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (128, 6, 'Cutaneous sarcoidosis can clinically present as:', 'Hypopigmented patches.', 'Nodules.', 'Papules.', 'Plaques.', 'All of the above.', 'E', 'Plaque-type sarcoidosis is the commonest cutaneous type followed by nodules.
Other variants include ichthyotic, dystrophic nails, subcutaneous and scar sarcoidosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (129, 6, 'Which type of cryoglobulinaemia is not associated with hepatitis C infection?', 'Type I.', 'Type II.', 'Type III.', 'Types I and II.', 'Types II and III.', 'A', 'Cryoglobulins are immunoglobulins that precipitate following cold exposure.
Types II and III are called mixed cryoglobulinaemia and can be associated with hepatitis C, connective tissue diseases, HIV, and lymphoproliferative disorders.
Type I is associated wih lymphoproliferative disorders but not with hepatitis C.
Suspect cryoglobulinaemia in the presence of a pernio-like appearance of digits, reticulate leukocytoclastic cutaneous vasculitis and when the levels of C4 are reduced.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (130, 6, 'In which of the following conditions can calcinosis cutis develop?', 'Juvenile dermatomyositis.', 'Pseudoxanthoma elasticum.', 'Sarcoidosis.', 'Scleroderma.', 'All of the above.', 'E', 'Calcinosis cutis is a well-recognized complication of juvenile dermatomyositis although it may occur (less commonly) in the adult form.
Juvenile dermatomyositis is not associated with an underlying malignancy (unlike the adult form).
Other conditions in which calcinosis cutis may occur include hyperparathyroidism, pseudohypoparathyroidi.;;m and chronic renal failure.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (131, 6, 'In which of the following is poikiloderma a feature?', 'Acne vulgaris.', 'Chronic plaque psoriasis.', 'Dermatomyositis.', 'Lichen planus.', 'Malignant melanoma.', 'C', 'Poikiloderma consists of pigmentary changes, atrophy and telangiectasia.
Other conditions in whichpoiklloderma may ooccur include mycosis fungoides, Rothmund-Thomspson syndrome and Bloom''s syndrome.
Poikiloderma of Civatte is a benign finding secondary to the effects of ultraviolet radiation and fragrances - appearing on the sides of the neck.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (132, 6, 'Which of the following drugs is associated with acneiform eruption?', 'Erythromycin.', 'Lithium.', 'Propranolol.', 'Ramipril.', 'Tetracycline.', 'B', 'An acneiform eruption secondary to a drug typically presents with predominantly monomorphic papules and pustules with no comedones (excepting the pre-existing comedones).
Other drugs that can give such an eruption include corticosteroids, androgens, phenytoin, isoniazid, haloperidol and sirolimus.
The relatively new anti-cancer drugs (Epidermal Growth factor Receptor Antagonists)
can give in addition to an acneiform eruption; xerosis, alopecia, pyogenic granuloma-like lesions in the digits and paronychia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (133, 6, 'A 56-year-old man w;th myeloid leukaemia developed deranged iiverflinction tests, diarrhoea and a maculo-papular eruption involving the palms and soles with marked follicular accentuation. This occured within 6G days following an allogenic bone-marrow transplantation. The most likely diagnosis here is:', 'Acute graft-versus-host disease.', 'Impetigo.', 'Secondary syphilis.', 'Systemic lupus erythematosus.', 'Toxic epidermal necrolysis.', 'A', 'Acute GVHD occurs within the first 100 days following an allogenic transplant tissue (mostly but not exclusively bone marrow) and typically presents with an exanthematous eruption most markedly on the palms and soles, hepatitis, diarrhoea and malaise.
Occasionally erythroderma followed by an exfoliation can occur giving a clinical picture similar to toxic epidermal necrolysis.
The most important differential diagnoses include a viral and drug-related exanthem and the eruption of lymphocyte recovery.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (134, 6, 'Which of the following alopecias is typically non-scarring?', 'Alopecia mucinosa.', 'Discoid lupus erythematosus.', 'Dissecting cellulitis of the scalp.', 'Lichen planopilaris.', 'Telogen effluvium.', 'E', 'Other causes of scarring alopecias include folliculitis Decalvans, erosive pustular dermatosis and pseudopelade.
Non-scarring alopecias include anagen effluvium, alopecia areata, loose anagen syndrome and syphilitic alopecia (patchy with a "moth-eaten" appearance).
In scarring alopecia the type of infiltrate (neutrophilic, lymphocytic or mixed) is also important pointer to the diagnosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (135, 6, 'Which of the following cutaneous manifestations can be associated with hepatitis C infection?', 'Atopic dermatitis.', 'Hidradenitis suppurativa.', 'Porphyria cutanea tarda.', 'Pustular psoriasis.', 'Scleroedema.', 'C', 'Hepatitis C infection can be associated with several cutaneous manifestations which include polyarteritis nodosa, lichen planus, erythema nodosum, cryoglobulinaemia (types II and III) and chronic urticaria.
Hepatitis B and C should always be looked for in the work-up of porphyria cutanea tarda.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (136, 6, 'Which of the following is the auto-antigen in dermatitis herpetiformis?', 'BP 230.', 'Collagen VII.', 'Collagen XII.', 'Epidermal transglutaminases.', 'Intestinal transglutaminase.', 'D', 'Epidermal transglutaminases is the dominant auto-antigen in dermatitis herpetiformis.
Collagen VII is the target in epidermolysis bullosa acquista, whilst BP 230 and 180 are the auto-antigens in bullous pemphigoid.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (137, 6, 'Which of the following statements regarding IgA in dermatitis herpetiformis (DH) is true?', 'Granular IgA deposits may also be seen in the skin of patients with epidermolysis bullosa acquisita.', 'IgA deposits are not seen in the skin of patients with isolated coeliac disease.', 'IgA deposits are uniformly intense throughout the skin.', 'IgA deposits may decrease after treatment with drugs.', 'Linear igAdeposits In normal-appearing skin isthe most reliable criterion for the diagnosis of DH.', 'B', 'Granular (or fibrillar) IgA deposits in dermal papillary tips of peri-lesional and uninvolved skin of patients is a typical finding in dermatitis herpetiformis.
IgA deposits have not been seen in the skin of patients with isolated coeliac: disease (without dermatitis herpetiformis).
IgA deposits in dermatitis herpetiformis are unaffected by treatment with drugs.
IgA deposits may decrease in intensity or disappear after long-term gluten-free diet.
IgA deposits are not uniformly intense throughout the skin.
These deposits may be more easily and intensely seen in normal-appearing peri-lesional skin.
IgA deposits may also be seen in the skin of patients with bullous pemphigoid, Hen och Schonlein purpura, and alcoholic liver disease, although the patterns of distribution is different than those seen in dermatitis herpetiformis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (138, 6, 'A 55-year-old diabetic woman presents with tense serous bullae on the lower legs. There is no perilesional erythema. Which of the following statements is correct?', 'Direct immunofluoresence shows IgG and C3 at the dermo-epidermal junction.', 'Hands are never involved.', 'Immunofluorescence is not diagnostic.', 'Oral steroids should be instituted.', 'There is a direct correlation with glycaemic control.', 'C', 'Bullous disease of diabetes (bullosis diabeticorum) is a spontaneous, non-inflammatory, blistering condition of acral skin in patients with diabetes mellitus.
The aetiology is obscure and a history of antecedent trauma is not always forthcoming.
Many patients have associated nephropathy or neuropathy.
Tense, non-tender blisters are seen on non-erythematous, non-urticated areas of the feet or lower legs. Other involved sites include the fingers, toes, hands, arms and rarely, non-acral sites may be involved.
Histology is non-specific and immunofluorescence is negative.
The blister may be in subcorneal, intraepidermal, or subepidermal location.ihe condition is self-limiting and the blisters heal spontaneously within 2-6 weeks of onset.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (139, 6, 'A 60-year-old woman presents with a non-tender violaceous annular plaque on the dorsum of her hand. She is taking methotrexate for rheumatoid arthritis. A skin biopsy shows palisaded granulomas associated with necrobiosis and increased deposition of dermal mucin. Which one of the following statements regarding thiscondition is true?', 'Methotrexate dose reduction is recommended.', 'Increasing the dose of methotrexate may improve the skin lesions.', 'Spontaneous resolution can be expected in 2 years.', 'The disease follows severity of rheumatoid arthritis.', 'There is an association with rheumatoid arthritis.', 'C', 'The clil"ical features and histology are typical of granuloma annulare (GA).
GA most commonly affects the dorsum of hands and feet.
GA can. present as subcutaneous, perforating, disseminated and the rare "in terstitial" variants.
Localised forms of GA are generally not associated with systemic illnesses.
Disseminated GA may be associated with diabetes mellitus.
Localised GA tends to resolve spontaneously (80% clearance in 2 years).
Disseminated GA lasts longer.
Potent topical and intralesional corticosteroids are the treatment of choice for localised lesions.
Phototherapy can be used in disseminated GA.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (140, 6, 'A 55-year-old patient presents with asymptomatic, firm, subcutaneous nodules on the elbow. A skin biopsy shows palisading granulomas with macrophages surrounding the eosinophilic fibrinoid degeneration of the collagen in the deep dermis. Which of the following is the most likely associated systemic disorder?', 'Diabetes.', 'Gout.', 'Rheumatoid arthritis.', 'Sarcoidosis.', 'Syphilis.', 'C', 'Rheumatoid nodules are most commonly seen on the elbows.
Other common sites include the extensor surfaces of the fingers.
Achilles tendon, ischial tuberosities and sacrum.They occur in 25%of patients with rheumatoid arthritis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (141, 6, 'A 70-year-old woman is admitted with chronic renal failure. She develops gangrenous areas on her thighs. A skin biopsy shows calcific deposits in blood vessels, necrosis and panniculitis. Which of the following statements is true?', 'Intravenous sodium thiosulphate may bring about resolution.', 'Parathyroidectomy has no role.', 'Primary hyperparathyroidism is the aetiological factor.', 'Prognosis is excellent with spontaneous improvement in most.', 'Serum calcium levels are generally low.', 'A', 'Calciphylaxis or calcific uraemic arteriolopathy refers to calcification affecting small blood vessels.
Secondary hyperparathyroidismresults in high or normal levels of serum calcium and phosphate results in spreading skin necrosis.
Purple mottling is followed by painful skin ulceration.
Management includes restricting calcium and phosphate in diet and using a lower dialysate calcium concentration.
Bisphosponates and intravenous infusions of sodium thiosulfate have been used successfully.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (142, 6, 'A 44-year-old woman is admitted with fever, chest and hip pains, and a recurrent non-pruritic urticarial eruption that lasts for few hours and coincides with febriie episodes. Haematological investigations show raised erythrocyte sedimentation rate (ESR) and C-React''.va Protein (CRP) and serum IgM. A skin biopsy shows perivascular neutrophilic inflammation. What is the most likely diagnosis?', 'CINCA syndrome.', 'Muckle-Wells syndrome.', 'NOMID syndrome.', 'Schnitzler''s syndrome.', 'Waldenstrom''s syndrome.', 'D', 'Features of Schnitzler''s syndrome include chronic non-pruritic urcicaria, monoclonal IgM gammopathy, intermittent fever, asthenia, arthralgia, and bone pain with imaging evidence of osteosclerosis.
Biological findings usually include an increase in white blood cell count, ESR and CRP, which reflect an inflammatory syndrome and the presence of the monoclonal IgM.
Skin biopsy findings often include mononuclear or neutrophilic perivascular infiltrates.
Treatment with NSAIDs, dapsone, colchicine alone is usually unsatisfactory.
Recently Anakinra, an interleukin-1 receptor antagonist has been found to be an effective treatment.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (143, 6, 'A 45-year-old presents with widespread chronic plaque psoriasis. He also complains of joint pains. Radiological examination confirmed psoriatic arthritis. What is the commonest type of psoriatic arthritis?', 'Asymmetric.', 'Axial arthritis.', 'Destructive arthritis.', 'Distelinterphalangeal joint disease.', 'Symmetric polyarthritis.', 'A', 'Up to 30% patients with psoriasis suffer from psoriatic arthritis.
The five types of psoriatic arthritis are:
Asymmetric - affects 60-70%- commonly involves fingers or toes.
Symmetric polyarthritis -15% - resembles rheumatoid arthritis.
Distal interphalengeal joint disease - 5%
Destructive arthritis (arthritis mutilans) - 5%
Axial arthritis - 5% - resembles ankylosing spondylitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (144, 6, 'A 60-year-old man is admitted with an erythematous and scaly rash covering 95% of his body surface area. He is feeling cold and shivery and is noted to have generalised lymphadenopathy. What is the commonest cause of erythroderma overall?', 'Drug allergy.', 'Atopic dermatitis.', 'Idiopathic.', 'Lymphoma.', 'Psoriasis.', 'C', 'This patient has erythroderma which by definition is involvement of >90% bod·f surface area with an erythematous and scaly rash.
The cause remains unknown in the majority of cases (30%).
Where a cause can be found, drug reactions are most commonly implicated.
Pre-existing skin diseases like atopic dermatitis and psoriasis, lymphoma and contact dermatitis are other causes of erythroderma.
130');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (145, 6, 'A 75-year-old man presents with recurrent crops of small, pruritic blisters on the scalp, face and neck. Examination shows atrophic scars and small vesicles on the scalp. There was no involvement of oral mucosa. A punch biopsy shows a non-inflammatory, subepidermal blister and direct immunofluoresence demonstrates linear deposits of complement C3 and IgG at the dermo-epidermal junction. What is the diagnosis?', 'Brunsting- Perry cicatritial pemphigoid.', 'Linear IgA disease.', 'Porphyria cutanea tarda.', 'Pseudo-porphyria.', 'Sweet''s syndrome.', 'A', 'Brunsting-Perry cicatritial pemphigoid is a rare variant of cicatritial pemphigoid.
It is most commonly seen in elderly males.
Clinical features include pruritic, recurrent crops of vesicles which heal with atrophic scars.
The vesicles are confined mainly to the head and neck.
Histopathology shows subepidermal blisters with prominent perivascular infiltrates of lymphocytes, polymorphonuclears, eosinophils and prominent fibrosis in late stages.
Direct immunofluoresence shows staining with IgG and C3.
Successful treatments include dapsone and sulphamethoxypyridazine.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (146, 6, 'A 70-year-old man is admitted with weight loss and fatigue. He is noted to have ichthyosis. A computed tomography scan showed mediastinal lymphadenopathy. You make a diagnosis of acquired ichthyosis. Which of the following is not a recognised cause of acquired ichthyosis?', 'Hypothyroidism.', 'Multiple myeloma.', 'Nicotinic acid.', 'Sarcoidosis.', 'Syphilis.', 'E', 'Acquired ichthyosis is associated with malignancies (especially Hodgkin''s lymphoma), non-Hodgkin lymphoma, mycosis fungoides, myeloma, Kaposi''s sarcoma, leiomyos11rcoma, and carcinomas of the lung, breast, ovary, and cervix.
Sarcoidosis, leprosy, thyroid disease, hyperparathyroidism, nutritional disorders, chronic renal failure, bone marrow transplantation, and HIV infection can all cause ichthyosis.
Auto-immune diseases, including systemic lupus erythematosus and dermatomyositis.
Medications - nicotinic acid, triparanol, butyrophenones, dixyrazine, cimetidine, and clofazimine.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (147, 6, 'Which of the following statements is incorrect regarding auto-inflammatory syndromes?', 'Abdominal pain is common in acute attacks.', 'Arthralgia is common in acute attacks.', 'Fever is often present in acute attacks.', 'Raised inflammatory markers are almost always seen in acute attacks.', 'The predominant skin eruption during acute attacks consists of a maculopapular exanthem.', 'E', 'Auto-inflammatory syndromes are characterised by the presence of fever, abdominal pain, arthralgia and an urticarial eruption during acute attacks.
Raised inflammatory markers are almost always found during acute attacks. Its absence almost always excludes the presence of an auto-inflammatory syndrome.
These syndromes represent dysfunction of the innate immunity (neutrophils and macrophages) in the absence of auto-antibodies.
Examples of auto-inflammatory syndromes include hyper IgD syndrome, Schnitzler''s syndrome, cryopyrin-associated-periodic-fever syndrome, TNF-receptor-associatedperiodic fever-syndrome (TRAPS) and familial Mediterranean fever.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (148, 6, 'Which of the following drugs is most likely to cause systemic vasculitis due to the induction of p-ANCA?', 'Anti-TNF agents.', 'Minocycline.', 'Penicillamine.', 'Propylthiouracil.', 'Simvastatin.', 'D', 'All the above listed drugs can result in positive p-ANCA with or without systemic vasculitis.
Propylthiouracil is an anti-thyroid drug most commonly associated with the induction of systemic vasculitis through p-ANCA which can occur several months to years following initiation of therapy.
Other causes of positive p-ANCA Include inflammatory bowel disease, rheumatoid arthritis andtuberculosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (149, 6, 'Which of the following is least likely to result in generalized pustular psoriasis?', 'Pregnancy.', 'Treatment with crude coal tar.', 'Treatment with intliximab.', 'Ultraviolet-A radiation.', 'Withdrawal of systemic steroids.', 'C', 'Generalized pustular psoriasis is a dermatological emergency In which patients are often very unwell.
Leukocytosis and fever may be present.
Ultraviolet-A radiation, withdrawal of steroid therapy, crude coal tar and pregnancy can all trigger generalized pustular psoriasis.
It is worth checking calcium levelsin pustular psoriasis as hypocalcaemia may result in therapy resistance.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (150, 6, 'Which of the following statements is correct?', 'Both heparin and warfarin-induced skin necrosis are related to the production of specific antibodies against the drugs.', 'Heparin-inducedskin necrosis is related to a drop in protein C levels.', 'Heparin-induced skin necrosis is related to the production of antibodies and therefore should never be re-challenged.', 'Warfarin -induced skin necrosis is related to the production of antibodies and therefore should never be re-challenged.', 'Warfarin-induced skin necrosis is a late manifestation of warfarin therapy, often occurring after the first six weeKS.', 'C', 'Warfarin-induced skin necrosis often occurs between day three and eight following initiation of warfarin due to the transient pro-coagulant state secondary to a drop in protein(s) C and S levels.
Heparin-inducedskin necrosis occurs due to the production of antibodies and should therefore never be re-challenged with heparin, unlike warfarin which can be re-challenged provided there is concomitant use of low molecular weight heparin in the initial phase.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (151, 6, '5-alpha-reductase is responsible for which type of hair loss?', 'Alopecia areata.', 'Anagen effluvium.', 'Androgenetic alopecia.', 'Frontal fibrosing alopecia.', 'Telogen effluvium.', 'C', '5-alpha-reductase converts testosterone to the more potent dihydrotestosterone which is responsible for hair loss in androgenetic alopecia.
Finasteride is a drug that blocks this enzyme; hence it can be used in male pattern alopecia.
Thyroid disease and iron deficiency anaemia can contribute to diffuse hair loss in a non-scarring fashion such as telogen effluvium.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (152, 6, 'Which of the following statements regarding the diagnosis of hidradenitis suppurativa is incorrect?', 'An autosomal dominant variant exists.', 'Arthritis can be a manifestation in severe cases.', 'Obesity tends to worsen the condition.', 'Smoking tends to worsen the condition.', 'There is increased risk of basal cell carcinoma.', 'E', 'There is increased risk of squamous cell carcinoma in patients with hidradenitis suppurativa due to the chronic inflammation.
Lymphoedema is also a complication of the disease.
Lithium tends to exacerbate hidradenitis suppurat.iva.
The condition can be associated with inflammatory bowel disease, pyoderma gangrenosum, spondylc::irthropathy and SAPHO syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (153, 6, 'Naso-septaI perforation can be found in all of the following except?', 'Bevacizumab therapy.', 'Cocaine use.', 'Polyarteritis nodosa.', 'Trauma.', 'Wegener''s granulomatosis.', 'C', 'Bevacizumab is a humanised monoclonal anti-angiogenic antibody used in the treatment for various cancers. Cocnine use, Wegener''s granulomatosis, trauma and bevacizumab have all been associated with naso-septal perforation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (154, 6, 'Which of the following is not a treatment option in pruritus secondary to endstage renal failure?', 'Gabapentin.', 'Mirtazapine.', 'Rifampicin.', 'Topical anti-pruritic therapy.', 'UVB phototherapy.', 'C', 'Pruritus is a common feature of end-stage renal disease and treatment depend on the severity.
Treatments include topical anti-pruritic therapy, UVB phototherapy, gabapentin and the use of selective neuro-epinephrine re-uptake inhibitors such as minazapine.
Rifampicin is used in pruritus secondary to chronic liver disease as it induces liver enzymes.
Other treatments for chronic liver disease inclucle the use vf mirtazapine or paroxetine, bile acid resins and naltrexone.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (155, 6, 'Which of the following is the most common manifestation of ocular rosacea?', 'Blepharitis.', 'Conjunctivitis.', 'Keratitis.', 'Meibomian gland dysfunction.', 'Scleritis.', 'D', 'Rosacea has four sub-types - erythematotelangiectatic, papulo-pustular, phymatous and ocular rosacea.
Ocular rosacea can be found in half of the patients, which is more frequently associ ated with the papulo-pustular variant.
Meibomian gland dysfunction is the commonest manifestation of ocular rosacea leading to dry eyes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (156, 6, 'Which type of cryoglobulinaemia is least likely to be assoc,ated with smallve.;sel vasculitis?', 'Types-1 & 2.', 'Type-1.', 'Types-2 & 3', 'Type-2.', 'Type-3.', 'B', 'Type-1 cryoglobulinaemia is often associated with monoclonal gammopathy and occlusion of small blood vessels but rarely small vessel vasculitis.
Cryoglobulinaemia types-2 and 3 are called essential mixed cryoglobulinaemia and can be associated with hepatitis C and other infections. It can be associated with small vessel vasculitis.
Type-2 cryoglobulinaemia can in some cases be associated with monoclonal gammopathy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (157, 6, 'A 52-year-old woman presented with a 3-year history of multiple painful and tender nodular lesions involving the upper aspects of her arms 2nd thighs, which were followed by atrophic scarring of the affected areas. She also suffered from chronic arthralgia and myalgia. She had positive ANA and weak double-stranded DNA antibodies. A biopsy showed evidence of atrophic epidermis with peri-vascular lymphocytic infiltrate, lobular panniculitis with a lymphocytic infiltrate. The most likely diagnosis is?', 'Discoid lupus erythematosus.', 'Erythema nodosum leprosum.', 'Erythema nodosum.', 'Lupus pernio.', 'Lupus profundus.', 'E', 'Lupus profundus is also known as lupus panniculitis, which is a chronic relapsing pannicullitis that occurs in 1 - 3% of patients with cutaneous lupus erythematosus, affecting mostly women.
Clinically, this can present with tender subcutaneous nodules and plaques with a predilection for the upper aspects of arms, shoulders and buttocks.
Histologically, it affects the cutaneous fat in a lobular fashion.
Treatment is with systemic steroids, hydroxychloroquine, dapsone, azathioprine or thalidomide.
Systemic retinoids are often unhelpful in thiscondition.
Erythema nodosum affects mostly the shins. Histologically, this is characterised by a septal panniculitis.
Lupus pernio is a term used for a variant of cutaneous sarcoidosis affecting the nose or ears resembling a frost bite.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (158, 6, 'Frusemide is a loop diuretic that is widely used. Which of the following blistering disorders can be caused by this drug?', 'Bullous pemphigoid & pseudo porphyria.', 'Bullous pemphigoid.', 'Drug-induced pemphigus.', 'Linear IgA disease.', 'Pseudo porphyria.', 'A', 'Vancomycin is the commonest cause of linear IgA disease.
Penicillamine and ACE inhibitors are common causes of drug-induced pemphigus.
Pseudo-porphyria can also be caused by thiazide diuretics and non-steroidal antiinflammatory drugs.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (159, 6, 'Which of the following conditions is not an acantholytic disorder?', 'Bullous pemphigoid.', 'Oarler''s disease.', 'Grover''s disease.', 'Hailey-Hailey disease.', 'Pemphigus vulgaris.', 'A', 'Bullous pemphigoid is a blistering disease which is subepidermal and acantholysis does not take place.
Hailey-Hailey and Darier''s diseases are both inherited forms of acantholytic disorders.
Grover''s disease is also known as transient acantf-iolytic dematosis and often pre sents with discrete pruritic papules and vesicles often on the back of middle aged or elderly people.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (160, 6, 'A 53-year-old man developed an intensely pruritic eruption consisting of violar.eous papules on his trunk and limbs with some follicular accentuation. He received a bone-marrow transplant four months prior to the onset of the eruption. Which of the following statements regarding this condition is incorrect?', 'A lichenoid drug eruption is the differential diagnosis in this case.', 'In grade 4 of the disease the histological appearances can resemble those of toxic epidermal necrolysis.', 'The chronic variant always follows on from the acute setting.', 'The condition is primarily mediated by T lymphocyt s.', 'The incidence is highest in the setting of bone marrow transplantation.', 'C', 'Chronic graft-versus-host-disease generally develops 3 months after transplantation and many not occur after the acute variant of the disease.
The condition is most likely to develop in the setting of allogeneic, unmatched and unrelated donor.
The 2 variants of the chronic form include lichenoid and sclerodermoid.
Advanced age, male gender and the presence of HLA-DR4 allele in the recipient are all risk factors for the development of the condition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (161, 6, 'A 64-year-old man with 3-year history of dermatomyositis presented with firm, painful nodules on his abdomen and limbs. Histology showed evidence of calicification in the dermis. The most likely mechanism here is:', 'Dystrophic calcinosis cutis.', 'Idiopathic calcinosis cutis.', 'Metastatic calcinosis cutis.', 'Primary osteoma cutis.', 'Secondary osteoma cutis.', 'A', 'Pathologic calcification of cutaneous tissue can be dystrophic, metastatic or idiopathic.
Oystrophk calcinosis cutis consists of deposition of calcium salts in abnormal or damaged tissue, mostly elastic fibres, and occurs in the setting of normal serum calcium levels particularly in connective ti sue disorders.
Metastatic calcinosis cutis occurs in the setting of hypercalcaemia and involves the calcification of normal tissues.
Idiopathic caicinosis cu-tis consists of calcification of normal tissues in the setting of normal calcium levels.
Primary osteoma cutis can occur in the setting of Albright''s hereditary osteodystrophy, fibrodysplasiaossificans progressiva and progressive osseous heteroplasia.
Secondary osteoma cutis may occur following previous dermatoses such as military osteoma cutis on the face secondary to acne vulgaris.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (162, 6, 'A 40-year-old woman recently diagnosed with acute myeloid leukaemia presented 3 weeks following treatment with thechemotherapy agent cytarabine. Clinically she had pruritic and tender papules on her forearms and chest with bilateral palmar erythema. The papules were slightly oedematous and some nave coalesced to form plaques. A biopsy taken from one of the papules showed a dense neutrophilic infiltrate around eccrine glands with associated necrosis. Which of the following statements regarding thiscondition is incorrect?', 'Acute myeloid leukaemia is the most common associated malignancy with this condition.', 'Cytarabine is the commonest reported chemotherapy agent respom,ible for thiscondition.', 'The condition is associated with a high mortality rate and future chemotherapy should be avoided.', 'The condition is self-limiting and treatment is often not required.', 'The condition usually begins within 3 weeks following chemotherapy.', 'C', 'Neutrophilic eccrine hidradenitis is a self-limiting condition occurring mostly within 3 weeks of cytarabine in the treatment of acute myeloid leukaemia.
Other chemotherapy agents that have been reported to cause the condition include bleomycin, cyclor,,hosphamide and doxorubicin.
Systemic steroids and dapsone have been used in cases where the lesions are very painful and oedematous.
Dapsone has been reported to be used successfully as prophylactic therapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (163, 6, 'In which of the following subtypes of vasculitis is the presence of granulomas a feature?', 'Churg-Strauss syndrome.', 'Cryoglobulinaemic vasculitis.', 'Erythema elevatum diutinum.', 'Granuloma faciale.', 'Microscopic polyarteritis.', 'A', 'Granulomas are also present in Wegener''s granulomatosis but In Churg-Strauss there it. often tissue eosinophilia as well.
In erythema elevatum diutinum the infiltrate is predominantly neutrophilic with areas of fibrosis (in chronic case).
In granuloma faciale there are no granulomas but a Grenz zone is present separating the dermis from the epidermis.
In cryoglobulinaemia a homogenous eosinophilic material is found within blood vessels.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (164, 6, 'A 40-year-old man with a history of excesive alcohol intake and self-neglect has a 12-month history of intermittent scaling of his hands and feet associated with a malar rash on his cheeks and a powdery scale on his nose. In addition, he had marked erythema of his tongue and has been complaining of loose stools for several months. He scores low on mini mental state examination, The most likely diagnosisis:', 'Beriberi.', 'Pellagra.', 'Porphyria cutanea tarda.', 'Scurvy.', 'Systemic lupus erythematosus.', 'B', 'Pellagra is classically a disease of the "4 Os": dermatitis, diarrhoea, dementia and death.
It is due to deficiency in vitamin 83 (Niacin).
Pellagra typically spares the nails and hair and can also be caused by deficiency in tryptophan.
Photosensitivity is often present.
6-Mercaptopurine, isoniazid and 5-flurouracil are drugs that can in rare cases cause pellagra.
Beriberi is due to deficiency in vitamin 81 (Thiamine) and typically gives ore-genital dermatitis with encephalopathy, cardiac failure and peripheral neuropathy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (165, 6, 'The phenomenon by which gentle pressure on an intact bulla forces the fluid to spread under the skin away from the site of pressure in pemphigus is known as:', 'Asboe-Hansen''s sign.', 'Darier''s sign.', 'Nikolsky''s sign.', 'Turban''s sign.', 'Trucot''s sign.', 'A', 'Due to the lack of cohesion within the epidermis, its upper layers easily move later ally with slight pressure or rubbing in patients with active pemphigus. This is known as Nlkolsky''s sign.
The bulla-spread phenomenon is when gentle pressure on an intact bulla forces the fluid to spread under the skin away from the site of pressure (Asboe-Hansen''s sign, also referred to as the ''indirect Nikolsky'' or ''Nlkolsky II'' sign).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (166, 6, 'A patient presents with scaly and crusted lesions on the malar region of the face and in other ''seborrhoeic'' areas. Direct immunofluoresence shows in vivo IgG and C3 deposition on cell surfaces of keratinocytes as well as the basement membrane zone. Serology shows presence of circulating antinuclear antibodies. Which of the following is the most likely diagnosis?', 'Bullous pemphigoid.', 'Lupus erythematosus.', 'Paraneoplastic pemphigus.', 'Pemphigus erythematosus.', 'Pemphlgus vulgaris.', 'D', 'Pemphigus erythematosus is a localized variant of pemphigus foliaceus.
Scaly and crusted lesions of pemphigus foliaceus are seen on the malar region of the face and in seborrhoeic distribution.
The term ''pemphigus erythematosus'' describes patients with immunologic features of both lupus erythematosus and pemphigus, i.e. in vivo IgG and C3 deposition on cell surfaces of keratinocytes as well as the basement membrane zone, in addition to circulating antinuclear antibodies.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (167, 6, 'Use of antigen specific ELISA allows for diagnosis of pemphigus. Which of the following best describes ELISA for pemphigus?', 'ELISA cannot predict disease relapse.', 'ELISA scores parallel disease activity.', 'Serum is positive against Dsgl but negative against Dsg3 in mucosaldominant type of pemphigus vulgaris.', 'Serum is positive against Dsglbut negative against Dsg3 in pemphigus vulgaris.', 'Serum is negative against both Dsgl and Dsg3 in mucocutaneous type of pemphigus vulgaris.', 'B', 'Patients'' serum is tested on ELISA plates pre-coated with recombinant Dsgl or Dsg3 protein leading to detection of specific antibodies against Dsgl or Dsg3.
In pemphigus foliaceus the serum is positive against Dsgl but negative against Dsg3.
In mucosal-dominant type of pemphigus vulgaristhe serum is negative against Dsgl but positive against Dsg3.
In mucocutaneous type of pemphigus vulgaris the serum is positive against both Dsgl and Dsg3.
ELISA scores demonstrate parallel fluctuations with disease activitv and are useful in monitoring disease activity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (168, 6, 'Which of the following virus is not been known to be associated with lichen planus (LP)?', 'Hepatitis C (HCV).', 'Human herpes virus-6 (HHV 6).', 'Human herpes virus-7 (HHV 7).', 'Human herpes virus-8 (HHV 8).', 'Transfusion-transmitted virus.', 'D', ',., In several case-control studies, the prevalence of HC.V was higher in patients with LP than in controls. This association seems to be strongest in Japanese and Mediterranean populations.
,., Of the various types of LP, it is the oral form that is most commonly viewed as a manifestation of HCV infection.
,.,Transfusion-transmitted virus (TTV) Is highly prevalent in patients with liver diseases, Including those with chronic HCV infection. Direct role of TTV In causation of lichen planus is lacking.
,., By in situ hybridization and immunohistochemical techniques, HHV-6 was detected in 67-100% of oral LP lesions and it was absent from normal oral tissues.
,., HHV7 DNA has been demonstrated in lesional samples of lichen planus more often than non leslonal LP.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (169, 6, 'One of the following is not useful in differentiating lichen striatus from linear lichen planus (LP):', 'Histology shows lichenoid changes in lichen planus.', 'Hypopigmentation is more often a sequlae of lichen striatus.', 'Lichen planus often results in hyperpigmentation.', 'Pruritus is more commonly a feature of lichen planus.', 'Spontaneous resolution occurs within a short period of time in lichen striatus.', 'A', ',., Differential diagnoses of lichen striatus include linear porokeratosis, linear psoriasis, inflammatory linear verrucous epidermal nevus, linear Darrier''s disease, linear LP, blaschkitis and linedr GVHD.
,., Linear LP and lichen striatus can occasionall''ybe indistinguishable histologicaliy.
,.,Hypopigmentation is a frequent sequela of lichen striatus.
,.,Hyperpigmentation appears more commonly associated with LP.
,., Lichen striatus is also characterized by minimal, if any, pruritus, unlike lichen planus which can be very pruritic.
,., Spontaneous resolution occurs within a short period of time In lichen striatus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (170, 6, 'Of all the pregnancy associated dermatoses, cholestasis of pregnancy is associated with highest incidence of fetal distress. The risk of fetal distress is highest if levels of maternal bile salts are higher than:', 'Sµmol/1.', 'l0µmol/1.', '20µmol/l.', '30µmol/l.', '40 µmol/1.', 'E', 'Cholestasis of pregnancy is defined by:
Generalized pruritus, with or without jaundice.
Absence of viral or drug induced hepatitis.
Absence of primary lesions.
Biochemical abnormalities consistent with cholestasis.
Disappearance of signs and symptoms following pregnancy.
Recurrence during subsequent gestation(s) and oestrogen containing oralcontra-ceptives is common.
Levels of maternal bile salts above 40 µmol/1 are correlated with an increased incidence of fetal (but not maternal) complicatior,s.
Meconium staining and premature labor occur in as many as 45% of patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (171, 6, 'The case of a 23-year-old female medical student, who has recently returned from an elective in Bhutan, is discussed at your local dermato-pathology meeting. She presented with scaly plaques over the shoulders and upper arms alongside systemic upset. Diagnostic skin biopsy demonstrated sarcoidal granuloma, with no plasma cell infiltrate. Both serum ACE and chest radiography have proved reassuring. What next step investigation will likeiy be suggested?', 'Quantiferon.', 'Venereal Disease Research Laboratory test.', 'Fastir.g glucose.', 'Colonoscopy.', 'Bone marrow trephine.', 'D', 'Sarcoidal or naked granulomas consist of loose groupings of epitheloid histiocytes, giant cells and lymphocytes.
Asteroid bodies may also be seen within the cytoplasm of macrophages.
Differential diagnoses include sarcoidosis and Crohn''s disease. Once sarcoidosis has been excluded, colonoscopy would be warranted to exclude metastatic cutaneous Crohn''s disease.
Secondary syphilis can present with sarcoidal granulomas but the absence of plasma cells points away from this diagnosis.
Mycobacterium tuberculosis granulomas classically occur with caseous necrosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (172, 6, 'A 38-year woman is seen in clinic with extensively sun-damaged skin. She points out well-demarcated and entirely asymptomatic areas of fine paper-like wrinklingover her trunk andupper arms that she first noted during a recent pregnancy. No evidence of transepithelial elimination of elastic fibres or fib;osis are seen on diagnostic skin biopsy. What is the most likely diagnosis?', 'Cutaneous morphea.', 'Ehler''s Danlos Syndrome.', 'Acrodermatitis chronica atrophicans.', 'Pseudoxanthoma Elasticum.', 'Mid-dermal elastolysis.', 'E', 'Mid-dermal elastolysis is a rare, acquired, skin condition.
Focal loss of elastic fibres results from increased elastase enzyme activity.
Its exact cause is unknown but associations include ultraviolet radiation, pregnancy and the oral contraceptive pill.
..,It most commonly presents with well-demarcated areas of fine wrinkling but can also manifest with perifollicular papules of reticular erythema.
Transepithelial elimination of elastic fibres is a histological feature characteristic of eiastosis perforans serpiginosa, a condition associated with both Ehlers-Dantos syndrome and pseudoxanthoma elasticum. Other associations include Down''s syndrome, Marfan syndrome, osteogenesis imperfecta, scleroderma, and D-penicillamine.
.., Dermal fibrosis is seen in scarring disorders such as acrodermatitis chronica atrophicans (which also demonstrates dermal atrophy) and cutaneous morphea.
Acrodermatitis chronica atrophicans is associated with Lyme''s disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (173, 6, 'You are asked to review a patient who has developed highly itchy tense blisters around her umbilicus. She is 5 days post-partum and presented with a similar problem after delivery of her first child. You review the histology report a skin biopsy taken at the time. What direct IMf pattern do you anticipate?', 'Linear IgG at DEJ.', 'Granular IgG at DEJ.', 'Linear C3 at DEJ.', 'Granular C3 at DEJ.', 'Linear IgG and C3 at DEJ.', 'C', 'Pemphigoid gest;;tionis occurs with an incidence of approximately 1 In 50,000 in those patients with high risk (DR3 or DR4) HLA types.
Other risk factors include a personal history of the disease, Caucasian heritage and other autoimmune disease. There is also a recognised association with choriocarcinoma and hydatidiform moles.
The target antigen concerns bullous pemphigoid antigen 2 (BP180).
Presentation may rarely be in the first trimester but is more typically in the second or third trimester or post-partum, as here. An important clinical clue is that the itchy lesions commonly start around the umbilicus, before spreading the rest of the torso and other areas such as the intertriglnous areas and extremities. The face, palms and soles are usually spared. Mucosal involvement occurs In fewer than 20% of cases
Diagnosis is with skin biopsy.
H&E analysis demonstrates an identical pattern to bullous pemphigoid, with split at the DEJ.
Direct IMFshows linear C3 in all cases, with additional IgG only seen in approximately 25% of cases.
This contrasts to bullous pemphigoid where the typical pattern on direct IMF is linear IgG and C3 deposition');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (174, 6, 'What perr.entage of patients with linear IgA disease have oral mucous membrane involvement?', '100%.', '25%.', '0%.', '50%.', '75%.', 'D', 'Linear IgA disease is the commonest autoimmune bullous disease in children.
It usually arises spontaneously but sometimes a triggering infection can beidentified.
The classic presentation is with an annular or crown-of-jewels configuration
In adults, the most common association is with medication, especially vancomydn.
Other associations include inflammatory bowel disease, rheumatological disorders and both haematological and non-haernatologica: malignancy.
On skin biopsy, the H&Esection demonstrates a:;ub-epidermal splitwith neutrophilic infiltrate in a linear fashion, and direct IMF demonstrates linear IgA deposition. This contrasts to dermatitis herpetiformis, where granular neutrophils predominate
The treatment of choice, as with many other IgA-associated neutrophilic disorders, is Dapsone.
Second line agents include sulfapyridine');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (175, 6, 'Ophiasis is recognised to be a poor prognostic marker in alopecia areata. What pattern of hair loss doses it describe?', 'Unilateral scalp involvement.', 'Lateral and occipital scalp involvement.', 'Multiple/>3 patches.', 'Eyebrow involvement.', 'Beard involvement.', 'B', 'Other poor prognostic markers in alopecia areata include: DQ7 or DR3 haplotype, family history, early/childhood onset, associated atopy (especially with fillagrin gene mutation) or autoimmune disease, extensive hair loss, nail disease (especially dystrophy) and chronicity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (176, 6, 'You suspect drug-related Churg-Strauss syndrome in a patient you nave oeen treating for chronic urticaria. Which class of drug is likely implicated?', 'Hl-receptor inhibitor.', 'Calcineurin inhibitor.', 'Leukotriene receptor inhibitor.', 'H2-receptor inhibitor.', 'Anti-IgE monoclonal antibody.', 'C', 'Use of montelukast, a leukotriene receptor inhibitor, is c:1ssociated with a higher incidence of Churg-Strauss syndrome. As with non-drug-related cases, p-ANCA levels can be elevated.
Calcineurin inhibitors include ciclosporin (which first must form a complex with cyclophilin-A)
Calcineurin inhibition prevents migration of the NFAT transcription factor into the T-celi nucleus and ultimately results in IL-2 signalling inhibition.
The Anti-IgE monoclonal antibody omallzumab has recently been granted a lice;ice for use as a second-line agent for treatment refractory chronic spontaneous urt;caria');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (177, 6, 'Which of the following medications would you wish to avoid in a patient with urticarial pigmentosa?', 'Propranolol.', 'Hydroxychloroquine.', 'Lithium.', 'Atropine.', 'Terbinafine.', 'D', 'Other medicines that may trigger mast cell degranulation, and thereby worsen mast cell mediated conditions such as urticarial pigmentosa, include: Amphotericin B, neuromuscular blocking agents such as gallamine, opiates, NSAIDs and aspirin, dextran plasma expander, polymyxin B, quinine and reserpine.
The other medications listed are more classically associated with triggering or worsening psoriasis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (178, 6, 'Which of the following statements regarding Raynaud''s phenomenon is correct?', 'Digital skin colour changes are in the order of red, white, then blue.', 'Ergot compounds used in anti-migraine medications improve the condition.', 'This is most commonly seen in patients with systemic lupus erythematosus', 'This is most commonly seen in patients with systemic sclerosis.', 'This is often associated with interstitial lung disease in the presence of connective tissue disease.', 'D', 'Raynaud''s phenomenon is most commonly seen in systemic sclerosis, followed by systemic lupus erythematosus and Sjogren''s syndrome.
The typical digital skin colour changes are white, followed by blue, then red.
Ergot compounds, bleomycin, cisplatin and beta blockers tend to worsen this phenomenon.
Mechanics hands are seen in dermatomyositis and affect the lateral aspects of the digits. There is a strong association with interstitial lung disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (179, 6, 'A 62-year-old man with a background of rheumatoid arthritis presented with redto-brown plaques and nodules on the dorsal aspect of his hands, which have been present for two months. These are mostly asymptomatic and tend to appear on the metacarpophalangeal joints. Full skin examination showed similar plaques and nodules on both his elbows. There are no associated nail changes. Which of the following statements regarding this condition is incorrect?', 'Histology from these lesions typically shows leukocytoclastic vasculitis.', 'Systemic steroids often result in complete resolution of the lesions.', 'The condition can be seen in HIV infected patients.', 'The condition responds well to treatment with dapsone therapy.', 'This condition can be associated with IgA monoclonal gammopathy.', 'B', 'The diagnosis here is erythema elevatum diutinum and can be associated with several haematological abnormalities, including IgA monoclonal gammopathy, myelodys plastic syndrome and multiple myeloma.
The condition responds generally well to dapsone therapy and poorly to systemic steroids.
Histology typically shows leukocytoclastic vasculitis with a neutrophilic infiltrate, which may mimic Sweet''s syndrome and rheumatoid nodule histologically. In chronic stages, fibrosis and cholesterol deposits are often found.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (180, 6, 'A 41-year-old Caucasian man presented with a three-year history of yellow papules coalescing into symmetrical plaques on the axillae, groin and the peri-orbital skin. A biopsy from two separate lesions showed dermal infiltrate with polymorphic cells consisting of foamy histiocytes, which stained negative for CD1a and positive for CD68 and factor XIII. Based on the clinical and histological features, you diagnose xanthomata disseminatum. Which of the following statements regarding this condition is incorrect?', 'Diabetes insipidus can be associated.', 'Rectal mucosal biopsy is often unhelpful.', 'The condition responds poorly to topical steroids.', 'Lipid profile is often normal in these patients.', 'This condition forms part of the Langerhans'' cell histiocytosis.', 'E', 'Xanthomata disseminatum is a non-Langerhans cell histiocytosis and stains negative for both S100 and CD1a - markers of Langerhans cells.
Foamy histiocytes and the presence of Touton giant cells are often observed.
The condition often has normal lipid profile and may be associated with diabetes insipidus due to pituitary involvement.
A rectal mucosal biopsy can be helpful in cases of systemic amyloidosis.
Treatment of xanthomata disseminatum is often challenging although agents such as azathioprine, cyclophosphamide and carbon dioxide laser have been used.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (181, 6, 'Which of the following statements regarding pityriasis lichenoides chronica is correct?', 'Histologically, this has 3 similar appearance to pityriasis lichenoides et varioliformis Acuta (PLEVA).', 'Phototherapy can be useful in this condition.', 'The condition appears predominantly on the face and neck.', 'The lesions tend to heal with significant pitted scarring.', 'Transformation to cutaneous lymphoma never occurs', 'B', 'Eruotions of pityriasis lichenoides chronica are characterised by erythematous to brown macules or slightly raised papules with fine centrally adherent scale "mica scale".
Histologically, the appearance is slightly different than PLEVA, which is characterised by a superficial lymphocytic infiltrate, mild parakeratosis and minimal aoptotickerat inocytes. The granular layer is often preserved.
Transformation to cutaneous lymphomas has been documented in some cases.
This condition tends to affect young adults and is predominantly found on the trunk and upper extremities.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (182, 6, 'Which of the following statements regarding eosinophilic cellulitis (Well''s syndrome) is correct?', 'Dapsone is the first line treatment.', 'Flame figures are pathognomonic of this condition.', 'Peripheral eosinophilia is extremely common and is found in almost all cases.', 'The condition is often progressive with no spontaneous resolution.', 'Vasculitis is absent on histology and direct immunofluoresence is negative.', 'E', 'Systemic corticosteroids are the first line treatment of choice in Well''s syndrome.
Spontaneous resolution often occurs.
Flame figures are found in other eosinophil-mediated dermatoses such as allergic contact dermatitis, bullous pemphigoid and insect biteo:.
Peripheral eosinophilia is found in almost half of the cases.
The presence of Peripheral eosinophilia and organ damage should raise the suspicion of hypereosinophilic syndrome.
Vasculitis is typically absent histologically with negative direct immunofluorescence.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (183, 6, 'Which of the following drugs is most likely to cause drug-induced subacute lupus erythematosus?', 'Bendrofluazide.', 'Ciclosporin.', 'Frusemide.', 'Ibuprofen.', 'Paracetamol.', 'A', 'Thiazidc diuretics are the commonest drugs that may cause drug-induced subacute r.utaneous lupus -?.rythematosus followed by terbinafine, calcium channel blockers and ACE inhibitors.
Frusemide is associated with the development of bullous pemphigoid and photosensitivity but not with subacute cutaneous lupus erythematosus.
Anti-histone antibodies are positive in around 50% of the cases of drug-induced sub acute cutaneous lupus erythematosus as opposed to around 80% in drug-induced systemic lupus erythematosus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (184, 6, 'Sebaceous glands can be found in which cyst walls of the following?', 'Epidermoid cysts.', 'Epidermoid cysts & eruptive vellus hair cysts.', 'Eruptive vellus hair cysts.', 'Pilar cysts.', 'Steatocystoma multiplex.', 'E', 'Sebaceous cysts are found in steatocystoma multiplex and are absent in the other forms of cysts.
Both epidermoid and eruptive vellus hair cysts are composed of epidermal lining.
However, in the latter vellus hair can be found in the contents of the cysts.
Pilar cysts are composed of the outer hair root sheath lining, which is characterised by absence of the granular layer.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (185, 6, 'A 22-year-old man presented with multiple palpable purpura and petechiae on his buttocks and legs three weeks following a sore throat. He also had symptoms of abdominal pain and ankle swelling. In this condition, which of the following statementsis correct?', 'Direct immunofluorescence will show deposition of both IgM and IgG peri-vascularly.', 'Direct immunofluorescence will show IgA deposition peri-vascularly.', 'Pulmonary haemorrhage is the commonest co-morbidity In this condition', 'Renal involvement is extremely uncommon and its presence is often transient.', 'The condition is associated with a higher mortality rate in children compared to adults.', 'B', 'Henoch-Schonlein purpura is an immune-mediated small vessel vasculitis characterised by deposition of IgA complexes in the small blood vessels.
It may affect the skin and kidney.
The conditon may be recurrent with both skin and renal involvement hence monitor Ing for up to six months is recommended even in the absence of any positive urinalysis on the initial investigation.
The disease in adults has a higher morbidity with the potential for chronic renal in volvement compared to children.
The commonest organs affected in this condition are the small Joints, kidney, skin and gut wall.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (186, 6, 'In which of the following conditions is monoclonal gammopathy usually not found?', 'Erythema elevatum diutinum.', 'Lichen planus.', 'Necrobiotic xanthogranuloma.', 'Schnitzler''s syndrome.', 'Scleromyxoedema.', 'B', 'Scleromyxoedema is most likely to be associated with IgG monoclonal gammopathy although other variants may also be possible.
Schnitzler''s syndrome is most likely to be associated with IgM monoclonal gammopathy.
Erythema elevatum diutinum is most likely to be associated with IgA monoclonal gammopathy.
Necrobiotic xanthogranuloma can be associated with any sub-type of monoclonal gammopathy.
other conditions that may be associated with monoclonal gammopathies include cryogobulinaemia types 1 and 2, Sweet''s syndrome and pyoderma gangrenosum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (187, 6, 'Which of the following choices is the major criterion for the diagnosis of systemic mastocytosis?', 'Positivity to CD2/C:D25 on mast cells.', 'Presence of 25% or more mast cells with atypical or spindle-shaped appearance.', 'Presence of c-kit mutations.', 'Presence of large mast cell infiltrate in the bone marrow, spleen or liver.', 'Raised serum tryptase levels.', 'D', 'In order to diagnose systemic mastocytosis one major criterion is required together with the presence of one minor criterion.
All the other choices are minor criteria for the diagnosis of mastocytosis.
The presence of raised serum tryptase levels in cases of cutaneous mastocytosis may indicate the presence of systemic involvement and may therefore necessitate further investigations.
Osteoporosis can occur in cases of systemic mastocytosis.
Patients with systemic mastocytosis are at increased risk of developing anaphylaxis and should avoid drugs that can potentially trigger the mast cells.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (188, 6, 'In which of the following drug-induced reactions is facial oedema a common manifestation?', 'Acute generalized exanthematous pustulosis.', 'Drug-induced lichenoid reaction.', 'Drug reaction with eosinophillia and systemic symptoms.', 'Serum-sickness-like reaction.', 'Stevens-Johnson''s syndrome.', 'C', 'In acute generalized exanthematous pustulosis small monomorphic pustules may appear on the face however facial oedema often occurs in the setting of drug reaction with eosinophilia and systemic symptoms.
Serum-sickness-like reaction presents with fever, arthralgia and urticaria due to a drug, although unlike serum-slcirness reaction, vasculitis is not a feature and the complement levels are within normal range.
Stevens-Johnson''s syndrome affetis the mucosal sites but facial oedema is not a feature of the condition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (189, 6, 'Which of the following is not a proposed pathogenic mechanism for acnevulgaris?', 'Excessive sebum production.', 'Follicular epidermal hyperproliferation.', 'Granuloma formation.', 'Inflammation.', 'Presence and activity of propionibacterium acne.', 'C', 'The pathogenesis of acne is multifaceted, but four basic steps have been identified:
Follicular epidermal hyperproliferation;
Excessive sebum production;
Inflammation;
The presence and activity of Proµionibacterium acnes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (190, 6, 'Which of the following chromosomal aberrations is associated with severe acne?', 'XO.', 'XX.', 'XXX.', 'XY.', 'XYY.', 'E', 'The severe form of acne ''Acne conglobata'' has been reported to be more common and more severe in XYY chromosomal aberration than in normal subjects.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (191, 6, 'A 35-year-old man presented with a 6-month history of mouth ulcers and painful blistering eruption on the trunk accompanied by painful warty growths over the groin and axillae. Widespread erythematous and annular plaques with flaccid blisters on trunk and limbs are present along with exophytic plaques on the axillae, groins and peri-anal skin. Extensive erosions are present on the buccal mucosa and papillomatous vegetating lesions on the angles of the mouth. Skin biopsy shows intra-epidermal neutrophilic microabscesses. Direct immunofluorescence shows epidermal intercellular IgG staining and linear and granular C3 at the dermal-epidermal junction. Indirect immunofluoresence on rat bladder epithelium is negative. What is the most likely diagnosis?', 'Epidermolysis bullosa acquisita.', 'Paraneoplastic pemphigus.', 'Pemphigoid vegetans.', 'Pemphigus vegetans.', 'Pemphigus vulgaris.', 'D', 'Pemphigus vegetans (PV) is the rarest variant of pemphlgus accounting for 2%- 5.7% of cases.
Flaccid bullae or pustules and hypertrophic papillated plaques involve the face, skin folds and oral mucosa.
Vegetative and hypertrophic lesions arise from eroded pustules and bullae.
The two clinical subclasses of PV; Hallopeau and Neumann type have similar histological and immunofluoresence features.
Neumann type follows more aggressive course and its treatment can be challenging.
Oral corticosteroids, dapsone, azathioprine, retinoids, etanercept and extra corporeal photopheresis have been used.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (192, 6, 'Which of the following is associated with flagellate hyperpigmentation?', 'Aciclovir.', 'Bleomycin.', 'Famciclovir.', 'Ribavarin.', 'Valaciclovir.', 'B', 'Certain drugs may produce a specific pattern of hyperpigmentation.
Flagellate hyperpigmentation-bleomycin or zidovudine.
Diffuse hyperpigmentation on the pcllms and soles - cyclophosphamide or doxorubicin.
Localized hyperpigmentation around small joints - bleomycin and doxorubicin.
Melasma-like pigmentation-oestrogen-related hormonal substances and phenytoin-like medications.
Nail unit involvement - zidovudine, psoralens, minocycline, antimalarials and Gold.
Mucosal hyperpigmentation - cyclophosphamide, doxorubicin, zidovudine, minocycline and some heavy metals.
Blue-grey pigmentation in sun-exposed areas - amiodarone.
Yellow-brown to bluish-gray pigmentation on the face, the neck, the lower extremities, and the forearms - hydroxychloroquine.
Exogenous ochronosis - chronic hydroquinone use.
Bluish-gray pigmentation, especially in sun-exposed areas, and pigmentations of the conjunctivae - chlorpromazine and related phenothiazines.
Skin, nails, scleral and oral mucosal, thyroid, bones, and teeth hyperpigmentation - mino:::ycline.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (193, 6, 'A 40-year-old man complains of recurrent burning eruption on the glans penis. Examiniltion shows hyperpigmentation over the glans penis. He has had recurrent episodes over the past 2 years. Which of the following is most likely to be implicated?', 'Aspirin.', 'Erythromycin.', 'Hydrochlorothiazide.', 'Nifedipine.', 'Phenylepherine.', 'A', 'This patient describes symptoms of a fixed drug eruption (FOE).
FOE recurs at the same site with each administration of the drug.
Most common sites for FOE include face and genitalia, but can occur anywhere.
Localised erythema leading to blistering is commonly seen.
Blistering may not always be present.
Hyperpigmentation occurs following resolution of the erythema and blistering.
Most commonly implicated medications include phenolphthalein in laxatives, sulphonamides, beta-lactams antibiotics, tetracyclines,barbiturates, gold, oral contraceptives and aspirin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (194, 6, 'A 60-year-old man was admitted to ICU with sepsis. A few days later he developed pruritus and erythema over the upper trunk associated with angioedema. Which is the most likely cause of his symptoms?', 'Cephalexin.', 'Meropenem.', 'Sulbactam.', 'Tobramycin.', 'Vancomycin.', 'E', 'Pruritus, erythema and angioedema over the upper body are associated with intravenous administration of vancomycin-the so-called red man syndrome.
It is thought to be secondary to histamine release and can be prevented by administering antihistamines. Rifampicin has been reported to cause similar reactions.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (195, 6, 'Which of the following is not true of Grover''s disease?', 'A history of sun-exposure is often forthcoming.', 'ATP2A2 mutations similar to Darier''s disease have been identified.', 'Can resemble Darier''s disease on histology.', 'Features of Hailey-Hailey disease may be seen on histology.', 'The rash can be persistent in some patients.', 'B', 'Grover''s disease (transient acantholytic dermatosis) presents as pruritic, papulovesicular eruption on the trunk.
Seen in adults with a history of chronic sun damage.
Histological examination shows variable focal aciantholytic dyskeratosis resembling, Darier''s disease, Hailey-Hailey disease or pemphigus.
Classic (transient) form resolves within a few months, but a persistent form has been recognized.
Unlike Darier''s disease there is no evidence for genetic predisposition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (196, 6, 'Which of the following types of porokeratoses is not associated with malignant epithelial neoplasm?', 'Diffuse superficial actinic keratosis.', 'Linear porokeratosis.', 'Porokeratosis of Mibelli.', 'Porokeratosis palmaris et plantaris disseminate.', 'Punctate porokeratosis.', 'E', 'Malignant epithelial neoplasms are reported in all sub-types except the punctate variety.
The risk is the highest with linear porokeratosis and giant porokeratosis of Mibelli.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (197, 6, 'Fogo selvagem is a subtype of which of the following?', 'IgA pemphigus.', 'Paraneoplastic pemphigus.', 'Pemphigus erythematosus.', 'Pemphigus foliaceous.', 'Pemphigus vulgaris.', 'D', 'Fogo selvagem is an endemic form of pemphigus foliaceus.
It is endemic in rural Brazil and it means "wild fire" in Portuguese.
It is clinically, histologically, and immunopathologically similar to sporadic pemphigus foliaceus.
The geographic distribution of disease clustering is similar to that of a black fly, Simulium nigrimanum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (198, 6, 'Which of the following statements isincorrect?', 'Guineapig oesophagus is more sensitive for detecting pemphigus foliaceous antibodies.', 'igGstaining is present on the cell surface of epidermal cells in pemphigus vulgaris.', 'Monkey oesophagus is more sensitive for detecting pemphigus vulgaris anti bodies.', 'Pemphigus vulgaris and foliaceous display similar direct immunofluorescence findings.', 'There is no correlation between the titre of circulating anti-cell surface anti body and disease activity in pemphigus vulgaris and foliaceous.', 'E', 'It is usually not possible to differentiate between pemphigus vulgaris and foliaceous on immunofluoresence findings as it is similar in both disorders.
IgG staining is present on the cell surface of epidermal cells throughout the epidermis in both disorders.
In general, monkey oesophagus is more sensitive for detecting pemphigus vulgaris antibodies.
Guniea pig oesophagus is a superior substrate for detecting pemphigus foliaceous antibodies.
There is a positive, correlation between the titre of circulating anti-cell surface an tibodv and the disease activity in pemphigus vulgaris and foliaceous. However, this correlation is not perfect (unlike in bullous pemphigoid where there is no correlation between the antibodies and disease activity).
Disease activity in individual patient does not necessarily correlate with antibody titre; therefore, clinical findings should not be replaced by immunofluoresence titres in monitoring the disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (199, 6, 'Which of the following statements is true regarding drug-induced pemphigus?', 'Direct immunofluoresence is negative.', 'Patients do not exhibit auto-antibodies to desmoglein 1 and desmoglein 3.', 'Pemphigus foliaceous is the commonest morphological pattern.', 'Remission after drug withdrawal is uncommon.', 'Seen commonly after penicillin administration.', 'C', 'The prevalence of pemphigus in penicillamine users is estimated to be approximately 7 percent.
Pemphigus foliaceous is more common than pemphigus vulgaris in these patients.
Direct and indirect immunofluorescence are positive.
Auto-antibodies to sporadic pemphigus antigens desmoglein 1 and desmoglein 3 have been noted.
Most patients go into remission after stopping the offending drug.
ACE inhibitors have been implicated in both pemphigus vulgaris and foliaceous.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (200, 6, 'A 45-year-old woman presents with a few months history of diffuse hair loss. She complains of losing a lot of hair whilst combing. Her past medical history includes breast cancer for which she has recently received chemotherapy. Examination shows diffuse non-scarring alopecia. What is the likely diagnosis?', 'Alopecia areata.', 'Anagen effluvium.', 'Catagen effluvium.', 'Lichen piano pilaris.', 'Telogen effluvium.', 'B', 'Anagen effluvium is usually seen after cancer chemotherapy.
Telogen effluvium can also result from cancer chemotherapy or stress.
Anagen effluvium results from inhibition or arrest of cell division in the hair matrix which leads to narrow weakened segment of the hair shaft that is susceptible to fracture with minimal trauma.
The characteristic finding in anagen effluvium is the tapered fracture of the hair shafts as a result of damage to the matrix.
.. Anagen and telogen effluvium can be differentiatedon pull test, where more anagen hair will be seen.
Pull test is negative in diffuse alopecia areata.
Exclamation hair mark hairs can be seen in alopecia areata.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (201, 6, 'A 34-year-old lady presented with a long-standing painful ulcer on the lateral aspect of the right lower leg which has been presen''i for 6 months and did not respond to various dressings and compression bandages. On examination, there was evidence of livecio reticularis on the lower legs and the patient gives a history of a previouspulmonary embolism and two spontaneous miscarriages. Laboratory examination showed mild thrombocytosis. The most likely diagnosis here is:', 'Antiphospholipid syndrome.', 'Cryoglobulinaemia.', 'Henoch-Schönlein purpura.', 'Polyarteritis nodosa.', 'Venous ulcer.', 'A', 'Painful chronic ulcers in young people can be secondary to vasculitis, and in thiscase, the presence of livedo reticularis, history of pulmonary embolism and miscarriages is highly suggestive of anti-phospholipid syndrome.
Investigations should include a full vasculitis screen and auto-antibodies which include anti-cardiolipin and anti-phospholipid antibodies.
Treatment with aspirin should be commenced.
This condition can co-exist with systemic lupus erythematosus.
Cryoglobulinaemia can present with livedo reticularis and vasculitic lesions. These tend to be acral and exacerbated on exposure to cold temperatures. Although this would still be a possibility in this patient,.;nti-phospholipid syndrome is more likely due to the history of miscarriages and pulmonary emboli.
Henoch-Schonlein purpura is a form of vasculitis where immune complexes withpre dominantly IgA antibodies occur in the buttocks and legs, and may be associated with throat, abdominal pain, arthralgia and renal involvement.
Around 1% of patients may progress to develop end stage renal failure.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (202, 6, 'A 28-year-old man who has been on penicillamine for several years presented with an asymptomatic annular eruption on the right side of the neck which consists of keratotic papules. There is no associated scaling or erythema. The most likely diagnosis is:', 'Elastosis perforans serpiginosa.', 'Erythema annulare centrlfugum.', 'Granuloma annulare.', 'Psoriasis.', 'Tinea corporis.', 'A', 'Elastosis perforans serpiginosa is a disorder in which there is trans-epidermal illumination of elastic fibres.
Although the condition may occur spontaneously, this can also occur secondarv to penicillamine or in patients with Marfan''s or Ehler''s-Danlos syndrome.
The clinical description does not tit with the other diagnoses mentioned (e.g. granuloma annulare does not have a keratotic surface).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (203, 6, 'A 37-year-old lady was referred to the dermatology department with a 3-year history of urticarial lesions that failed to respond to various anti-histamines given by her GP. Further history reveals that the individual wheals persist for days before they disappear. This often leaves post-inflammatory pigmentation. There is also associated bone pain and an associated paraproteinaemia. The most likely diagnosis here is:', 'Muckle-Wells syndrome.', 'Necrobiotic xanthogranuloma.', 'Ordinary spontaneous urticaria.', 'Schnitzler''s syndrome.', 'Urticarial vasculitis.', 'D', 'Schnitzler''s syndrome is a rare disorder which is characterised by the presence of urticariaI-like lesions that often persist for days or even weeks, and is associated with bone pain and paraproteinaemia.
Bone pain can often be severe.
Muckle-Wells syndrome can present with limb pain and an urticarial-like eruption, however, this is often associated with recurrent fever, amyloidosis and deafness. This is an autosomal dominant disorder due to CIASl defect.
Although urticarial vasculitis can present with urticarial lesions that persist for days leaving post inflammatory hyperpigmentation, this is often associated with arthralgia, rather than bone pain.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (204, 6, 'A 34-year-old lady has been troubled with persistent acne over the last 10 years with hirsutism, hair loss and menstrual irregularities. Polycystic ovarian syndrome has bP.en excluded by various hormonal testing and imaging by the gynaecologist.She is on a number of medications, one of which could be the cause of her symptoms. Which of the following medications is most likely to be associated with these symptoms?', 'Ibuprofen.', 'Lithium.', 'Minocycline.', 'Prednisolone.', 'Sodium valproate.', 'E', 'Sodium valproate is an anti-epileptic and can rarely produce an acneiform eruption together with a clinical and biochemical picture that is similar to polycystic ovarian syndrome.
Lithium and prednisolone can both cause acneiform eruptions, however, this if often monomorphic in nature and would not explain the signs of hyperandrogenism.
Minocycline can be used in acne; the possible side effects are a lupus-like syndrome, hepatitis and pigmentation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (205, 6, 'A 26-year-old lady with a history of photosensitivity developed an annular erythematous rash with scaling, predominantly on her shoulders and upper chest following exposure to sunlight. Her laboratory investigations showed a strong positivity to the anti-Ro antibody. She wishes to become pregnant in the near future and has asked whether the foetus can come to any harm. Which of the following statement is true?', 'None of the options.', 'Pregnancy should be strongly discouraged.', 'There is a small risk of congenital heart block of the foetus.', 'There is risk of cleft lip to the foetus.', 'This condition and laboratory findings have no effect on the pregnancy.', 'C', 'Subacute lupus erythematosus and a positive Ro antibody indicate a strong degree of photosensitivity and the risk of developing a congenital heart block in the foetus.
Close collaboration with the obstetricians is required.
There is also a risk of neonatal lupus erythematosus; however, this is often transient and will disappear within the first few months of life due to the passive transfer of IgG antibodies.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (206, 6, 'You demonstrate to a group of medical students that detachment of the epidermis can occur with gentle lateral pressure in certain dermatological conditions. This sign is positive in which of the following conditions?', 'Hailey-Hailey disease.', 'Pemphigus vulgaris.', 'Staphylococcal scalded skin syndrome.', 'Toxic epidermal necrolysis.', 'All of the above.', 'E', 'The Nikolsky''s sign is positive when gentle lateral pressure on the skin leads to shear ing/detachment of the epidermal component.
Second degree burns can also exhibit the Nikolsky''s sign.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (207, 6, 'A patient is referred to you for assessment of bluish discolouration of his proximal fingernails. Blue lanulae" of the nails can occur with which of the following?', 'Darier''s disease.', 'Mepacrine.', 'Potassium permanganate soaks.', 'Pseudomonas aeruginosa.', 'Tetracycline.', 'B', 'Mepacrine use can also give a blue-grey discolouration of the hard palate.
Potassium permanganate soaks can give rise to brown nails.
Tetracycline can cause photo-onycholysls which may be the sole manifestation of phototoxicity.
Pseuclomonasaeruglnosa infection can give rise to green discolouration of the nails.
Oal''ier''s disease may have longitudinal erythro-and/or leukonychia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (208, 6, 'Which of the following does not exhibit antibodies to BPAG2 or its metabolic products?', 'Bullous pemphigoid.', 'Epidermolysis bullosa.', 'Herpes gestationis.', 'Lichen planus pemphigoides.', 'Linear IgA disease.', 'B', 'Antibodies against BPAG2 or its metabolic products are seen in patients with bullous pemphigoid, pemphigoid gestationis, linear IgA disease, cicatricial pemphigoid, and lichen planus pemphigoides.
The clinical appear nce, immunofluoresence and type of infiltrate can help differentiate between these conditions (e.g. neutrophilic infiltrate in linear IgA as opposed to eosinophilic in bullous pemphigoid).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (209, 6, 'Which of the following statements regarding myasthenia gravis, thymoma and pemphigus is false?', 'Irradiation of thymus or thymectomy may not improve the pemphigus dis ease activity.', 'Myasthenia gravis and thymoma are associated with pemphigus vulgaris and pemphigus foliaceous.', 'The course of myasthenia gravis follows the course of pemphigus.', 'Thymic abnormality may either precede or follow the onset of pemphigus.', 'Thymoma may be associated with paraneoplastic pemphigus.', 'C', 'Myasthenia gravis, thymoma, or both have been associated with pemphigus vulgaris and pemphigus foliaceous.
Thymoma may be associated with PV and PF and with paraneoplastic pemphigus.
The course of myasthenia gravis is independent of pemphigus.
Thymic abnormality may either precede or follow the onset of pemphigus.
Irradiation of thymus or thymectomy may not improve pemphigus disease activity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (210, 6, 'Which of the following statements regarding paraneoplastic pemphigus is false?', 'Antibodiestoplakin family proteins are characteristic.', 'Blistering, lichenoid, or erythema multiforme-like lesions may be seen.', 'High fatality from disease complications, including pulmonary involvement with respiratory failure.', 'Most common underlying malignancy is thymoma.', 'Mucosal involvement is common.', 'D', 'Paraneoplastic pemphigus is a rare complication of malignancies of which non- Hodgkin lymphoma or chronic lymphocytic leukaemia are the commonest.
Painful, erosive stomatitis is commonly seen.
Polymorphous cutaneous lesions includingblisters and erosionsmay be seen in addition to morbilliform, or lichenoid lesions.
Anti-plakin antibodies are detected by indirect immunofluorescence against rodent bladder epithelium.
There is high fatality from disease complications, Including sepsis, pulmonary in volvement with respiratory failure or bronchiolitisobliterans.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (211, 6, 'Which of the following is associated with increased risk of internal malignancy?', 'Anti-epiligrin cicatritial pemphigoid.', 'Bullous pemphigoid.', 'Dermatitis herpetiformis.', 'Epidermolysis bullosa acquisita.', 'Linear IgA disease.', 'A', 'The relative risk for cancer increases with anti-epiligrin cicatricial pemphigoid.
The time between blister onset and cancer diagnosis is approximately 14 months.
The risk for cancer appears higher in the first year of disease.
Relative risk for malignancy with anti-epillgrin cicatricial pemphigoid approximates that for adults with dermatomyositis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (212, 6, 'Which of the following is not a feature of Brunsting-Perry pemphigoid?', 'Head and neck involvement is common.', 'Lack of mucous membrane involvement.', 'Milia formation is commonly seen.', 'More common in elderly men.', 'Scarring is common.', 'C', 'Brunsting-Perry pemphigoid is a locally recurrent and scarring sub-epidermal blistering disorder.
Head or neck involvement is common.
Patients are typically elderly.
Brunsting-Perry pemphigoid predominates in elderly men.
Mucous membrane involvement is uncommon.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (213, 6, 'Which of the following is not true regarding pemphigoid gestationis?', 'Can occur post-partum.', 'Direct immunofluorescence shows linear deposition of immunoglobulinG without C3.', 'Newborns may be affected with bullous lesions.', 'Umbilical lesions are characteristic.', 'Usually occurs in the second-third trimester.', 'B', 'Pemphigoid gestationis (PG) is a pruritic, vesiculobullous eruption of acute-onset.
Seen in the second-third trimester or the immediate postpartum period.
Flares may occur around delivery.
Shows a strong association with HLA-DR3, -DR4, and a C4 null allele.
First onset usually on the abdomen and umbilicus.
Spares the face, mucous membranes, palms, and soles.
Newborns may be affected.
Histopathology shows dermo-epidermal separation with numerous eosinophils.
Direct immunofluorescence shows linear deposition of C3 (almost 100%), with or without immunoglobulin G.
Indirect IF only occasionally detects circulating IgG deposition.
Sera from most PG patients react to a 180-kd transmembrane protein with a collagenous domain.
No significant maternal morbidity or mortality.
Associated with a slight increase in premature and small-for-gestational-age births.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (214, 6, 'Which of the following is true regarding the prognosis of Pemphigoid gestationis?', '50% have asymptomatic subsequent pregnancy.', 'May flare in the post-partum period.', 'Most common in prirniparous women.', 'Occurs later with subsequent pregnancy.', 'Recurrences are rare with oral contraceptive and menstruation.', 'B', 'Pemphigoid gestationis has a variable clinical presentation and course.
Spontaneous resolution during the latter part of gestation is common but dramatic post-partum flares may be seen.
Recurrences with menstruation and flares with use of oral contraceptives occur in at least 25%.
Spontaneous disease regression may occur during the third trimester but the disease may flare during parturition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (215, 6, 'Which of the following systemic diseases is most commonly associated with epidermolysis bullosa acquisita?', 'Diabetes mellitus.', 'Inflammatory bowel disease.', 'Pulmonary fibrosis.', 'Rheumatoid arthritis.', 'Systemic lupus erythematosus.', 'B', 'Epidermolysis bullosa acquisita may be associated with various autoimmune systemic diseases:
Inflammatory bowel disease (commonest).
Systemic lupus erythematosus.
Amyloidosis.
Thyroiditis.
Multiple endocrinopathy syndrome.
Rheumatoid arthritis.
Pulmonary fibrosis.
Chronic lymphocytic leukemia.
rhymoma.
Diabetes mellitus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (216, 6, 'Which of the following statements is false?', 'ELISA can differentiate pemphigus vulgaris from pemphigusfoliaceous.', 'ELISA is more sensitive than indirect immunofluoresence for pemphigus vulgaris and pemphigus folicaeous.', 'ELISA ispositive for both desmogleins 3 and 1 in pemphigus vulgaris.', 'ELISA ispositive for desmoglein 1 in mucosal pemphigus vulgaris.', 'ELISA is positive for only desmoglein 1 in pemphigus foliaceous.', 'D', 'Enzyme-linked immunosorbent assay (ELISA) is more sensitive and specific than immunofluorescence in differentiating pemphigus vulgaris from pemphigus foliaceous.
ELISA titer correlates better than that of indirect immunofluorescence with disease activity.
ELISA is positive for desmoglein 3 (but not desmoglein 1) in mucosal pemphigus vulgaris.
ELISA is positive for both desmogleins 3 and 1 in pemphigus vulgaris with both mucosal and skin involvement.
ELISA is positive for only desmoglein 1 in PF.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (217, 6, 'A 48-year-old alcoholic man was admitted with ascites and decompensated liver failure. He was noted to have a purpuric, perifollicular eruption on his legs. Significant bruising was also noted on his abdomen. What investigation would you request to make the diagnosis?', 'Blood pressure.', 'Plasma ascorbic acid levels.', 'Serum pyruvic acid levels.', 'Skin biopsy.', 'Urine dip stick for protein and blood.', 'B', 'Scurvy is characterized by general weakness, anaemia, gingivitis and petichieae.
It is caused by a prolonged deficiency of vitamin C (ascorbic acid) in the diet.
Vitamin C plays a crucial role in the formation of collagen.
It isuncommon in modern society but can still be encountered in high risk population which includes institutionalised patients and alcoholics.
Skin signs of scurvy include perifollicular hyperkeratotic papules, often on the shins.
These appear as reddish/bluish bruise-like spots surrounding hair follicles. The central hairs are twisted like corkscrews that may break easily.
The papules may join together to form large areas of palpable purpura or ecchymoses.
Diagnosis is based on clinical findings.
Plasma ascorbic acid level may help in establishing the diagnosis, but this level tends to reflect the recent dietary intake rather than the actual tissue levels of vitamin C.
Signs of scurvy can occur with low-normal serum levels of vitamin C.
The level of vitamin C in leukocytes more accurately correlates to tissue stores com pared with serum levels because these cells are not affected acutely by circadian rhythm or dietary changes.
Confirmation of the diagnosis can be achieved by resolution following vitamin Cad ministration.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (218, 6, 'A 7O-year old woman is admitted with tense blisters developing on a background of eczematous skin. A skin biopsy is performed for histology and immunofluoresence. Histology confirms your diagnosis of bullous pemphigoid. Which of the following statements is true of immunofluoresence in bullous pemphigoid?', 'Approximately 50% of patients have circulating anti-basement membrane zone IgG.', 'Bullous pemphigoid IgG causes complement activation by the alternate pathway.', 'C3 may be the sole immunoreactant on direct immunofluorescence of peri-lesional skin.', 'Indirect immunofluorescence antibody titer correlates with disease activity.', 'On lM NaCl induced blister, bullous pemphigoid antibodies bind to the floor of the blister.', 'C', 'In pemphigoid, direct immunofluorescence of peri-lesional skin reveals linear deposition of IgG and C3 at the epidermal basement membrane.
Although both C3 and IgG are detected in most patients, C3 may be the sole immunoreactant.
Approximately 70 - 80 % of patients with bullous pemphigoid have circulating anti basement membrane zone IgG.
On artificially splitting the skin with lM NaCl, bullous pemphigoid antibodies bind to the roof of the blister while epidermolysis bullosa acquisita antibodies bind to the floor of the blister.
In bullous pemphigoid, the indirect immunofluorescence antibody titer does not usually correlate with disease extent or activity.
Bullous pemphigoid IgG causes complement activation by the classic pathway, with activation of the alternative pathway by the C3 amplification mechanism.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (219, 6, 'A 40-year-old man presented with a 6-months history of an intensely pruritic eruption which started on his limbs and genitalia. Close examination shows shiny polygonal papules with a violaceus colour; all papules were flat-topped. Examination of the mouth shows a reticular white appearance on both buccal mucosae. The diagnosis here is:', 'Erythema multiforme.', 'Lichen planus.', 'Lymphomatoid papulosis.', 'Psoriasis.', 'Scabies.', 'B', 'The appearance of pruritic, polygonal, purple and plane papules (SPs) Is characteristic of lichen planus.
Oral and genital examination should always be performed when the diagnosis is suspected.
Erosive lichen planus can cause scarring.
Other variants of lichen planus include: hypertrophic, atrophic, drug-induced, lichen planus pemphigoides and lichen planus pigmentosa.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (220, 6, 'A 20-year-old patient presents with depigmented patches on the trunk and limbs. There are no associated symptoms. Which auto-immune condition is most likely to be associated with this condition?', 'Addison''s disease.', 'Alopecia areata.', 'Diabetes mellitus.', 'Pernicious anaemia.', 'Thyroid disease.', 'E', 'Many auto-immune disorders can be associated with vitiligo but thyroid disease is the commonest.
Measurement of thyroid antibodies should be considered in patients with vitiligo as a high titre - even in the presence of normal thyroid function tests indicates the risk for future thyroid disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (221, 6, 'A 32-year-old female presented with a 4-week history of a mildly burning rash on the upper arms and torso. Examination showed erythematous annular and polycyclic plaques with scaling without scarring. She has marked photosensitivity. The presence of which antibod,yn this condition may be associated with a congenital heart block in the foetus?', 'ANA.', 'Anti-La.', 'Anti-Ro.', 'Mi-2.', 'RNP.', 'C', 'The diagnosis is sub-acute lupus erythematosus (LE) which can present in an annular or psoriasiform pattern.
Sub-acute LE can be drug induced with thiazides being the commonest implicated.
Unlike discoid LE, this variant is not associated with scarring.
Anti-Ro antibodies are associated with marked photosensitivity and the risk of developing congenital cardiac defects in the foetus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (222, 6, 'A 60-year-old man presented with a 3-month history of an eruption that consisted of flaccid pustules in the trunk and groin with background erythema. Close examination showed flaccid bullae and pustules containing a fluid level giving the appearance of a hypopyon. Some pustules and bullae had ruptured forming an annular pattern of scaling. The patient had a background of IgAparaprotinaemia. What is the first-line systemic treatment for this condition in the absence of any contra-indications?', 'Dapsone.', 'Phototherapy.', 'Sulphonamides.', 'Tetracyclines.', 'Vitamin E.', 'A', 'The diagnosis here is subcorneal pustular dermatosis, also called Sneddon Wilkinson disease.
The condition can be associated with myeloma or a paraprotinaemla and these should always be investigated once the diagnosis has been made.
Although all the above treatments have been used, dapsone remains the most effective treatment for subcorneal pustular dermatosis.
Dapsone is also very effective for dermatitis herpetiformis and bullous lupus erythematosus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (223, 6, 'A 45-year-old HIV positive pajent develops a widespread rash after he was commenced on co-trimoxazole. You assess the rash and ciarry out a SCORTEN prognostic measurement. Which of the following is not a SCORTEN parameter in the assessment of toxic epidermal necrolysis?', 'Age over 40.', 'C-Reactive Protein.', 'History of malignancy.', 'Serum bicarbonate levels.', 'Serum glucose levels.', 'B', 'SCORTEN has seven parameters which also include serum urea, tachycardia and skin detachment of >10% on the first day of assessment.
The higher the score, the higher the mortality risk (3-5% for one point and >90% for 6-7 points).
The SCORTEN should be measured every 3 days to assess the progress / deterioration.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (224, 6, 'A 26-year-old lady presented to the dermatologist with a 1-week history of painful tender subcutaneous nodules on the anterior aspects of both shins. Initially, tile "lumps" were very red and painful to touch and gradually the colour had changed to bruise-like. On examination, ankle swelling was noted. She denies other symptoms. What is the commonest cause of thiscondition in the U.K.?', 'Actinomycosis.', 'Sarcoidosis.', 'Streptococcal infection.', 'Tuberculosis.', 'Yersinia infection.', 'C', 'The diagnosis is erythema nodosum, of which in the U.K. streptococcal throat infec tion is the commonest cause.
Other causes include sarcoidosis, yersinia, hellcobacter pylori infections, actinomycosis, tuberculosis, pregnancy and the combined contraceptive pill.
Measurement of anti-streptolysin titre 7-10 days following a sore throat can help confirm the streptococcal aetiology in retrospect.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (225, 6, 'A 68-year-old lady was recently treated with isoniazid for prophylaxis of tuberculosis. She presented with an erythematous butterfly rash on the cheeks following sun exposure and reports arthralgia and several mouth ulcers. Her full blood count showed normocytic anaemia, and slight reduced platelet count. Her renal function is normal. Which of the following auto-antibodies will most likely be positive?', 'Anti Jo-1.', 'Anti RNP.', 'Anti-histone.', 'Anti-parietal.', 'Mi-2.', 'C', 'Drug-induced lupus erythematosus, should be considered in older patients with no past history of connective tissue disorders. Anti-histone antibody is positive in the majority of patients with drug-induced lupus (>90%), positive ANA is also seen in these patients.
Common causes of drug-induced lupus include:
Allopurlnol
Clonidine
Danazol
Hydralazine
isoniazid
Lithium
Methyldopa
Penicillamine
In the majority of the cases, drug-induced lupus tends to spare the kidneys, however, if they are involved, double stranded DNA is often positive too.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (226, 6, 'A 16-year-old boy suffered from a sore throat for 2 weeks. Thereafter, he complained of abdominal pain, swollen ankles and a rash on the lower legs. Examination of the rash shows multiple areas of palpable petichiae and purpura. Skin biopsy showed evidence of small vessel vasculitis with IgA deposition in the vascular walls on direct immunofluoresence. What should be the next investigation performed?', 'Erythrocyte Sedimentation Rate.', 'Full blood count.', 'None.', 'Stool culture.', 'Urinalysis and blood pressure.', 'E', 'The diagnosis is Henoch-Schonlein Purpura, which is usually a self-limiting small vessel vasculitis often seen in children and young adults following a sore throat.
Abdominal involvement can occur in around half of the patients.
Measurement of blood pressure and urinalysis to check for renal involvement is essential.
A small percentage of patients (less than 5%), may progress to chronic renal failure.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (227, 6, 'A 16-year-old boy presented to Accident and Emergency for the third time in 1 month with a history of very painful right leg, fever (38°C), joint pains in fingers and knees and myalgia. His blood tests showed evidence of moderate renal impairment, and his father says that one of his cousins had a similar presentation and was treated successfully with colchicine. On examination there was a bright erythema of the leg, mimicking a cellulitis. He had marked raised C-Reactive Protein. The most likely diagnoses here is:', 'Familial Mediterranean fever.', 'Hyper IgE syndrome.', 'Polymyositis.', 'Urticaria.', 'Wegener''s granulomatosis.', 'A', 'Familial Mediterranean fever is an autosomal recessive disorder due to pyrindefi ciency and presents with Intermittent fever, arthritis, cellulitis-like rash on the legs, myalgia and renal impairment.
Treatment with colchicine can be very effective, although more recently anti-IL 1 monoclonal antibody (anakinra) has been found to be very effective in all auto-inflammatory syndromes.
Hyper IgE syndrome presents with recurrent infections with raised serum IgE levels and skin changes which are similar to atopic dermatitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (228, 6, 'A 45-year-old woman presents with a long history of recurrent sinusitis and ear infections. She pre.;ented a month ago to Accident and Emergency with haemoptysis which was thought to be secondary to a ch.,st infection. She was febrile (temperature 38.7°C) and has lost 1 stone in weight over 6 weeks. You note that she has a collapsed nasal bridge, resulting in a saddle nose appearance. Which of the following investigations is most likely to be positive?', 'ANA.', 'Anti-cardiolipin antibody.', 'c-ANCA.', 'p-ANCA.', 'Rheumatoid factor.', 'C', 'Wegener''s granulomatosis presents with recurrent sinusitis, ear involvement, and respiratory Involvement with haemoptysis, arthralgia and saddle nose shape due to collapsed nasal bridge.
Cutaneous involvement is found in around a third of patients, anci often consists of painful small ulcers or vasculitic palpable purpura.
c-ANCA is positive in around 80-90% of the patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (229, 6, 'A 45-year-old man presented with a 6-month history of multiple crusted areas on his scalp, face and central chest. He gives a dear history of flaccid bullae that rupture easily leaving eroded areas that crust. There is no mucosal involvement. Treatment with anti-fungal creams for presumed seborrhoeic dermatitis failed to clear the lesions. Biopsy of one of the lesions showed acantholysis confined to the sub-corneal area and deposits of IgG in the epidermis on immunofluorescence. Which antigen is involved in the pathogenesis of this condition?', 'BP-180.', 'Collagen VII.', 'Desmoglein 1.', 'Desmoglein 3.', 'Laminln-6.', 'C', 'Pemphigus foliaceus is a milder variant of pemphigus vulgaris with flaccid bullae progressing to crusted erosions in a seborrhoeic distribution.
Mucosal involvement is typically absent, and the defect is high in the epidermis in the sub-corneal layer.
Oesmoglein-1 can also be found in pemphigus vulgaris and pemphigus vegetans.
However, in pemphigusvulgaris, Desmoglein 3 is almost always present as well.
Collagen VII is the target antigen in epidermolysis bullosa acquisita.
Laminin-6 is targeted in cicatricial pemphigoid.
BP-180 and BP-230 are the auto-antigens targeted in bullous pemphigoid.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (230, 6, 'A 60-year-old man developed multiple yellow plaques on the peri-orbital skin. Some of the plaques were ulcerated with a few having a telangiectatic component. Biopsy from one of the lesions showed a palisading granuloma with necrobiosis and foamy histiocytes with giant Touton cells. The most appropriate next investigation in this patient would be:', 'Calcium levels.', 'C-Reactive Protein.', 'Erythrocyte Sedimentation Rate.', 'Serum ACE level.', 'Serum electrophoresis and immunoglobulins.', 'E', 'Paraproteinaemia is found in nearly three quarters of the cases of necrobiotic xanthogranuloma.
This is predominantly IgG, however, IgM paraproteinaemia may also occur.
Cryoglobulinaemia can also occur in about a third of the patients; therefort:
cryoglobulin studies should also be performed.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (231, 6, 'A 26-year-old 34-weeks pregnant lady in her third pregnancy developed multiple urticated plaques on her thighs and abdomen with a large urticated plaque involving her umbilicus with some vesicles. She is otherwise well but is extremely concerned about her pregnancy. Which of the following statements regarding this condition is true?', 'A pregnancy termination is often required.', 'Biopsy and immunofluorescence findings would be non-specific in this condition.', 'There is a slightly increased risk of premature labor.', 'This condition has no effect on the foetus and always resolves following post-partum.', 'This condition tends to continue many years after delivery.', 'C', 'Pemphigoid gestationis is a rare pregnancy-related dermatosis that often occurs in the second or third trimester.
It typically presents with urticated plaques or vesicles and bullae, often with umbilical involvement.
There is an Increased risk for prematurity and small for gestational age babies, and less than 10% risk of the neonates have skin lesions.
The condition almost always resolves post-partum, and does not tend to progress to a chronic stage.
immunofluorescence typically shows linear C3 +/- IgG along the basement membrane zone and can be very helpful in distinguishing this condition from the urticated phase of pruritic papules and plaques of pregnancy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (232, 6, 'Which of the following is the commonest recognized cause of recurrent erythema multiforme?', 'Campylobacter.', 'Drugs.', 'Herpes simplex virus.', 'Mycoplasma pneumonia.', 'Yersinia.', 'C', 'Although many factors can trigger erythema multiforme, herpes simplex virus (HSV)
is the commonest known trigger for this self-limiting condition.
In the absence of any identifiable trigger, a long-term (6-24 months) suppressive therapy for HSV such as aciclovir 400 mg twice daily can be given for recurrent erythema multiforme.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (233, 6, 'A 20-year-old man presents with keratotic beaded papules on the nape of the neck. Which of the following disorders is not associated with elastosis perforans serpiginosa?', 'Diabetes mellitus.', 'Down''s syndrome.', 'Ehlers-Danlos syndrome.', 'Marfan''s syndrome.', 'Pseudoxanthoma elasticum.', 'A', 'Elastosis perforans serpiginosa is a perforating disorder characterized by transepidermal elimination of elastic fibers.
Hyperkeratotic papules varying from 2 mm to 1 cm in diameter occur in a serpiginous distribution.
0-penicillamine is associated with the development of elastosis perforans serpiginosa.
The neck is most commonly involved.
Elastosis perforans serpiginosa is associated with Down''s syndrome, acrogeria, Marfan''s syndrome, Ehlers-Danlos syndrome, cutis laxa, osteogenesis imperfecta, Rothmund-Thomson syndrome and pseudoxanthoma elasticum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (234, 6, 'Which of the following statements about immunology of bullous pemphigoid is false?', 'Elevated serum IgE levels correlate with the presence of pruritus.', 'Peripheral blood eosinophilia correlates with serum IgE levels.', 'Peripheral blood eosinophilia is seen in 90% patients.', 'Serum IgE is elevated in 50% patients.', 'Serum IgE levels correlate with IgG anti-basement membrane zone immunofluorescence titers.', 'B', 'Almost 50% of patients with bullous pemphigoid have elevated total serum IgE.
Levels of serum IgE positively correlate with IgG anti-basement membrane zone immunofluorescence titers.
Elevated levels of IgE correlate with thepresence of pruritus.
90% of patients have peripheral blood eosinophilia.
Peripheral blood eosinophilia does not correlate with serum IgE levels.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (235, 6, 'Which of the following is not useful in differentiating epidermolysis bullosa acquisita from porphyria cutanea tarda?', 'Absence of hirsutism in sites affected by epidermolysis bullosa acquisita.', 'IgG and complement deposits at the dermo-epidermal junction in epidermolysis bullosa acquisita.', 'Immune deposits around the dermal blood vessels in porphyria cutanea tarda.', 'Negative urine porphyrin screen in epidermolysis bullosa acquisita.', 'Sclerodermoid skin changes and photo distribution of rash in porphyria cutanea tarda.', 'B', 'Epidermolysis bullosa acquisita may mimic bullous pemphigoid, porphyria cutanea tarda, pseudo-porphyria, bullous lupus erythematosus, cicatritial pemphigoid, linear IgA bullous dermatosis, Brunsting-Perry cicatricial bullous pemphigoid, dystrophic epidermolysis bullosa and rarely other disorders like toxic epidermal necrolysis and dermatitis herpetiformis.
Although the presentation of epidermolysis bullosa acquisita may be reminiscent of porphyria cutanea tarda, these patients do not have other hallmarks of porphyria cutanea tarda or pseudo-porphyria, such as hirsutism, a photodistributionof the eruption, or scleroderma-like changes.
Urinary porphyrlns are within normal limits in epidermolysis bullosa acquisita.
Patients with porphyria cutanea tarda, which may mimic epidermolysis bullosa acquisita clinically, frequently have IgG and complement deposits at the dermo-epider mal junction similar to those of epidermolysis bullosa acquisita patients.
Porphyria cutanea tarda skin also demonstrates immune deposits around the dermal blood vessels, which distinguishes it from epidermolysis bullosa acquisita.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (236, 6, 'A 50-year-old patient is referred with yellow nails. He has a diagnosis of rheumatoid arthritis. Which of the following statements regarding yellow nail syndrome is incorrect?', 'Can be associated with internal malignancies.', 'Can be associated with lichen planus.', 'High doses of vitamin E may be helpful.', 'Patients report failure of nail growth.', 'Spontaneous improvement may be seen.', 'B', 'Yellow nail syndrome may or may not be associated with a systemic disorder.
It is a triad of yellow nails, primary lymphoedema, and pleural effusion.
Nail features include thickening, transverse ridging, diminished growth, increased curvature with a "hump," and onycholysis.
It is occasionally familial.
Respiratory tract involvement is seen and features include sinusitis, bronchiectasis, pleural effusions, upper respiratory infections and pneumonia.
Other conditions that may be associated with yellow nail syndrome include rheumatoid arthritis and internal malignancies.
Patients always claim that their nails have stopped growing.
High oral doses of vitamin E may be beneficial.
Spontaneous improvement is possible.
Topical vitamin E and systemic antifungal medications (itraconazole, fluconazole) do not appear to be effective.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (237, 6, 'Proximal nail splinter haemorrhages are seen in all the following except:', 'Altitude sickness.', 'Anti-phospholipid syndrome.', 'Bacterial endocarditis.', 'Hepatitis A infection.', 'Trichinosis.', 'D', 'The following are causes of proximal nail splinter haemorrhages: bacterial endocarditis, trichinosis, anti-phospholipid syndrome and altitude sickness.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (238, 6, 'Which of the following conditions can give a keratoderma-like yellow appearance of the palms?', 'Diabetes mellitus.', 'Hypothyroidism.', 'Limited systemic sclerosis.', 'Pregnancy.', 'Rheumatoid arthritis.', 'B', 'Rheumatoid arthritis and pregnancy can give palmar erythema.
Limited systemic sclerosis (CREST) gives telangiectasia which can be found on the palms.
Hypothyroidism should always be included in the differential of "yellow palms" particularly when carotinaemia is suspected.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (239, 6, 'The differential diagnosis of "punctate keratoderma" affecting the palms will include all except:', 'Arsenical keratosis.', 'Keratoses of Cowden''s syndrome.', 'Mycosis fungoides (folliculotropic).', 'Palmar porokeratoses.', 'Viral warts.', 'C', 'Punctate palmar keratoderma is an autosomal dominant keratoderma characterized by keratotic plugs, often limited to the palmar creases.
Cowden''s syndrome is an autosomal dominant condition due to PTEN gene defect and can present with palmar keratoses, tricholemmomas, buccal cobblestoning, lipomas, thyroid gland lesions, high-arched palate and adenoid facies.
Follicular or syringotropic mycosis fungoides can present with palmar involvement but not with punctate keratoses.
Although palmar pits are often seen in Darier''s disease, this condition can be associ ated with palmo-plantar keratoses too.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (240, 6, 'A 45-year-old lady with type-1diabetes develops waxy plaques on her shins. You diagnose these as Necrobiosis lipoidica. Which of the following statements regarding necrobiosis lipoidica (NL) is correct?', '30% of patients with diabetes will develop NL.', 'Less than 1% of diabetes patients will develop NL.', 'NL most frequently occurs on the upper trunk.', 'NL occurs exclusively in diabetics.', 'NL often resolves spontaneously.', 'B', 'NL most commonly occurs on the shins and around two-thirds of its sufferers have diabetes.
Less than 1% of patients with diabetes develop NL.
The condition is difficult to treat and may develop areas of ulcerations.
Disease activity appears to be independent from glycaemlc control in diabetics.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (241, 6, 'You diagnose a patient with pyoderma gangrenosum (PG). Which of the following is not a clinical variant/subtype of PG?', 'Bullous.', 'Plaque.', 'Pustular.', 'Ulcerative.', 'Vegetative.', 'B', 'Another variant of PG includes the peri-stomal type which can particularly occur when the underlying inflammatory bowel disease (IBD) is active.
PG can occur in IBD, rheumatoid arthritis, multiple myeloma and carcinoid tumour (rarely).
PG belongs to the group of neutrophilic dermatoses and may respond to corticosteroids, ciclosporin and anti-TNF therapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (242, 6, 'Which of the following subtypes of porokeratosis has the highest risk of malignant transformation?', 'Disseminated superficial actinic porokeratosis.', 'Linear porokeratosis.', 'Porokeratosis of Mibelli.', 'Porokeratosis palmaris et plantaris.', 'Punctate porokeratosis.', 'B', 'Porokeratoses are a group of keratinizing disorders characterized histologically by the presence of a cornoid lamella which is a thin column of parakeratotic cells extending through the stratum corneum with absent granular layer and-occasionally-basal layer dyskeratosis.
The overall risk of transformation to squamous cell carcinoma is low but is highest with the linear subtype.
The commonest variant is disseminated superficial actinic porokeratosis.
Giant porokeatosis of Mibelli can also be associated with a higher risk of malignancy transformation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (243, 6, 'Milia can occur in some genodermatoses and are referred to as "primary milia". Secondary milia can occur in several disorders. In which of the following can milia occur as part of the disease process?', 'Dermatophytosis.', 'Impetigo.', 'Lichen planus.', 'Porphyria cutanea tarda.', 'Psoriasis.', 'D', 'Milia are benign keratinous cysts.
Secondary causes of milia include subepidermal bullous formation (porphyria cutanea tarda, bullous pemphigoid, epidermolysis bullosa acquisita), radiotherapy, thermal burns, acne and allergic contact dermatitis.
Porphyria cutanea tarda presents clinically with skin fragility, bullae, erosions, milia and hypertrichosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (244, 6, 'A 65-year-old woman with end-stage renal failure who attends the haemodialysis unit developed an indurated tender subctaneous plaque on the inner aspect of her right thigh. A reticulate pattern of erythema was evident on her thigh. Biopsy from the lesion which included the subcutaneous fat showed calcification of small vessels with necrosis. In addition to haemodialysis, which other risk factor contributes to the development of this condition?', 'Atopic dermatitis.', 'Heparin use.', 'Irish ancestory.', 'Low serum calcium.', 'Warfarin use.', 'E', 'Calciphylaxis(also called "calcific uraemic arteriopathy") is a disease with a high mortality rate and occurs in the setting of renal failure, particularly in dialysis-dependent patients.
Risk factors include obesity, warfarin use, diabetes mellitus, liver disease, systemic steroid use, raised serum calcium and phosphate product, and raised serum aluminium.
Warfarin may alter the balance of calcification promoters and inhibitors and may need to be switched to heparin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (245, 6, 'Which of the following is the gold standard in the diagnosis of epidermolysis bullosa acquisita?', 'Direct immunofluorescence.', 'Histopathology,', 'Immune-electron microscopy.', 'Indirect salt-split skin immunofluorescence.', 'Western immunoblotting.', 'C', 'Although all the listed options are helpful in establishing the diagnosis of epidermolysis bullosa acquisita by differentiating it from other immunobullous disorders like bullous pemphigoid, immuno-electron microscopy still remains the gold standard in the diagnosis of epidermolysis bullosa acquisita.
Epidermolysis bullosa acquisita lesions have Immune deposits within the sub-lamina densa zone of basement membrane zone.
Deposits in bullous pemphigoid are higher up in the hemidesmosome area or the lamina lucida area of the basement membrane.
In cicatricial pemphigoid, antigenic targets are confined to the lamina lucida.
Western blots of human skin basement membrane proteinscontain type VII collagen.
A new ELISA developed from recombinant, purified, post-translationally modified NC-1In stably transfected human cells is considered more sensitive than immunofluorescence and Western blotting and very specific for antibodies to type VII collagen.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (246, 6, 'Which one of the following forms of pemphigus involves non-stratified squamous epithelium?', 'Drug-induced pemphigus.', 'Paraneoplastic pemphigus.', 'Pemphigus foliaceous.', 'Pemphigus vegetans.', 'Pemphigus vulgaris.', 'B', 'Paraneoplastic pemphigus is the only form of pemphigus that has involvement of non-stratified squamous epithelium.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (247, 6, 'Which of the following is not seen at an increased incidence in dermatitis herpetiformis?', 'Bone demineralization.', 'Dermatomyositis.', 'Gastrointestinal lymphomas.', 'Non-Hodgkin''s lymphoma.', 'Thyroid disease.', 'B', 'Dermatitis herpetiformis is associated with an increased risk for the following:
Gastrointestinal diseases, including: achlorhydria, atrophic gastritis, pernicious anaemia, coeliac disease, malabsorption and bone loss.
Malignancies, including: gastrointestinal and non-Hodgkin''s lymphomas.
Auto-immune diseases, including: thyroid disease, insulin-dependent diabetes, lupus erythematosus, Sjogren''s syndrome, and vitiligo.
Neurologic diseases, including: epilepsy, ataxia, and dementia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (248, 6, 'Which of the following is the least common subtype of morphoea?', 'Generalized morphea.', 'Guttate morphea.', 'Linear scleroderma.', 'Parry-Romberg syndrome.', 'Plaque-type morphea.', 'B', 'Plaque-type morphea is the commonest subtype of morphoea. Other subtypes in decreasing order of frequency include:
Linear scleroderma;
Generalized morphea;
Parry-Romberg syndrome;
En coup de Sabre.
Morphea profunda, guttate morphoea, bullous morphea, keloidal morphoea and pansclerotic morphea of childhood are other rare forms of morphoea.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (249, 6, 'Auto-antibodies can be seen in morphea. Which of the following is not associated with auto-antibody positivity in morphoea?', 'Duration of disease.', 'Number of lesions.', 'Number of sclerotic lesions.', 'Resistance to treatment.', 'Severity of disease.', 'D', 'Serum auto-antibodies have been found with variable frequency in patients with localized scleroderma.
Anti-nuclear antibodies usually with a homogenousimmunofluorescence pattern are most commonly found.
Anti-single stranded DNA and/or anti-histone antibodies may be found with extensive involvement.
Compared with other subsets of localized scleroderma, patients with generalized morphea have a higher frequency of antibody positivity which correlates with a more severe clinical presentation, greater number of lesions, more sclerotic lesions and longer duration of clinical course.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (250, 6, 'Which of the following is not a recognized risk factor for development of Dupuytren''s contracture?', 'Afro-Caribbean descent.', 'Diabetes mellitus.', 'Male sex.', 'Old age.', 'Smoking.', 'A', 'Dupuytren''s contracture (palmar fibromatosis) is a fibroproliferative disease.
Bilateral, progressive fibrosis of the palmar fascia.
Presenting most commonly as nodules over the fourth and fifth metacarpal head.
Joint contractures and flexion deformities may follow.
Significant risk factors for development of Dupuytren''s contracture include old age, male sex (three to four fold increase), white northern European ancestry, family history, seizures, alcohol-induced liver disease, trauma, smoking, and diabetes mellitus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (251, 6, 'All of these can be presenting features of Bazex syndrome exc€pt which one?', 'Facial erythema.', 'Follicular atrophoderma.', 'Hypohidrosis.', 'Hypotrichosis.', 'Multiple basal cell carcinomas.', 'A', 'Bazex syndrome is an X-linked dominant syndrome, which is characterized by follicular atrophoderma, multiple basal cell carcinomas, hypotrichosis, and localized hypohidrosis.
The follicular atrophoderma presents as multiple ice-pick marks or patulous follicles (most commonly on the dorsal sides of the hands).
Associated findings may include facial hyperpigmentation,milia, hair shaft dystrophy, and multiple genital trichoepitheliomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (252, 6, 'Which of the following is associated with elastosis perforans serpiginosa?', 'Dacarbazine.', 'D-penicillamine.', 'Isotretinoin.', 'Metformin.', 'Sulfonylurea.', 'B', 'Elastosis perforans serpiginosa is a perforating disorder characterized by transepider mal elimination of elastic fibers.
Hyperkeratoticpapules varying from 2 mm to 1 cm in diameter occur in a serpiginous distribution.
D-penicillamine is associated with the development of elastosis perforans serpiginosa.
The neck is most commonly involved.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (253, 6, 'Which of the following disorders gives an erythema contusiforme appearance?', 'Erythema gyratumrepens.', 'Erythema migrans.', 'Erythema multiforme.', 'Erythema nodosum leprosum.', 'Erythema nodosum.', 'E', 'The tender erythematous warm nodules and raised plaques of erythema nodosum evolve into red or purplish colour to a yellow or greenish discoloration, resembling a deep bruise-erythema contusiforme.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (254, 6, 'Which of the following panniculitides can demonstrate an isomorphic phenomenon?', 'Cold panniculitis.', 'Erythema nodosum leprosum.', 'Lupus panniculitis.', 'Oxalosis.', 'Pancreatic panniculitis.', 'C', 'Lupus panniculitis is a chronic recurrent panniculitis.
It is a mild variant of lupus erythematosus.
It is more frequent in women than men.
May present as subcutaneous nodules as the only clinical manifestation of the dis ease.
Histological features of discoid lupus erythematosus at the dermal-epidermal junction may be seen in only 20-30% patients.
Lobular panniculitis without vasculitis is the predominant histopathological feature.
An isomorphic phenomenon (Koebner) is frequently seen in patients with lupus panniculitis.
Subcutaneous erythematous nodules often develop or recur at the sites of trauma.
Treatments include topical, intralesional or oral corticosteroids, hydroxychloroquine and dapsone.
An isomorphic phenomenon is also frequent In al-antitr ypsin-deficiencyassociated panniculitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (255, 6, 'Elevated levels of which of the following enzymes is predominantly implicated in pancreatic panniculitis?', 'Amylase.', 'Disacchiradase.', 'Lipase.', 'Maltase.', 'Trypsin.', 'C', 'Pancreatic panniculitis is also termed enzymatic fat necrosis.
It is associated with several pancreatic diseases, including acute and chronic pancreatitis, pancreatic carcinoma, pancreatic pseudocysts, vasculo-pancreatic fistulae, and drug induced pancreatitis.
In some patients there may be no demonstrable pancreatic disease.
Pancreatic enzymes, mostly lipase, seem to be responsible for the subcutaneous fat necrosis.
Presents as erythematous subcutaneous nodules around the ankles and knees that often ulcerate spontaneously.
Histopathologically, mostly lobular panniculitis without vasculitis is evident with an intense necrosis of the adipocytes at the centre of the fat lobules.
Ghost adipocytes are necrotic adipocytes, which have lost their nuclei and contain finely granular and basophilic material within their cytoplasm.
Ghost cells result from saponlfication-hydrolytic action of pancreatic enzymes on fat, followed by calcium deposition.
These ghost adipocytes are characteristic of pancreatic panniculitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (256, 6, 'Which of the following phenotypes is most commonly associated with cx1-antitrypsin-deficiency panniculitis?', 'FF.', 'FM.', 'MS.', 'MZ.', 'ZZ.', 'C', 'The four major categories of a1-antitrypsin genes include: F (fast), M (medium), S (slow), and Z (very slow).
Two alleles determine the specific al-antitrypsin phenotype.
The most common allele associated with normal levels of a1-antitrypsin is M.
S and Z alleles are associated with low serum levels of the enzyme.
ZZ phenotype has severe al-antitrypsin deficiency.
Serious clinical manifestations include emphysema, hepatitis, cirrhosis, vasculitis, and angioedema.
Clinical manifestations of panniculitis include subcutaneous nodules on the lower abdomen, buttocks, and proximal extremities.
Other features include frequent ulceration and isomorphic phenomenon.
Histopathological features include lobular panniculitis without vasculitis, necrosis of the fat lobules with a dense inflammatory infiltrate of neutrophils.
Dapsone is the mainstay treatment for mild disease.
For severe forms of the disease: intravenous infusion of exogenous al-proteinase inhibitor concentrate or genetically engineered al-antitrypsin can be used.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (257, 6, 'Which of the following is the commonest auto-immune disorder associated with vitiligo?', 'Addison''s disease.', 'Alopecia areata.', 'Diabetes mellitus.', 'Pernicious anaemia.', 'Thyroid dysfunction.', 'E', 'Vitiligo is frequently associated with auto-immune disorders.
The commonest is thyroid dysfunction, either hyperthyroidism (Graves'' disease) or hypothyroidism (Hashimoto''s thyroiditis).
Other auto-immune disorders associated with vitiligo include Addison''s disease, pernicious anemia, alopecia areata, and diabetes mellitus.
Patients with auto-immune polyendocrinopathy candidiasis ectodermal dystrophy also have an increased prevalence of vitiligo.');

-- Genito-urinary Disorders & Oral Medicine
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (258, 7, 'Which of the followingtreatments is recommended as first-line in the treatment of vulval lichen sclerosus (LS) according to the British Association of Dermatologists guidelines:', 'Ciclosporin.', 'Moderate potency topical corticosteroids.', 'Systemic corticosteroids.', 'Topical calcineurin inhibitors.', 'Very potent topical corticosteroids.', 'E', 'Clobetaol proprionate ointment is recommended as first-line treatment in vulval LS.
Although. all the other treatments can be used in this condition, very potent topical corticosteroids should be used first-line.
Suspect a concomitant allergic contact dermatitis to perfumes, topical anaesthetics and ciorticosteroids in resistant or "eczematized" cases, in particular with chronic syrnpto''11s and prolonged use of multiple topical agents.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (259, 7, 'A geographic tongue can be found in all the following conditio;,s except:', 'Atopic dermatitis.', 'Down''s syndrome.', 'Pityriasis rubra pilaris.', 'Psoriasis.', 'Reiter''s disease.', 'B', 'Down''s syndrome is associated with macroglossia.
No specific treatment is required for geographic tongue.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (260, 7, 'Which of the following statements is false?', 'Buccal macules in Peutz-Jeghers syndrome may disappear over time.', 'Buccal mucosal macules are a pathognomonic feature of Peutz-Jeghers syndrome.', 'Mutation in the serine/threonine kinase 11 (STKll or LKBl) gene is responsible for more than half of all cases of Peutz-Jeghers syndrome.', 'Pigmented macules in Peutz-Jeghers syndrome are absent at birth.', 'Tile most common malignancies associated with Peutz-Jeghers syndrome are gastrointestinal.', 'A', 'Peutz-Jeghers syndrome is an autosomal dominant malignant predisposition syndrome.
Mucocutaneous pigmentation and intestinal hamartomatous polyposis an:? hallmarks of the disease.
Small hyperpigmented macules appear on the lips and buccal mucosa in childhooo.
Pigmented lesions are not present at birth.
Up macules may disappear over time.
Macules of the buccal mucosa are pathognomonic and do not tend to disappear with time.
Peutz-Jeghers syndrome is associated with internal malignancies.
Of the associated Internal malignancies, gastrointestinal (small intestine, colorectal, stomach, pancreas) malignancies are most common.
Surveillance is therefore required from an early age.
Mutation in the serine/threonine kinase 11 (STKll or LKBl) gene is responsible for more than half of all cases of Peutz-Jeghers syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (261, 7, 'Which of the following is a characteristic feature of Melkersson-Rosenthal syndrome?', 'Geographic tongue.', 'Granulomatous cheilitis.', 'Multiple mucosal neuromas.', 'Painful vegetative papules and ulcerations.', 'Xerostomia.', 'B', 'Granulomatous cheilitis represents acute onset of asymmtric swelling of the upper and less commonly lower lip.
Erythema, scaling, fissuring, and erosions may also develop.
There is prolonged and recurrent course with eventual fixed swelling.
Me.lkersson-Rosenthal syndrome is characterized by lingua plicata ("fissured" or fur rowed tongue), facial paralysis/ptosis, and granulomatous cheilitis.
Granulomatous cheilitis may be the sole manifestation of this syndrome.
Treatment of granulomatous cheilitis is generally unsatisfactory.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (262, 7, 'Which of the following is not associated with geographic tongue?', 'Atopic dermatitis.', 'Diabetes mellituss.', 'Down''s syndrome.', 'Reiter''s syndrome.', 'Vitiligo.', 'E', 'Geographic tongue is a benign inflammatory condition that affects 2% of the population.
It results from loss of filiform papillae.
Erythematous plaques are seen with an annular or serpiginous well-demarcated white border.
A changing geographic appearance is noted with time.
Incidence is increased in patients with more severe or early-onset psoriasis.
Treatment is not needed except in symptomatic patients in whom topical corticosteroids and analgesics may be useful.
Besides psoriasis, geographic tongue is seen in Reiter''s syndrome and is associated with atopic dermatitis, diabetes mellitus, anaemia, hormonal disturbances, Down''s syndrome, and lithium therapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (263, 7, 'Which of the following is associated with fissured tongue?', 'Down''s syndrome.', 'Melkersson-Rosenthal syndrome.', 'Psoriasis.', 'Sjogren.e.yndrome.', 'All of the above.', 'E', 'Fissured tongue (small irregular fissures on lateral dorsal tongue) is also known as lingua plicata and may be a normal variant.
It is also a classic but non-specific feature of Melkersson-Rosenthal syndrome.
Other associated conditions include psoriasis, Down''s syndrome, acromegaly, and Sjogren syndrome.
Regular brushing of the tongue is emphasized to eliminate any associated bacterial overgrowth.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (264, 7, 'Which of the following is the aetiologic agent of oral hairy leukoplakia?', 'Cytomegalovirus.', 'Epstein-Barr virus.', 'Herpes simplex virus.', 'Small pox virus.', 'Varicella zoster virus.', 'B', 'Oral hairy leukoplakia is an asymptomatic condition caused by Epstein-Barr virus.
It presents as corrugated, white plaques with accentuation ofthe vertical folds along the lateral borders of the tongue.
It occurs predominantly in immunosuppressed patients, especially HIV-infected individuals in which it is an AIDS-defining illness.
It may also occur in organ transplant recipients and in patients on chemotherapy.
It responds to aciclovir and cidofovir.
Other anecdotal treatments include topical retinoids, and podophyllin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (265, 7, 'Which of the following is not a known cause of macroglossia?', 'Amyloid.', 'Diabetes.', 'Down''s syndrome.', 'Hypothyroidism.', 'Neurofibromatosis.', 'B', 'Disproportionate enlargement of the tongue relative to the jaw size is called macroglossia.
It may be congenital or acquired.
Pressure against the teeth results in scalloping along the lateral aspects of the tongue.
Problems Include difficulty with mastication and speech and accidental tongue biting are common.
Causes include Down''s syndrome, hypothyroidism, Beckwith-Wiedemann syndrome, neurofibromatosis, Infection by mycobacteria, filamentous bacteria, or fungus.
Macroglossia caused by amyloid deposition results in woody induration of the tongue.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (266, 7, 'Which of the following is not associated with periodontal disease?', 'Cushing''s disease.', 'Diabetes.', 'Down''s syndrome.', 'Human Immunodeficiency Virus.', 'Langerhan''s cell histiocytosis.', 'A', 'Periodontal disease is associated with Human Immunodeficiency Virus, diabetel;, Down''s syndrome, and Langerhans cell histiocytosis.
.... Additionally, children with Papillon-Lefevre syndrome also develop severe and destructive periodontal disease.
Treatment options include oral retinoids in Papillon-Lefevre syndrome, and external beam radiation in periodontal disease of Langerhans cell histiocytosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (267, 7, 'Which of the following is not a recognized cause of gingival hyperplasia?', 'ACE-inhibitors.', 'Calcium channel blockers.', 'Ciclosporin.', 'Leukaemia.', 'Phenytoin.', 'A', 'Causes of glngival hypertrophy include:
-Leuka,;,mi:: hyperplasia e.g. acute myeloblastic and myelomonocytic leukaemia.
-Glycogen storage disease type lb.
Medications e.g. phenytoin, calcium channel blockers, and ciclosporin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (268, 7, 'Which of the following is not true of cyclic neutropaenia?', 'Antibiotics do not help alveolar bone loss.', 'May progress to periodontal disease.', 'Oral ulcers recur at intervals of 21-27 days.', 'Spontaneous improvement may occur.', 'Ulcerative gingivostomatitis is the presenting feature.', 'A', 'Cyclic neutropaenia is an autosomal dominant disorder.
Acyclic decrease in the circulating neutrophils is seen.
It presents with ulcerative gingivostomatitis.
Oral lesions last few days and recur at 21 to 27 day intervals.
Progression to periodontal disease may be seen.
Alveolar bone loss may occur over time.
Spontaneous improvement is seen as neutrophil counts improve.
Systemic antibiotic therapy may prevent bone loss.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (269, 7, 'Which of the following is not associated with labial melanotic ma.:ules?', 'Carney complex.', 'Laugier-Hunziker syndrome.', 'Peutz-Jeghers syndrome.', 'Psoriasis.', 'All of the above.', 'D', 'Multiple lahial melanotic macules are associated with Peutz-Jeghers syndrome, Carney complex, and Laugier-Hunziker syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (270, 7, 'Which of the following is not associated with oral pigmentation?', 'Amiodarone.', 'Anti-malarials.', 'Clofazimine.', 'Minocycline.', 'Rifampicin.', 'E', 'Some medications may induce pigmentary changes of the oral mucosa.
Women appear more susceptible.
The common medications causing intra-oral pigmentary changes include minocycline, anti-malarials, clofazimine, amiodarone and zidovudine.
This acquired pigmentation fades after discontinuation of the implicated medication or it may persist for months to years.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (271, 7, 'A 48-year-old man was admitted with a 6-week history of diarrhoea and burning micturition. He also complained of red, itchy eyes and lower back pain. Examination showed erosions on the glans penis. Which organism is most commonly implicated in the pathogenesis of this condition?', 'Campylobacter.', 'Chlamydia.', 'Salmonella.', 'Shigel/a.', 'Yersinia.', 'A', 'Reiter''s syndrome comprises of classic triad of arthritis, non-gonococcal urethritis, and conjunctivitis.
It is also known as reactive arthritis and may be triggered following an enteric or urogenital infection.
Symptoms appear 1-3 weeks from onset of urethritis/cervicitis or diarrhoea.
It is associated with Human Leukocyte Antigen (HLA)-827.
Dermatological features incude shallow painless ulcers on the meatus and glans penis in a circinate pattern-circinate balanitis.
Hyperkeratotic psoriasiform thickening of palmar/plantar skin may be seen-keratoderma blennorrhagica.
Onychodystrophy and superficial oral ulcers may be present.
The most commonly implicated enteric pathogen in reactive arthritis is Campylobacter.
Chlamydia is the most common cause of non-gonococcal urethritis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (272, 7, 'The commonest site for intra-oral squamous cell carcinoma is?', 'Buccal mucosa.', 'Dorsal tongue.', 'Floor of the mouth.', 'Soft palate.', 'Hard palate.', 'B', 'Squamous cell carcinoma is the commonest type of oral carcinoma and 1s most commonly found in the floor of the mouth.
Squamous cell carcinoma is more common amongst smokers and can arise from a pre-existing plaque of leukoplakia, particularly the verrucous form.
Squamous cell carcinoma can arise on the lips, particularly in smokers and patients with actinic damage.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (273, 7, 'Cobblestoning of the gingiva can occur with all of the following except:', 'Cowden''s syndrome.', 'Crohn''s disease.', 'Darier''s disease.', 'Lipoid proteinosis.', 'Peutz-Jegher syndrome.', 'E', 'Peutz-Jeghers syndrome is associated with intestinal polyps and typically presents with (peri)-oral lentigines.
Other oral manifestations of Crohn''s disease include aphthous ulcerations and granulomatous cheilitis.
The cobblestoning in Darrer''s disease is mostly apparent in the hard palate.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (274, 7, 'A 44-year-old woman with known chronic plaque psoriasis and metabolic syndrome is suspected to have vulval psoriasis. Which of the following anatomical structures will most likely be involved?', 'Mons pubis.', 'Hymen.', 'Labia minora.', 'Labia majora.', 'Urinary meatus.', 'D', 'Genital psoriasis typically presents in the context of more generalised psoriasis but can present in isolation.
Diagnostically helpful features include a symmetrical distribution, marked erythema, occasional fissuring and healing without scarring.
First-line treatment is with a weak or moderate potency steroid.
Bland emollients play an important role in protecting against chemical and mechanical irritation and subsequent koebnerization.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (275, 7, 'A 39-year-old patient has an extremely itchy glistening orange-red plaque over the glans penis and foreskin. You suspect a diagnosis of plasma cell (or Zoon''s) balanitis. What is the most definitive treatment for this condition?', 'Imiquimod cream.', 'Circumcision.', 'Laser destruction.', 'Topical steroid.', 'Topical tacrolimus.', 'B', 'The cause of plasma cell balanitis/vulvitis is not known but established risk factors include poor hygiene and being uncircumcised
Whilst all the listed treatments listed can be used for plasma cell balanitis, only circumcision is reliably curative');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (276, 7, 'What is the risk of developing complicating squamous cell carcinoma in patients with vulval lichen sclerosus?', '1%.', 'Less than 1%.', '5%.', '10%.', '50%.', 'C', 'Lichen sderosus is associated with an increased risk of vulval squamous cell carcinoma, necessitating long-term follow up.
By contrast, penile disease is extremely unlikely to progress to squamous cell carcinoma with only one case reported In the literature.
Extra-genital disease, typically involving asymptomatic white patches with the appearance of cigarette paper, occurs in around 10 % of cases. There is no associated risk of squamous cell carcinoma at these sites.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (277, 7, 'Which of the following is the cardinal feature of Miescher-Melkersson-Rosenthal Syndrome?', 'Cheilitis.', 'Lingua plicata.', 'Mucosal tags.', 'Facial nerve paralysis.', 'Cutaneous lesions.', 'A', '.. Both Miescher-fJlelkersson-Rosenthal Syndrome and Melkersson-Rosenthal Syn drome are part of the orofacial granulomatosis disease spectrum, which can demonstrate all the listed features
Miescher-Melkersson-Rosenthal Syndrome is characterised by granulomatous change confined to the lips
Melkersson-Rosenthal Syndrome is characterised by granulomatous change involving the lips, tongue together with facial nerve paralysis.. Strictly speaking, orofacial granulomatosis is a diagnosis of exclusion that can only be made once systemic granulomatous disease such as Crohn disease, sarcoidosis, TB, Wegener''s granulomatosis and allergic contact dermatitis have been expiored and excluded
Food allergies have been proposed to play a role and in some cases a benzoate/cinnamon-free diet can lead to improvement');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (278, 7, 'Which of the following causes of genital ulceration is not a venereal disease?', 'Beh et''s disease.', 'Chancroid.', 'Granuloma inguinale.', 'Herpes simplex.', 'Primary syphilis.', 'A', 'Recurrent genital ulcerations is a minor criterion for the diagnosis of Beh et''s dis ease.
Other non-venereal causes of genital ulcerations include trauma, tumours, tuberculosis, aphthosis, vesiculobullousdisoroers, Stevens-Johnson syndrome and chemical irritants.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (279, 7, 'A 17-year-old girl has developed very painful erosions in the vulva one week following unprotected sexual intercourse with a new partner. Close examination showed a few intact vesicles on an erythematous base and few eroded areas where previous vesicles were present. The most likely pathogen in this case is:', 'Epstein-Barr virus.', 'Herpes simplex virus.', 'Mycoplasma pneumonia.', 'Staphylococcus aureus.', 'Varicella-zoster virus.', 'B', 'Although traditional teaching is that herpes simplex virus type 1 is predominantly implicated in orolabial herpes and herpes simplex type 2 in genital herpes, both conditions can be caused by either viral serotypes.
Varicella-zoster virus is implicated in shingles, and whilst there are some reports of painful ulceration with fever in females with Epstein Barr Virus.
The morphology of grouped vesicles on an erythematous base is characteristic of herpes simplex Infection.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (280, 7, 'A 50-year-old man presents with peri-anal ulceration. The differential diagnosis of such ulceration includes:', 'Infections.', 'Malignancy.', 'Crohn''s.', 'Nicorandil use.', 'All of the above.', 'E', 'A detailed history and skin examination is required to assess or obtain any valuable clues to the possible aetiology of chronic peri-anal ulceration.
Viral infections such as cytomegalovirus and herpes simplex virus should be suspected in immunocompromised patients.
Squamous cell carcinoma should be included in the differential-particularly if human papillomavirus infection isa risk.
Active underlying Crohn''s disease can lead to metastatic disease which can present with ulceration. The histology in this case will show granulomas.
Genital involvement in Crohn''s is often accompanied by oedema.
Nicorandil use has been incre.:isingly recognized to cause mucosal and cutaneous ulcerations, including in·peri-stomal sites.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (281, 7, 'A 68-year-old lady was recently discharged from the cardiology ward following a second myocardial infarction. She presents with a 6-week history of painful ulcer in the buccal mucosa. The ulcer was oval shaped with an erythematous halo and was extremely tender to touch. She reports no othe;mucosal ulceration and remains well otherwise. She is on a number of cardiac medications. Which of the following is most likely to be the cause of her oral ulceration?', 'Aspirin.', 'Nicorandil.', 'Paracetamol.', 'Propranolol.', 'Simvastatin.', 'B', 'Nicorandil has been increasingly linked to ulceration, both mucosal as well as cuta neous.
Recently, several reports have reported peri-stomal ulcerations and spontaneous bowel perforations.
These only respond to withdrawal of the nicorandil, however healing can take several months.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (282, 7, 'A 40-year-old patient has erosive lichenoid lesions in the oral mucosa. Which of the following is associated with this condition?', 'Hepatitis A.', 'Hepatitis C.', 'Hepatitis D.', 'Hepatitis E.', 'Human Immunodeficiency Virus.', 'B', 'There are reports of association between lichen planus and hepatitis C virus infec tion, chronic active hepatitis, and primary biliary cirrhosis.
Hepatitis should be considered in patients with widespread or unusual presentations of lichen planus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (283, 7, 'A 70-year-old man presents with 20-year history of pigmentation on the lips. Further examination shows linear pigmentation of his fingernails. There is no family history of similar features and his general health has been fine. What is the most likely diagnosis?', 'Cronkhite Canada syndrome.', 'Hermansky-Pudlak syndrome.', 'Laugier- Hunziker syndrome.', 'LEOPARD syndrome.', 'Peutz-Jeghers syndrome.', 'C', 'Laugier- Hunziker syndrome refers to the presence of orolabial pigmented macules and longitudinal melanonychia. It differs from Peutz-Jeghers syndrome in its sporadic occurrence and absence of gastrointestinal involvement.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (284, 7, 'A 35-year-old man presented with a 6-month history of mouth ulcers and painful blistering eruption on the trunk accompanied by painful warty growths over the groin and axillae. Widespread erythematous and annular plaques with flaccid blisters on his trunk and limbs were present along with exophytic plaques on the axillae, groins and peri-anal skin. Extensive erosions were present on the buccal mucosa and papillomatous vegetating lesions on the angles of the mouth. Skin biopsy showed intra-epidermal neutrophilic microabscesses. Direct immunofluorescence and indirect immunofluoresence on rat bladder epithelium were negative. What is the most likely diagnosis?', 'Paraneoplastic pemphigus.', 'Pemphigoid vegetans.', 'Pemphigus Vegetans.', 'Pemphigus vulgaris.', 'Pyodermatitis-pyostomatitis vegetans.', 'E', 'Pyodermatitis-pyostomatitis vegetans is a rare disorder characterized by typical mucocutaneous lesions and histopathological changes of pemphigus vulgaris but negative immunofluorescence findings.
Clinical and histological differentiationofpyodermatitis-pyostomatitisvegetans from pemphigus vegetans can be impossible.
Oral involvement is seen in all cases and cutaneous Involvement in around 60% of patients with PD-PSV.
The occurrence of pustules on the gingiva is very suggestive of pyostomatitis vegetans.
Most patients with PD-PSV have underlying ulcerative colitis (around 50%) or Crohn''s disease (around 10%).
A prompt response to corticosteroids helps differentiating PD-PSV from PY.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (285, 7, 'A 40-year-old man is seen with recurrent oral ulcerations. You suspect Behc;et''s disease. The diagnosis of Behc;et''s disease requires the presence of the major criterion and 2 of the minor criteria according to the International Study Group of Behc;et''s Disease. Which of the following is the major criterion?', 'A non-follicular (predominantly acral) papulo-pustular acneiform eruption.', 'Positive pathergy.', 'Recurrent genital ulcerations (3 or more) in 12 months.', 'Recurrent oral ulcerations (3 or more) per 12 months.', 'Uveitis.', 'D', 'Beh et''s disease is a neutrophilic dermatosis with a vasculitis which is more prevalent in the Middle East and Japan.
The minor criteria (of which at least 2 are required for the diagnosis) are recurrent genital ulcerations, uveitis or retinal vasculitis, cutaneous involvement (non-follicular papulo-pustular eruption or erythema nodosum) and a positive pathergy test.
Joint involvement with arthritis can occur but is not a minor criterion for the diagnosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (286, 7, 'Which of the following is not a recognized risk factor for Peyronie''s disease?', 'Alcohol.', 'Diabetes mellitus.', 'Genetic predisposition.', 'Trauma.', 'Vascular disease.', 'B', 'Peyronie''s disease is fibrosis of the fibrous septa between the corpus spongiosum and the corpora cavernosa along the dorsum of the penis.
It is often associated with Dupuytren''s contracture.
Risk factors include genetic predisposition, trauma to the penis, systemic vascular diseases, smoking and alcohol consumption.');

-- Infectious Disease
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (287, 8, 'A 4-year-old boy presented with generalized tender macular erythema wh;ch was most prominent on the skin around his mouth and nose, and in the groin a,ea. Two days after his hospitalization, the erythematous rash started to desquamate, particularly in his groin area. He was feverish and appeared lethargic, but had no mucoul. membrane involvement and no lymphadenopathy. His mother said that he had a sore throat two days prior to his eruption and has not been on any medication. What is the most likely diagnosis?', 'Cellulitis.', 'Kawasaki''s disease.', 'Netherton''s syndrome.', 'Staphylococcal scalded skin syndrome.', 'Toxic epidermal necrolysis.', 'D', 'Staphylococcal scalded skin syndrome is characterized by generalized tender macular erythema which desquamates within few days, particularly on the skin around the mouth, nose and flexural areas.
Typically, large superficial flaccid bullae may appear on the background of the erythema and leave painful denuded areas.
The child is often lethargic and febrile and the condition is due to staphylococcal exfoliating toxin.
Prompt treatment with anti-staphylococcal antibiotics results in fullrecovery and the prognosis is generally very good.
Toxic epidermal necrolysis would certainly be in the differential, however, this condition is often secondary to drugs and occurs more in adults than children, and often involves the mucous membranes.
Diagnostic biopsy is sometimes required to differentiate the two conditions.
In toxic epidermal necrolysis, full epidermal necrosis is seen with minimal dermal infiltrate.
The defect (split) in staphylococcalscalded skin syndrome is in the subcorneal layer.
Kawasaki''s disease may give rise to desquamation in the flexural area; however, the diagnosis requires the presence of high fever lasting for at least five days and four of the following criteria: conjunctival injection, mucous membrane changes (particularly strawberry tongue appearance), erythema or oedema of the palms and soles, and cervical lymphadenopathy.
Coronary artery aneurysm is one of the main and fatal complications of Kawasaki''s disease, and patients therefore require an echocardiogram.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (288, 8, 'A 43-year-old man presented with a 10-year history of red-brown patches in the axillae with distinct borders and absence of any scaling. The condition was mildly pruritic and scrapings were negative for fungal hypahe or spores. Examination unde, Wood''s light showed coral-pink fluorescence. The organism responsible for this condition is:', 'Bartonella henselae.', 'Corynebacterium minutissimum.', 'Epidermophytonfloccosum.', 'Staphylococcal aureus.', 'Trichophyton verrucosum.', 'B', 'Erythrasma can be treated with topical or oral erythromycin.
Epidermophytonfloccosum may affect the axillae, although it is commonly present in the groins.
It is a fungus that does not fluoresce; scrapings can be positive for microscopy and culture.
Trichophyton verrucosum is a zoophilic dermatophyte found in cattle and usually results in a severe inflammatory dermatomycosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (289, 8, 'Which of the following organisms causes cutaneous larva migrans?', 'Ankylostoma brazilense.', 'Mycobacterium mar/num.', 'Schistosomamansoni.', 'Staphylococcal aureus.', 'Strong/yoides stercoralis.', 'A', 'Cutaneous larva migrans is a pruritic eruption that is caused by the nematode hook worm Ankylostoma brazilense (and in some occasions Ankylostoma caninum), which is deposited in dogs and cats faeces.
It clinically presents with serpiginous vesicular burrows that migrate slowly. The worm cannot penetrate the basement membrane.
Stronglyoides stercoralis, another nematode, causes cutaneous larva c1.irrens which presents similarly with serpiginous urticarial burrows on the buttocks or trunk. This worm however can penetrate the basement membrane and can affect the lungs and the gastrointestinal tract. When it does involve the lungs it may cause Loeffler''s syn drome (pulmonary eosinophilia).
Schistosomes may cause schistosomiasis and "swimmer''s" itch.
Mycobacterium marinum causes fish tank granuloma presenting with red to purple coloured nodules and plaques with sporotrichoid spread.
A further difference between Stronglyoides and Ankylostoma is that the latter mi grates slowly and Stronglyoides typically migrate fast.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (290, 8, 'Which of the following is not a risk factor for (recurrent) cellulitis?', 'Alcohol.', 'Leg ulcer.', 'Lymphoedema.', 'Puncture wound.', 'Tinea Pedis.', 'A', 'Although alcohol and smoking are thought to increase the possible risk for cellulitis, this has not been proven in any study.
Lymphoedema is the strongest risk factor for the development of cellulitis followed by leg ulcers.
The risk of cellulitis increases after each episode due to post-cellulitis residual oedema (mostly secondary lymphoedema) and all the above mentioned factors need to be taken into account when managing patients with cellulitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (291, 8, 'In which group of patients will staphylococcalscalded skin syndrome be associated with a poor prognosis?', 'Afro-Carribeans.', 'Asthmatics.', 'Females.', 'Haemodialysis patients.', 'Males.', 'D', 'Conditions associated with poor prognosis in staphylococcal scalded skin syndrome (SSSS) include diabetes and haemodialysis.
Toxic epidermal necrolysis (TEN) is the main differential diagnosis; however TEN involves the entire epidermis as opposed to SSSS in which the split is at the granular layer.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (292, 8, 'A 23-year-old man presented with a 6-month history of slightly pruritic scaly hypopigmented patches on the shoulders and back which worsen following sun exposure. Examination showed hypopigmented patches with some fine scaling and no loss of hair colour within the patches. What is the most likely diagnosis?', 'Hypopigmented mycosis fungoides.', 'Idiopathic guttate hypomelanosis.', 'Mycosis fungoides.', 'Pityriasis versicolor.', 'Sarcoidosis.', 'D', 'Pityriasisversicolor is caused by the yeast Pityrosporumorbiculare, a lipophilic yeast hence it thrives on the sebaceous-rich areas of the back.
Increased temperature and humidity leads to worsening of the condition.
Vitiligo presents with depigmented patches with no epidermal change.
Poliosis (loss of hair colour) is a sign in vitiligo.
Idiopathic guttate hypomelanosis is an idiopathic condition in which porcelain-white small macules appear predominantly on the lower legs.
Hypopigmented patches can represent rare variants of sarcoidosis and mycosis fungoides.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (293, 8, 'The "two-feet one hand syndrome" refers to the involvement of both feet and a single hand in:', 'Atopic dermatitis.', 'Cellulitis.', 'Mycosis fungoides.', 'Psoriasis.', 'Tinea.', 'E', 'This phrase is used to describe the occurence of tinea manum (often the dominant hand) associated with bilateral tinea pedis.
The commonest cause of tinea pedis is Trichophyton rubrum followed by Trichophyton interdigitale.
Psoriasis, atopic, allergic contact dermatitis as well as mycosis fungoides can all affect both the hands and feet.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (294, 8, 'Which of the following human papillomavirus serotype is not associated with epidermodysplasia verruciformis?', 'HPV-12.', 'HPV-16.', 'HPV-3.', 'HPV-5.', 'HPV-8.', 'B', 'Epidermodysplasia verruciformis present clinically as plain pink to skin-coloured flat papules similar to plain warts.
Epidermodysplasia verruciformis is associated with serotypes 3, 5, 8 and 12.
HPV-16 and 18 are associated with Bowen''s disease, Bowenoid papulosis and cervical cancer.
Histologically, epidermodysplasia verruciformis is characterised by pale keratinocytes in the upper part of the epidermis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (295, 8, 'A 62-year-old man who is seriously ill in intensive care with neutropaenia on a background of chronic myeloid leukaemia developed several erythematous and purpuric macules on his thigh and lower back, which rapidly developed into haemorrhagic bullae which ruptured leaving ulcers with eschars. There was a surrounding erythematous violaceous necrotic area of skin. Blood cultures will most likely show which of the following organisms?', 'Escherichia coli.', 'Neisseria meningitides.', 'Pseudomonas aeruginosa.', 'Staphylococcus aureus.', 'Streptococcus pyogenes.', 'C', 'Ecthyma gangrenosum is often a manifestation of sepsis secondary to pseudomonas aeruginosa.
Predisposing causes include neutropaenia, haematological malignancies, immunodeficiency syndromes, chemotherapy, burns and indwelling catheters.
The main differential diagnosis is of pyoderma gangrenosum which is not associated with septicaemia.
In rare cases, ecthyma gangrenosum can be caused by other organisms such as escherichia coli and neisseria meningitidis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (296, 8, 'A 65-year-old Caucasian man, who works for an international company recently returned from a foreign trip where he was working for six months. He recalled being bitten by an insect on his right cheek arid gradually developed a small papule which has become ulcerated. You suspect cutaneous leishmaniasis and have tciken a biopsy for both histology and culture. Which of the following leishmaniasis species causes visceral leishmanisis only with no cutaneous lesions?', 'L.brasiliensis.', 'L.donovani.', 'L.major.', 'L.mexicana.', 'L.tropica.', 'B', 'Lelshmaniasisdonovani is the only leishmaniasis species tilat causes visceral leishmaniasis and typically presents with pancytopenia and splenomegaly due to involvement of both the spleen and bone marrow.
All other leishmaniasis species give cutaneous lesions that are div,ded into new and old world cutaneous leishmaniasis.
Old world cutaneous leishmaniasis is due to L.tropica, L.major, L.ethiopica and L.in fantum.
New world leishmaniasis is due to L.brasiliensis and L.mexicana. "'' L.brasiliensis can result in mucosal involvement.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (297, 8, 'Which of the following statements regarding cat scratch disease is incorrect?', 'Bartonellosis is the disseminated form of the infection in the im munocompromised host.', 'Bacillary angiomatcsis is the cutaneous-limited manifestation of Bartonella henselae.', 'Lymphadenopathy may occur in half of the cases.', 'The condition is self-limiting in immunocompetents and therefore conservative management is appropriate.', 'The responsible organism is Bartonella henselae.', 'C', 'Lymphadenopathy is found in 100% of cases of cat suatch disease.
The condition is common in children and presents with a papulo-pustular eruption with scratch marks, mostly on the hands.
Azithromycin has been used in some cases but no treatment is required in immunocompetent individuals.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (298, 8, 'A 36-year-old patient develops an expanding rash on her left thigh after a tick bite. If untreated she is has a highest risk of developing:', 'Cardiac block.', 'Facial nerve paralysis.', 'Knee Arthritis.', 'Persistent headaches.', 'Pleurisy.', 'C', 'Erythema chronlcum migrans is seen in 60-90% of patients diagnosed with Lyme disease.
If untreated, approximately 60% of patients will go on to have oligoarticular arthritis (usually the knee).
Approximately 10% develop a neurologic manifestation such as facial nerve palsy.
Approximately 5% develop a cardiac complication such as varying degrees of atrioventricular block).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (299, 8, 'The second member of a family who have recently installed a hot-tub in their back garden presents to your clinic with follicular-based papules and pustules predominantly distributed over the torso, buttocks and legs. What is the most probable causative agent?', 'Streptococcus.', 'Pseudomonas aeroginosa.', 'Hepatitis C.', 'Staphylococcus aureus.', 'HIV.', 'B', 'The number of privately owned hut-tubs in the UK is estimated at 100,000 and is rising.
In turn, cases of hot-tub folliculitis - a condition caused by the opportunistic pathogen Pseudomonas aeroginosa and thought to arise from inadequate chlorination - are also increasing.
Diagnosis is largely clinical, with a predominantly truncal eruption appearing within a few days of exposure to contaminated water.
Typically, the condition is self-limiting and requires no treatment. Extensive disease, especially in immunosuppressed individuals, may necessitate anti-gram negative systemic therapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (300, 8, 'A haematology colleague asks for your opinion on a 38-year-old female, with newly-diagnosed lupus-related leukopaenia, who now presents with pearly umbilicated papules over her breasts and hands. Her otherwise well 11-month old child has crops of similar lesions. What is the causative agent?', 'Human papilloma virus.', 'Enterovirus.', 'DNA pox virus.', 'Herpes simplex virus.', 'RNA pox virus.', 'C', 'Molluscumcontagiosum is a DNA poxvirus, as is Orf virus
Diagnosis of SLE is based on a combination of clinical findings and laboratory evi den,:e. The American College of Rheumatology (ACR) uses a standard diagnostic classification requiring at least 4 out of the following 11 criteria to be met: Matar rash, discoid rash. photosensitivity, oral ulcers, non-erosive arthritis, pleuritis or pericarditis, renal dysfunction, neurological dysfunction, haematological disorder (such as leukopaenia), immunological disorder and positive antinuclear antibody.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (301, 8, 'A middle-aged business man who travels extensively abroad has a monomorphic follicular eruption over the face and trunk. Diagnostic skin biopsy demonstrates a dense eosinophilic peri-follicular infiltrate. He denies taking any prescription, overthe-counter or herbal remedies. What is the most likely underlying diagnosis?', 'Hepatitis C.', 'Propionibacterium acnes.', 'Pseudomonas aeroginosa.', 'Acneiform drug reaction.', 'HIV.', 'E', 'Eosinophilic folliculitis is a feature of cell-mediated immunodeficiency, although nc definitive infective aetiology has been identified.
With HIV infection it is seen when the CD4 lymphocyte count falls below 300 cells/ mm3 and typically improves with Highly Active Anti-Retroviral Therapy.
Papuloerythroderma of Ofuji or "Ofuji disease" is a variant of eosinophilic folliculitis that is typically found in Japan and is not associated with immunodeficiency.
PQ.7.63');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (302, 8, 'A 55-year patient with a history of self-neglect and features of malnutrition is admitted with an infective exacerbation of chronic obstructive pulmonary disease necessitating systemic steroids. On day 7 of admission he develops haemorrhagic bullae over h;s buttocks, groins and inner thighs that break do11,n to leave deep purulent ulcers. Which causative agent would you expect to identify on blood culture?', 'Escherichia coli.', 'Pseudomonas aeriginosa.', 'Neisseria meningitis.', 'Staphyloccus aureus.', 'Aeromonashydrophila.', 'B', 'Ecthyma gangrenosum results from haematogenous spread of infective agents.
Pseudomonas aeriginosa is the most common cause but all those listed c.an be causal agents.
Fungal infections such as Aspergillosis, Candida and Zygomycosis may also cause ecthyma gangrenosum.
It usually occurs in immune-compromised or severely unwell patients.
Characteristic lesions concern haemorrhagic pustules that evolve into deep necrotic ulcers.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (303, 8, 'A GP refers a 17-year-old veterinary nurse trainee with suspected Catch Scratch Disease. If her suspicion is correct, what is the likelihood that the patient with have lympadenopathy?', '0%.', '75%.', '50%.', '25%.', '100%.', 'E', 'Catch scratch disease is caused by Bartonella henselae.
Localised, tender lymphadenopathy occurs distal to theiteofa bite or scratch 1-3 weeks after inoculation.
A discrete papule or vesicle may also be seen at the site of Inoculation.
Approximately SO% patients experience systemic symptoms such as fever, headache and malaise.
In immunocompetent individuals, the infection is self-limiting, with conservative management appropriate.
immunocompromised patients, however, are at significant risk of developing com plications such as bacillary angiomatosis (a vascular lesion that may extend from the skin and soft tissue into underlying to bone) and require treatment with antimicrobials such as azithromycin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (304, 8, 'A 24-year-old man presented with a three month history of asymptomatic generalized maculopapular eruption, on his trunk and extremities. He also had some small, smooth grey patches on his tongue and has been complaining of headaches for four weeks. Further questioning revealed a recent history of unprotected sexual intercourse. Which of the following statements in this condition is correct?', 'A vesiculo-bullous eruption is common.', 'Argyll-Robertson pupil is a common finding.', 'Histology often shows parakeratosis, lichenoid changes and erythrocyte extravasation in the absence of plasma cells.', 'Potential adverse reactions occurring within the first 24 hours of therapy include headache, myalgia and worsening of the eruption.', 'Response to Penicillin is generally very poor.', 'D', 'Jarisch-Herxheimer reaction is an acute febrile reaction that can occur within the first 24 hours of therapy of secondary syphilis.
Syphilis responds very well to treatment with penicillin.
Dark field microscopy is often of limited value in oral lesions due to the presence of saprophytic spirochetes in the oral cavity.
Pupillary constriction with convergence accommodation but no reaction to strong light describes Argyll-Robertson pupils which is a feature of tertiary syphilis.
Histologically, secondary syphilis is characterised by a superficial and deep peri-vascular infiltrate containing plasma cells.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (305, 8, 'Borreli:;i borgderfori has been linked to the pathogenesis of all of the following except:', 'Acrodermatitis chronica atrophicans.', 'Erythema chronicum migrans.', 'Marginal zone B cell lymphoma.', 'Morphea.', 'Rocky mountain spotted fever.', 'E', 'Rocky mountain spotted fever is caused by Rickettsia rickettsii and can present with a maculo-papular eruption around the wrists and ankles which may become haemorrhagic and purpuric.
Marginal zone B cell lymphoma has been associated with Borrelia in Europe and pa tients ore often screened for this infelition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (306, 8, 'Which of the following is associated with black, necrotic palatal ulceration in insulin-dependent diabetics with poor diabetic control?', 'Coccidiomycosis.', 'Cryptococcus.', 'Histoplasmosis.', 'Mucormycosis.', 'Para-coccidioidomycosis.', 'D', 'Rhinocerebral form of zygomycosis is associated with black, necrotic, palatal ulceration.
It is associated with poorly controlled insulin-dependent diabetes and keto-acidosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (307, 8, 'A 35-year-old East Timorian immigrant presents with multiple numerous, variable-sized erythematous and dusky annular macules, ill-defined patches and well-demarcated plaques scattered across the trunk, arms, proximal legs and the face. He complains of hand and feet numbness. Which of the following is the most likely diagnosis?', 'Kaposi sarcoma.', 'Leprosy.', 'Phaeohyphomycosis.', 'Syphilis.', 'Tuberculosis verruca cutis.', 'B', 'Diagnosis of leprosy is primarily clinical and is based on presence of one of following three features-hypopigmented or erythematous patches with definite loss of sensation, thickened peripheral nerves and acid-fast bacilli on skin smears or biopsy material.
Histology is the gold standard for diagnosis of leprosy.
Identification of endoneuritis (nerve disruption and fragmentation) which can be difficult on haematoxylin and eosin is helped by S100 stain which enables differentiation of tuberculoid leprosy from other cutaneous granulomatous diseases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (308, 8, 'Which of the following is thought to be secondary to mycobacterium tuberculosis infection?', 'Erythema induratum of Bazin.', 'Erythema nodosum leprosum.', 'Leukocytoclastic vasculitis.', 'Oxalosis.', 'Sclerosing panniculitis', 'A', 'Erythema induratum of Bazin and nodular vasculitis describe the most common form of lobular panniculitis with vasculitis.
The term erythema induratum of Bazin is used for cases in which an aetiologic relationship with tuberculosis is demonstrated.
Presents as erythematous subcutaneous nodules and plaques on the posterior as pectsof the lower legs, which may ulcerate and heal with scarring,
Polymerase chain reaction may demonstrate mycobacterium tuberculosis DNA in skin biopsy specimens of patients with erythema induratum of Bazin.
A full course of anti-tuberculosis triple-agent therapy should be Instituted when mycobacterium tuberculosis DNA Is isolated.
Other therapeutic measures include potassium iodide, supporting bandages, bed rest, and non-steroidal anti-inflammatory drugs.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (309, 8, 'Which of the following is associated with "leopard skin" pattern of depigmentation?', 'BeJel.', 'Leishmaniasis.', 'Onchocerciasis.', 'Pinta.', 'Yaws.', 'C', 'Several infections can result in pigmentary changes in the skin.
Onchocercaldepigmentation or "leopard skin" is the commonest feature of onchocerciasis and is rarely associated with pruritus.
It presents as hypopigmented patches with peri-follicular spots of normally pigmented skin, typically on the pre-tibial area of older people in endemic areas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (310, 8, 'A 21-year-old man presented with a maculo-papular eruption on the trunk with inguinal lymphadenopathy and a painless penile ulcer. History reveals that he had unprotected sexual intercourse few months before the onset of eruption. Darkfield microscopy showed the presence of treponemas. In the absence of any allergies, the first-line antibiotic in this condition is:', 'Ceftriaxone.', 'Doxycycline.', 'Erythromycin.', 'Penicillin.', 'Tetracycline.', 'D', 'The diagnosis in this case is secondary syphilis with primary chancre and should al ways be considered in the differential of a painless genital ulcer (chancre).
Secondary syphilis can present as maculo-papular eruption which typically involves the palms.
Other conditions that result in macular palmar involvement are HIV-seroconversion and erythema multiforme.
Penicillins are the first-line treatment in syphilis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (311, 8, 'A 5-year-old boy presented to the dermatologist with a 3-month history of progressive development of bald patches on the scalp, with pruritus and some discharging areas. On examination, there were scaly patches of alopecia with some pustules and broken hairs. Wood''s light examination showed positive fluorescence. The parents report that they keep pets at home. What is the most likely organism in this case?', 'Microsporum canis.', 'Microsporum nanum.', 'Trichophyton rubrum.', 'Trichophyton tonsurans.', 'Trichophyton verrucosum.', 'A', 'The history here is highly suggestive of a zoophilic dermatophyte infection of which Microsporum canis is the commonest.
The commonest sources of microsporum canis are cats and dogs.
Trichophyton verrucosum is also a zoophilic species; however, this is often found in cattle and infected patients develop a very inflammatory kerion-like inflammation.
Trichophyton tonsurans and Trichophyton rubrum are both anthropophilic (human to human spread), and do not fluoresce under Wood''s light.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (312, 8, 'An 8-year-old girl returned back from a visit to Connecticut, USA, where she was visiting her relatives. She was complaining of a slightly pruritic erythematous rash in tr lower leg, which seemed to be expanding, though on further questioning she recalls being bitten by an insect whilst on a picnic. What is the most appropriate antibiotic of choice in this case?', 'Amoxicillin.', 'Doxycycline.', 'Gentamycin.', 'Tetracycline.', 'Vancomycin.', 'A', 'The history and clinical examination point towards a diagnosis of erythema annulare centrifugum / Lyme''s disease secondary to tick bite.
These ticks are commonly found in some areas of the world. The name Lyme, relates to a town in Conn.:cticut where these cases were first reported.
Although doxycycline would be the treatment of choice, this would be contra-;ndi cated in view of patient''s age.
Amoxicillin would be the second choice in the absence of penicillin allergy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (313, 8, 'A 14-year-old girl is seen in your clinic with fever and a rash. On examination of the oral mucosa, Forschheimer spots are seen. W at are Forschheimer spots a feature of?', 'Hand-foot-and mouth disease.', 'Herpangina.', 'Measles.', 'Roseola infantum.', 'Rubella.', 'E', 'Forlichheimer spots are small erythematous macules on the palate seen in Rubella (German measles).
They are not a feature of congenital rubella.
White "Koplik" spots are characteristic of measles.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (314, 8, 'A 26-year-old atopic patient is admitted with eczema herpeticum. Eczema herpeticum can complicate all of the following except:', 'Darier''s disease.', 'Mycosis fungoides.', 'Pemphigus vulgaris.', 'Psoriasis.', 'Seborrhoeic dermatitis.', 'D', 'Eczema herpeticum is the presence of disseminated herpes in the setting of underlying skin diseases (most commonly, atopic eczema).
Besides atopic eczema, eczema herpeticum has also been associated with seborrhoeic dermatitis, Darier''s disease, pemphigus vulgaris, mycosis fungoides, WiskottAldrich disease, congenital ichthyosiform erythroderma, and second degree burns.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (315, 8, 'A 45-year-old Nigerian man presents with a solitary hyperpigmentedirregular macule on the palmar surface of the hand. Microscopy of skin scrapings treated with 20% KOH reveal thick, septate, branching hyphae that contain a dark pigment in their walls. What is the most likely diagnosis?', 'Black Piedra.', 'Syphilis.', 'Tinea Mannum.', 'Tinea nigra.', 'Tinea Vericolor.', 'D', 'Tinea nigra is an uncommon superficial dermatomycosis usually caused by Hortaeawerneckll which is classified in the family Dematiaceae.
Tinea nigra appears as a hyperpigmented macule, which usually occurs on the palms.
Tinea nigra is a superficial mycosis of the stratum corneum.
Infection is believed to occur as a result of inoculation from a contaminated source such as soil, sewage, wood, or compost.
Microscopic examination of skin scrapings treated with 20% KOH reveals thick, septate, branching hyphae that contain a dark pigment in their walls.
Topical application of antifungal agents e.g. clotrimazole or ketoconazole usually lead to resolution of tinea nigra within 2-4 weeks.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (316, 8, 'A 30-year-old farmer was admitted with multiple nodules on the left leg in a sporotrichoid pattern. Gram stain of the clinical specimen showed thin, gram-positive branching filamentous bacteria, weakly positive with acid-fast staining. Which of the following is the most likely diagnosis?', 'Actinomycetoma.', 'Actinomycosis.', 'Botryomycosis.', 'Mycetoma.', 'Nocardiosis.', 'E', 'Nocardiosis is caused by aerobic Gram-positive filamentous bacteria.
It has a worldwide distribution, and is an environmentally acquired infection, due to primary traumatic inoculation.
Pulmonary infections are mostly seen in immunocompromised patients and skin infections mostly in immunocompetent patients.
Skin diseases are mostly caused by N. brasiliensis and less commonly N. asteroldes, N. otidiscaviarum, and N. farcinica.
Cutaneous nocardiosis occurs either as cellulitis or more characteristic lymphocutaneousncdules in a sporotrichoid pattern.
Skin lesions also occur in disseminated disease.
Diagnosis is based on Gram stain of clinical specimen which shows thin, gram-positive branching bacteria, weakly positive with acid-fast staining.
Microbiologic isolation of Nocardia sp. is diagnostic, but requires keeping cultures under observation for 5 to 7 days.
Treatment of choice is sulfonamides.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (317, 8, 'A 25-year-old Asian man is admitted with painful and tender, bright-pink, dermal and subcutanem;s nodules. He is febrile and anorexic. He has been receiving anti leprosy treatment. Which of the following subtypes of leprosy was the most likely primary diagnosis?', 'Borderline lepromatous.', 'Borderline tuberculoid.', 'Lepromatous.', 'Mid borderline.', 'Tuberculoid.', 'C', 'Erythema nodosum leprosum (type II reaction) occurs most often in lepromatous leprosy (75%).
It may occur before, during, or after chemotherapy.
The median time of onset is almost 1 year after onset of treatment.
It is characterized by crops of painful and tender bright-pink, dermal and subcutaneous nodules arising in clinically normal skin., in association with fever, anorexia, and malaise.
Arthralgia and arthritis are commonly seen.
Neuritis, adenitis, orchitis/epididymitis or iritis, may rarely be the initial presentation.
A neutrophilic leukocytosisis seen.
Thalidomide is the treatment of choice.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (318, 8, 'A 23-year-old returning traveler presents with a creeping eruption on her foot. All of the following are recognized treatments for this eruption except:', 'Oral albendazole.', 'Oral ivermectin.', 'Oral thiabendazole.', 'Topical albendazole.', 'Topical thiabendazole.', 'D', 'Cut;meous larva migrans infection results in a creeping eruption that occurs when the larvae of dog or cat hookworm (Ankylostoma duodenale and Ankylostoma bra zliense) penetrate intact, exposed skin and begin migrating through the epidermis.
This gives rise to tingling/prickling at the site of exposure within 30 minutes of penetration of the larvae.
Pruritic, erythematous, linear, serpiginious advancingiesions track 3-4 cm from the penetration site.
Thiabendazole is the agent of choice in cutaneous larva migrans.
Topical application is used for early, localized lesions.
The oral route is preferred for widespread eruption.
Other effective alternative treatments include oral albendazole, mebendazole, and ivermectin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (319, 8, 'A 45-year-old man has proximal subungual onychomycosis. Which of the following underlying illnesses should be excluded in this patient?', 'Alopecia areata.', 'Atopic dermatitis.', 'Human immunodeficiency virus infection.', 'Irritant dermatitis.', 'Psoriasis.', 'C', 'Proximal subungual onychomycosis is an uncommon variant of dermatophyte infec tion caused by T. rubrum and is often related to intercurrent disease.
Paronychia is not a feature.
immunosuppressed patients, especially those who are human immunodeficiency vi rus-positive, may present with proximal subungual onychomycosis.
Other associations of proximal subungual onychomycosis include peripheral vascular disease and diabetes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (320, 8, 'Which of the following is the commonest variant of onychomycosis?', 'Candidal onychomycosis.', 'Distal and lateral subungual onychomycosis.', 'Pro)(imal subungual onychomycosis.', 'Superficial white onychomycosis.', 'Total dvstrophic onychomycosis.', 'B', 'Onychomycosis is classified clinically as distal and lateral subungual onychomycosis (DLSO), superficial white onychomycosis (SWO), proximal subungual onychomycosis (PSO), candidal onychomycosis and total dystrophic onychomycosis.
Of these, distal and lateral subungual onychomycosis is the commonest and is most commonly caused by T. rubrum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (321, 8, 'A 32-year-old man presented with an intensely pruritic follicular eruption on the fac,eind trunk which has not responded to oral flucloxacillin and topical anti-fungal tr rapy given to him in the community. A swab from a follicular pustule showed no growth and a biopsy showed a dense eosinophilic perifollicular infiltrate. The diagnosis of eosinophilic folliculitis was made. Which of the following conditions should he be investigated for?', 'Human Immunodeficiency Virus (HIV).', 'Malaria.', 'Psoriasis.', 'Seborrhoeic dermatitis.', 'Tuberculosis.', 'A', 'HIV infection can have many dermatological manifestations and a diagnosis of eosinophilic folliculitis should be considered in any HIV patient who presents with a pruritic sterile folliculitis in which the biopsy shows an eosinophilic inflammatory cell infiltrate.
There are 3 types of eosinophilic folliculitis; HIV-associated, classic type (also called Ofuji syndrome) and the infancy-associated type.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (322, 8, 'A 55-year-old diabetic presents with an asymptomatic erythematous rash on both axillae. Wood''s light examination shows coral red fluorescence. Which chemical is responsible for this fluorescence?', 'Coproporphyrin III.', 'Haemoglobin.', 'Protoporphyrin IX.', 'Uroporphyrin II.', 'Uroporphyrin III.', 'A', 'Erythrasma is caused by the Gram positive bacterium Corynebacterium minutissi mum.
The patches of erythrasma display coral red fluoresence on Wood''s lamp examination.
This is secondary to coproporphyrin III production by Corynebacterium minutissi mum.');

-- Paediatrics & Genetics
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (323, 9, 'A 6-week old baby presented with multiple papules, pustules and closed comedones on both cheeks. Examination of the rest of the skin was unremarkable and he was otherwise a healthy neonate. The most likely diagnosis is:', 'Gram-negative folliculitis.', 'Infantile acne.', 'Neonatal acne.', 'Neonatal cephalic pustulosis.', 'Staphylococcal pustulosis.', 'C', 'Neonatal acne consists of both inflammatory lesions and comedones.
It presents in the first three months of life.
This occurs due to the presence of the maternal hormones which stimulate the sebaceous glands In the neonate.
The condition resolves spontaneously without treatment in the first three months of life.
Neonatal cephalic pustulosis is a pustular condition mainly affecting the head of neonates, without comedones. This is may be due to overgrowth of various Malassezia species.
Infantile acne appears after the age of three months and is more common in boys due to higher levels of testosterone in the first 6-12 months of life.
There may be a positive family history, and the condition includes bothinflammatory and comedonal lesions, however often inflammatory lesions predominate and in severe cases, cystic acne may occur.
Children with infantile acne should be evaluated with an endocrinological screening for underlying abnormalities, and there may be a risk for severe acne later in life.
Staphylococcal pustulosis presents with diffuse pustules in the absence of comedones, on the trunk and limbs.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (324, 9, 'What is the inheritance pattern for incontinentia pigmenti?', 'Autosomal dominant.', 'Autosomal recessive.', 'Non-inherited disorder.', 'X-linked dominant.', 'X-linked recessive.', 'D', 'incontinentia pigmenti is a genodermatosisthat primarily affects females asmales do not survive this X-linked dominant disorder, unless they are mosaic. The commonest mutation involves a deletion in the NEMO gene on the long arm of the X chromosome.
The condition has four stages; inflammatory vesicular stage which tends to be along Blaschko''s lines, a verrucous stage, hyperpigmented, and finally hypopigmented stage in which whorls and swirls develop in a characteristic "Chinese letter" pattern.
There is associated ectodermal dysplasia and nail changes may occur including onycholysis, onychodystrophy and subungual hyperkeratosis.
Systemic defects can occur, and in particular, brain and eye involvement.
Patients with incontinentia pigmenti should have neurological and ophthalmic assessment.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (325, 9, 'A 46-year-old patient presents with multiple skin tags and skin-coloured papules on the face and neck. She has previously been admitted on three occasions for spontaneous pneumothoraces. Which of the following is the most likely diagnosis?', 'Bazex-Dupre-Christol syndrome.', 'Birt-Hogg-Dube syndrome.', 'Goltz syndrome.', 'Gorlin''s syndrome.', 'Rambo syndrome.', 'B', 'Birt-Hogg-Dube syndrome manifests as fibrofolliculomas, trichodiscomas and acrochordons.
This is an autosomal dominant disorder and can be associated with renal and pulmonary cysts; and can present with pneumothoraces.
Rombo syndrome presents with basal cell carcinomas, trichoepitheliomas, hypotrichosis, atrophoderma and telangiectasia.
Bazex-Dupre-Christol syndrome presents with basal cell carcinomas, follicular at,ophoderma, pill torti, scrotal tongue, spiny hyperkeratosis, and neuropsychiat;''ic symptoms. It is an X-linked dominant disorder.
Gorlin''s syndrome presents with basal cell carcinomas, palmo-plantar pits, odonto genic jaw cysts, frontal bossing, ovarian carcinoma / fibroma, medulloblastomas, lipomas, and epidermal cysts.
It is an autosomal dominant disorder due to PTCH1gene defect.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (326, 9, 'Which of the following genodermatoses is inherited in an X-linked dominant fashion?', 'Conradi-Hunerman syndrome.', 'Lamellar ichthyosis.', 'Netherton''s syndrome.', 'Sjogren-Larsson syndrome.', 'Xeroderma pigmentosum.', 'A', 'Conradi-Hunermann syndrome is inherited in an X-linked dominant pattern.
Patients are often born with a collodion-like membrane followed by an ichthyosiform erythroderma in Blaschko''s lines.
There may also be follicular atrophodermc, scarring alopecia, scoliosis and cataracts.
Sjogren-Larsson syndrome is an autosomal recessive disorder presents with ichthyosis at birth with spastic paralysis and mental retardation.
Netherton''s syndrome is an autosomal recessive disorder that presents with an exfoliative ery1:hroderma with ichthyosis lineariscircumflexa; the typical double edged migratory scale.
The typir.al feature is the so-called "bamboo" hairs showing microscopically the typ· ical trichorrhexis invaginata.
Lamellar ichthyosis presents with a collodion baby at birth. It is an autosomal recessive disorder.
Most patients develop later in life features of ectropion, inverted ears, plate-like scale, which is often "dirty brown", and palmo-plantar keratoderma.
Xeroderma pigmentosum is an autosomal recessive disorder.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (327, 9, 'A 5-month old boy presented with a 6-week history of multiple tense vesicles and bullae appearing on the face, abdomen and scrotum. These arepainless and some are arranged in an annular configuration resembling a "crown of jewels''''. No mucosal involvement is present and a biopsy showed a subepidermal bulla with dense neutrophilic infiltrate. Which of the following statements regarding this condition is true?', 'Commonest bullous disorder in children.', 'Histology typically shows a dense eosinophilic infiltrate.', 'Mucous membrane involvement is rare.', 'Systemic corticosteroids are the first-line treatment of choice.', 'The disease is very rare in children.', 'A', 'Linear IgA disease is the commonest bullous disorder in children.
Mucous membrane involvement may occur in half of the patients.
Dapsone remains the first-line treatment of choice.
Subepidermal Infiltrate is predominantly neutrophilic.
Drugs can cause a similar disease in adults (drug-induced linear IgA disease) with vancomycin being the commonest.
Other vesiculo-bullous disorders in childhood include: congenital HSV, congenital varicella, bullous impetigo, scabies, toxic epidermal necrolysis, staphylocoocal scalded skin syndrome, thermal burns, incontinentia pigmenti, epidermolysis bullosa, neonatal pemphigus vulgaris (from the mother), bullous pemphigoid, bullous mastocytosis and bullous congenital ichthyosiform erythroderma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (328, 9, 'Which of the following inherited forms of epidermolysis bullosa is associated with mutations of the gene coding for type VII collagen (COL7Al)?', 'Dystrophic epidermolysis bullosa.', 'Epidermolysis bullosa simplex.', 'Hemi-desmosomal epidermolysis bullosa.', 'Junctional epidermolysis bullosa.', 'Kindler syndrome.', 'A', 'Epidermolysis bullosa simplex-mutation in Keratins 5/14.
Hemi-desmosomal epidermolysis bullosa- Epidemolysis bullosa with muscular dystrophy-mutation in PLEC1, EB with pyloric atresia-mutation in ITGB4/ITGA6.
Junctional epidermolysis bullosa-mutation in LAMB3/LAMA3/LAMG2.
Dystrophic epidermolysis bullosa-mutation in COL7Al.
Kindler syndrome-mutation in KINDl.
Ectodermal dysplasla-skin fragility-mutation in PKPl.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (329, 9, 'A 2-year-old Caucasian boy is referred to the Paediatric dermatology clinic with the appearance of akinky, wavy hair on the scalp. You carry out hair pluck test and find tightly coiled hair on microscopy. Which other system involvement is to be excluded?', 'Cardiac.', 'Central nervous.', 'Gastrointestinal.', 'Haematological.', 'Renal.', 'A', 'Woolly hair is the presence of kinl-.y, wavy hair on the scalp of persons of non-African or Negroid background.
Microscopically, the hairs are tightly coiled.
The unruly hair presents at birth or in infancy, usually as a solitary problem inherit d in an autosomal dominant fashion.
Mutations in the genes for the desmosomal proteins plakoglobin (Naxos disease) or desmoplakin give rise to the triad of woolly hair, striate palmar-plantar keratoderma, and cardiomyopathy.
Both recessive and dominant patterns of inheritance have been reported.
Assessment of cardiac status should be performed In all children presenting with generalized woolly hair.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (330, 9, 'A 35-year-old patient with Darier''s disease present wich some changes affecting the fingernails. You expect to see some or all of the changes expect:', 'Distal nail plate nicking.', 'Longitudinal erythronychia.', 'Longitudinal leukonychia.', 'Longitudinal melanonychia.', 'Subungual hyperkeratotic papules.', 'D', 'Key features of nail disease in Darier''s disease include longitudinal erythronychia, longitudinal leukonychia associated with distal nail plate nicking (V-shaped), and subungual hyperkeratotic papules.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (331, 9, 'Collodion baby" is a clinical finding describing a new-born infant encased in an oily parchment-like shiny skin. This finding can occur in which of the following conditions?', 'Non-bullous congenital ichthyosiform erythroderma.', 'Hay-Wells syndrome.', 'Netherton''s syndrome.', 'Rothmund-Thompson syndrome.', 'Xeroderma pigmentosum.', 'A', 'Collodion membranes may resolve spontaneously or evolve into non-bullous ichthysioform erythroderma or lamellar ichthyosis.
Complications m;;;y include infections, dehydration and hypernataemia.
Newborns with Netherton''s syndrome typically present with an exfoliative erythroderma.
- Hay-Wells syndrome is an autosomal dominant condition wliich is a type of ectodermal dysplasia caused by a mutation in the TP7PQL gene.
The 2 features that differentiate Hay-Wells syndrome from other ectodermal dysplasias are the occurence of "clefting" of the lip or palate and the fusion of the edges (often become fibrotic) of the upper and lower eyelids.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (332, 9, 'A 3-month old preterm boy is admitted with a few w ek history of scaling and vesicular eruption in the peri-oral and acral distribution. The child is Irritable and has been having diarrhoea for 4 weeks. What is the most likely cause of these symptoms7', 'Acrodermatitis enteropathica.', 'Epidermolysis bullosa simplex.', 'Hand foot and mouth syndrome.', 'Linear IgA disease.', 'Primary herpes simplex infection.', 'A', 'Acrodermatitis enteropathlca may be autosomal recessive or acquired.
It is caused by deficiency of zinc.
Scaling and vesicles in a perl-orificial and acral distribution are common.
Diarrhoea is often present.
At risk population includes premature infants, aicoholics and patients with absorption defects.
Zinc replacement brings about rapid improvement.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (333, 9, 'A 14-week-old girl is referred with a 12-week history of a rapidly enlarging bruise-like swelling of the left upper eyelid completely obscuring the left eye. Examination shows a large haemangioma filling the left upper eyelid and orbit, completely closing the eye. Which of the following is the most appropriate management?', 'Aspiration of haemangioma.', 'Bevacizumab.', 'Propranolol.', 'Pulsed dye laser.', 'Topical corticosteroids.', 'C', 'Oral propranolol has replaced oral corticosteroids as the mainstay of treatment for high risk haemangiomas including those that risk loss of vision.
It should also be considered for subglottic or nasal haemangiomas or rapidly enlarging haemangiomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (334, 9, 'A-12 week old boy has an enlarging tender ulcerated haemangioma on the perine''31 area. Which of the following statements is incorrect?', 'Becaplermln 0.01% gel is the mainstay treatment.', 'Intralesional steroids are the treatment of choice.', 'Potent topical corticosteroids are usually ineffective.', 'Pulsed dye laser is ineffective for pain control.', 'Spontaneous resolution is unlikely in perineal haemangioma.', 'D', 'Pulsed-dye laser is effective for treating ulcerated hemangiomas and can result in pain reduction, rapid re-epithelialization, and hastened involution.
There is a small risk of worsening of ulceration with pulsed dye laser.
Pulsed dye laser is not used routinely in the treatment of uncomplicated haemangiomas.
Long pulsed and frequency-doubled Nd:YAG lasers may also be used to treat ulcer ated haemangiomas.
Topical imiquimod cream, becaplermin 0.01% gel and oral propranol have all been used successfully in the treatment of infantile haemangiomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (335, 9, 'A 3-year-old boy presents with dry scaly skin since birth. Examination shows dark, polygonal, firmly adherent scales on the posterior neck, upper trunk, and extensor surfaces of the extremities. He has a history of cryptorchidism. What is the most likely diagnosis?', 'Ichthyosis vulgaris.', 'Lamellar ichthyosis.', 'Refsum''s disease.', 'Richner Hanhart syndrome.', 'X-linked ichthyosis.', 'E', 'X-linked ichthyosis is caused by deficiency of the enzyme steroid sulfatase (STS).
The scaling is mildin the first few days of life and gives way to dark brown, polygonal, firmly adherent scales.
Palms and soles are usually spared.
During late childhood the rash becomes more prominent on the trunk and extremities, particularly on the extensor surfaces of the legs.
Corneal opacities may be seen in patients and carriers.
Cryptorchidism occurs in 20% of patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (336, 9, 'A 14-week-old girl was referred with a 12-week history of a rapidly enlarging bruise-like swelling of the left upper eyelid completelv obscuring the left eye. She had repeated episodes of fresh rectal bleeding. Examination shows a large haemangioma filling the left upper eyelid and orbit. Computerised tomographic scan of abdomen shows a large haemangioma in the right lobe of the liver and extensive small intestinal haemangiomas. Which of the following most likely describes the condition?', 'Cobb syndrome.', 'Dandy Walker syndrome.', 'LAMB syndrome.', 'LEOPARD syndrome.', 'PHACES syndrome.', 'E', 'PHACES syndrome is a neurocutaneous syndrome representing a spectrum of anomalies in which segmental haemangiomas, most commonly of the face, are associated with one or more of: posterior fossa brain malformations, arterial anomalies, coarctation of the aorta and cardiac defects, and eye abnormalities (PHACES if ventral developmental defects such as sternalclefting and/or supraumbilicalraphe are included).
The most common manifestations noted are structural and arterial anomalies of the brain, followed by cardiac anomalies and/or coarctation of the aorta, eye abnormalities, and ventral developmental defects. The most commonly reported sites for visceral haemangiomas among such patients are the brain and mediastinum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (337, 9, 'A 35-year-old woman presents with erosions under her breasts and axillae. Her mother had similar S''ymptoms which were treated as flexural psoriasis. Which of the following statements regarding this condition is incorrect?', 'Direct immunofluoresence shows IgG and C3 deposition at dermo-epidermal junction.', 'Kaposi''s varicelliform eruption is a recognised complication.', 'The defect is identified on ATP2C1gene.', 'The disease can occur sporadically.', 'White bands on the fingernails may be seen.', 'A', 'Hailey-Hailey disease (familial chronic benign pemphigus) is an autosomal dominant disorder with incomplete penetrance.
Approximately one thirds of patients do not have a family history of the disorder.
The defect appears to be in a calcium pump protein, ATP2Cl which encodes the secretory pathway Ca2+/Mn2 ATPase (hSPCAl).
Patients present with crusts and vesicles studded on erythematous plaques in flexural areas including the genital infra-mammary region, neck, and axillae.
Longitudinal leukonychia may be seen on fingernails.
Treatment is aimed at suppressing symptoms and includes anti-perspirants, antibacterials, topical steroids and immunosuppressives in recalcitrant cases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (338, 9, 'A 12-year-old Pakistani girl was referred with a long-standing history of general stiffening of the tongue with the presence of beaded papules on the eyelids and on the peri-orbital skin and hoarseness of her voice. There are also verrucous-like plaques on the elbows and knuckles, in addition to dental anomalies. Further history reveals that her older sister, aged 16, suffers from the same condition. The inheritance pattern of this condition is?', 'An acquired condition therefore not inherited.', 'Autosomal dominant.', 'Autosomal recessive.', 'X-linked dominant.', 'X-linked recessive.', 'C', 'The diagnosis here is lipoid proteinosis which is a rare autosomal recessive disorder characterised by the above signs and symptoms.
It is caused by a mutation of the gene ECN-1.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (339, 9, 'A 2-month-old boy presented with targetoid large erythematous macules with purpura and oedema on his limbs and face. History reveals that the baby suffered an upper respiratory tract infection ten days prior to the appearaniie of this rash. Which of the following statements regarding this condition is true?', 'ANCA level must be checked immediately.', 'Histology will show leukocytoclastic vasculitis and the condition will resolve spontaneously.', 'Histology will show multiple thrombi in the superficial vessels.', 'The condition has a very poor prognosis and rapid initiation of corticosteroid therapy is required.', 'Treatment with hyperoaric oxygen is required.', 'B', 'Acute haemorrhagic oedema of infancy can occur following upper respiratory tract infection and clinically presents with targetoid-like purpuric macules associated with oedema.
The condition is transient, has an excellent prognosis and no treatment is required other than supportive measures.
Histologically, the lesions show small vessel leukocytoclastic vasculitis and occasion ally IgA deposition in the vessels.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (340, 9, 'A 12-year-old girl presents with a persistent eczematous eruption covering her face, trunk and limbs which is associated with coarse facial features, doughy skin and broad nasal bridge. She also has a history of recurrent fractures and poor dentition. She has been found to have persistently raised eosinophil count, significantly raised IgE levels but no demonstrable specific igEs against any particular allergen. On examination, you also note that she has a high-arched palate. Mutation of which gene is responsible for thiscondition?', 'ABCA12.', '8-RAS.', 'c-kit.', 'SPINKS.', 'STAT3.', 'E', 'The clinical features and lab abnormalities here are consistent with the diagnosis of hyper-lgEsyndrome.
The autosomal dominant variant is related to STAT3 defects; however the autosomal recessive variant is related to lYK2 defects.
Other features of this disease are recurrent pyogenic infections, asthma, hyper-ex tensible joints, scoliosis and neurological complications.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (341, 9, 'Which of the following structural hair abnormalities can be seen in Netherton''s syndrome?', 'Loose anagen.', 'Pili annulati.', 'Trichorrhexis invaginata.', 'Woolly hair.', 'Monilethrix.', 'C', 'Trichorrhexis invaginata is also called "bamboo hair" and is found in Netherton''s syndrome.
Increased fragility of the hair shaft is also seen in monilethnx, trichorrhexis nodosa, trichothiodystrophy and pill torti.
In loose anagen syndrome and woolly hair, the hair shafts are not fragile.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (342, 9, 'which of the following sub-types of morphea is the commonest in children?', 'En coup de Sabre.', 'Generalized type.', 'Linear type.', 'Pan-sclerotic.', 'Plaque type.', 'C', 'Linear nicrphea can be associated with joint symptoms and is the commonest subtype in children.
The plaque type of morphea is thecommonest in adults.
En coup de Sabre sub-type of morphea on the head can be associated with ocular and neurological abnormalities.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (343, 9, 'A 17-year-old man presented with diffuse asymptomatic angiokeracomas on the trunk and genitalia with bilateral leg oedema. In addition he has been complaining of neuropathic pains in his limbs and hypohidrosis. Urinalysis showed evidence of proteinuria. Which of the following statements regarding this condition is incorrect?', 'Cardiac arrhythmias are a potential complication in this condition.', 'The angiokeratomas tend not to respond to enzyme replacement therapy.', 'The deficient enzyme is alpi,a-galactosidase-A.', 'The disease is generaliy milder in women.', 'The pattern of inheritance is autosomal dominant.', 'E', 'Fabry''s disease is an X-linked recessive disorder.
Female carriers can still manifest the disease but it tends to be milder.
The angiokeratomas and lymphoedema generally do not respond to enzyme replacement therapy.
Hypohidrosis and neuropathic pain crises are other manifestations of the disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (344, 9, 'A 40-year-old man with a history of thyroid carcinoma and multiple facial tricholemmomas presented with cobblestoning of the oral mucosa and palmo-plantar keratoses. The most likely diagnosis here is:', 'Bazex syndrome.', 'Birt-Hogg-Dube syndrome.', 'Cowden''s syndrome.', 'Gardner''s syndrome.', 'Muir-Torre syndrome.', 'C', 'The rare Cowden''s syndrome should be suspected when a patient presents with oral cobblestoning, palmo-plantar keratoses, tricholemmomas and ahistory of internal malignany (mostly breast, thyroid or uterus).
Muir-Torre syndrome can also be associated with internal malignancies but the cuta neous manifestations are of sebaceous tumours or eruptive keratoacanthomas.
Gardner''s syndrome is associated with polyposis coli (risk of colon carcinoma) and multiple epidermoid cysts and/or lipomas.
Bazex syndrome is also called acrokeratosisparaneoplastica and is a paraneoplastic phenomenon that often presents with a psoriasiform appearance of the hands and feet accentuated around the nails with associated nail changes, palmo-plantar keratoderma and alopecia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (345, 9, 'Dental anomalies can be found in all of the following except:', 'Dyskeratosis congenita.', 'Gardner''s syndrome.', 'Incontinentia pigmenti.', 'Junctional epidermolysis bullosa.', 'Netherton''s syndrome.', 'E', 'In Netherton''s syndrome there is ichthyosis with hair shaft defects but dental abnormalities are not a feature.
Other conditions that can be associated with dental anomalies include ectodermal dysplasia, congenital erythropoietic porphyria, focal dermal hypoplasia, Sjogren- Larsson syndrome and Papillon-Lefevre syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (346, 9, 'An infant has a focal area of midline alopecia, overlying a blue-tinged compressible nodule, surrounded by long dark coarse hair. Which of the following investigations would you instigate?', 'Serum testosterone.', 'MRI head.', 'Diagnostic biopsy.', 'Serum folate.', 'Diagnostic aspiration.', 'B', 'Features described are those of the hair collar sign; a relatively specific marker of meningoceles and other types of cranial dysraphism.
CT or MRI imaging is necessary to determine whether an intracranial connection is present.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (347, 9, 'A 31-year-old amateur rugby player experiences considerable distress during a dental procedure despite receiving multiple local anaesthetic injections. What is the most likely underlying diagnosis?', 'Marfan''s syndrome.', 'Pseudoxanthoma elasticum.', 'Ehlers-Danlos Syndrome.', 'Ectodermal dysplasia.', 'Osteogenesis imperfecta.', 'C', 'There exists an increasingly well-recognised association between Ehlers-Danlos syndrome, specifically of the hypermobility type, and resistance to local anaesthetics.
This can necessitate a higher local anaesthetic dose, a greater time between delivering analgesia and starting surgery, or even consideration for general anaesthesia.
The underlying mechanism awaits full elucidation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (348, 9, 'A 7-year-old girl is noted to have exaggerated wrinkling of the palms after brief immersion in water. Which of the following investigations would you instigate?', 'Random glucose.', 'Sweat test.', 'Thyroid function tests.', 'Diagnostic skin biopsy.', 'Nerve conduction studies.', 'B', 'Aquagenic wrinkling of the palms is a cutaneous manifestation of cystic fibrosis that may also be seen in carriers of cystic fibrosis gene mutations.
It usually presents with translucent papules that coalesce to form oedematous plaques.
Time-to-onset·is typically a few minutes, but is usually longer in carriers of cystic fibrosis mutations.
The exact cause isunclear and most authorities agree that it is related to dysfunction in sweating.
Reported treatments include topical aluminium preparations and botulinum toxin injections.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (349, 9, 'A 15-year-old boy, whose family have recently moved to the UK, presents with crops of reddish-brown pigmented plaques and papillomatous lesions over his face, trunk and limbs. These first appeared aged 12 and have steadily grown more extensive. A diagnosis of epidermodysplasia verruciformis is suspected. This disorder results from mutation in which gene?', 'SPINK.', 'FLG.', 'PTEN.', 'NEMO.', 'EVER.', 'E', 'Epidermodysplasia verruciformis (or Lewandowsky-Lutz dysplasia) is a rare disorder, typically inherited in an autosomal recessive fashion.
Mutations in EVER 1 or 2 genes result in defective cell-mediated immunity.
Patients are predisposed to HPV infection and squamous cell carcinoma.
Numerous HPV serotypes are associated, although not HPV 16.
HPV 5, 8, 10, and 47 serotypes have been isolated in over 90% of epidermodysplasia verruciformis-associated squamous cell carcinomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (350, 9, 'Bart-Pumphrey syndrome results from mutation in the gene encoding connexin 26. The function of which structures will be affected?', 'Intermediate filaments.', 'Anchoring filaments.', 'Hemidesmosomes.', 'Gap junctions.', 'Tonofilaments.', 'D', 'Bart-Pumphrey syndrome is characterised by the clinical triad of prominent knuckle pads, leuconychia and deafness.
Inheritance is autosomal recessive and arises from mutation in the GJB2/connexin 26 gene.
Other disorders resulting from mutation inconnexin 26 include Palmoplantar Keratoderma with Deafness and Vohwinkel syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (351, 9, 'A 10-year-old girl is seen in clinic with multiple lentigines and blue naevi. During examination, you also elicit a cardiac murmur leading you to suspect an underlying diagnosis of LAMB. To what does the ''A'' in this acronym refer?', 'AV malformations.', 'Atrial myxomas.', 'Aortic stenosis.', 'Aortic regurgitation.', 'Any of the above.', 'B', 'LAMB (Lentigines, Atrial Myxomas, Mucocutaneous Myxomas, Blue Naevi) is a type of Myxoma syndrome.
Other recognised disorders on this disease spectrum are NAME (naevi, atrial myxomas, rnyxoidneurofibroma, and ephelides) and carney syndrome (atrial, cutaneous and mammary myxomas, lentigines, blue naevi, endocrine disorders and testicular tumours).
Myxoma syndrome may be autosomal dominant or sporadic.
One implicated gene in familial cases is PRKARlA, a cell cycle regulator.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (352, 9, 'You have been reviewing an 18-month year old boy with multiple papules over his cheeks and forehead. Initially lesions appeared smooth and pink but lately have developed a yellowish appearance. Diagnostic skin biopsy is consistent with juvenile xanthogranuloma. What action might you consider?', 'None of the above - this is a skin-limited disorder.', 'Full lipid profile.', 'Liver function tests.', 'Cardiology review.', 'Ophthalmology review.', 'E', 'Juvenile xanthogranuloma is a type of non-langerhan''s cell histiocytosis.
it is most commonly seen in male children but can oc.cur in both sexes at any age.
Its cause is unknown and diagnosis is confirmed by skin biopsy with collections of, often foamy, lipid-full histiocytes seen in the dermis.
There is no associated dyslipidaemia.
Ophthalmic involvement, however, can be associated with spontaneous hyphema leading to secondary glaucoma and blindness. Those at greatest risk are children younger than 2 years with multiple skin lesions');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (353, 9, 'You see a 2-month old child with scarring blistering of the skin. Other ieatures include a mitten deformity with proximal fusion or all hand and toes webs and aphonia. Which of the following combinations concerning 1) inheritance 2) protein(s) affected 3) cellular structure affected and 4) level of the blister, for thiscondition is true?', 'Autosomal recessive, collagen 7 (COL7A1), anchoring fibril, sublamlnal densa.', 'Autosomal recessive, laminin 332, anchoring filament, lamina-lucida split.', 'Autosomal dominant, collagen 7 (COL7Al), anchodng fibril, sublaminal densa.', 'Autosomal dominant, keratin 5 &14, intermediate filament, intra-epithelial split.', 'None of the above.', 'A', 'The clinical features described are those of the autosomal recessive, or Hallopeau-Siemans, type of dystrophic epidermolyis bullosa (EB).
Other features include enamel defects and dental caries, nail dystrophy and high propensity to squamous cell carcinoma.
Answer C relates to the autosomal dominant form of dystrophic EB, which is less severe and improves with age.
Answer B relates to junctional EB, classically subdivided into Herlitz and non-Herlitz types.
Answer D relates to EB simplex, which in turn can be subdivided into localised (Weber Cockayne), generalised (Dowling Meara) and superficial types.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (354, 9, 'An 8-year-old girl is referred to the department of paediatric dermatology with a port-wine stain overlying her right mid-back. She is under the neurology team for a radiculopathy. You suspect a unifying diagnosis of Cobb Syndrome. Which of the following best describes the inheritance pattern of this condition?', 'X-linked recessive.', 'Autosomal dominant.', 'Autosomal recessive.', 'X-linked dominant.', 'Sporadic.', 'E', 'Cobb syndrome (also known as Cutaneous Vertebral Medullary Angiomatosis or Spinal Arteriovenous Metameric Syndrome) is defined by coexistence of vascular malformations in all tissue layers of a segmental dermatome.
Venous or arteriovenous malformations over the back are present from birth may be the only clue to an underlying spinal cord AVM.
Neurological manifestations typically involve lower limb motor or sensory deficit and/or sphincter deficits.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (355, 9, 'A 29-year-old pregnant woman is seen in clinic with her fourth skin malignancy. There is strong family history of cancer with her father and paternal grandmother having suffered medulloblastoma and ovarian cancer, respectively. She and her partner, who has no personal or family of skin cancer, wish to know the likelihood that their child, which they know to be a daughter, will also be affected by the condition. Which of the following is the correct answer?', '75%.', '25%.', '0%.', '50%.', '100%.', 'D', 'Gorlin''s syndrome is inherited in an autosomal domirant fashion.
Non-basal cell carcinoma skin signs can include epidermal cysts, lipomas and palmoplantar cysts.
Bony manifestations include bifid ribs, frontal bossing and ontontogenic jaw cysts.
Other associated malignancies include medulloblastoma and ovarian cancer.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (356, 9, 'Whir.h of the following statements regards Naxos syndrome is most accurate?', 'It is autosomal recessive, involves a defect in the desmoplakin gene, and presents with woolly hair, arrhythmogenic left ventricular cardiomyopathy and striate PPK.', 'It is autosomal recessive, involves a defect in the plakoglobin gene, and presents with woolly hair, arrhythmogenic left ventricular cardiomyopathy and diffuse PPK.', 'It is autosomal recessive, involves a defect in the plakoglobin gene, and pre sents with woolly hair, arrhythmogenic right ventricular cardiomyopathy and striate PPK.', 'It is autosomal dominant, involves a defect in the plakoglobin gene, and presents with woolly hair, arrhythmogenic left ventricular cardiomyopathy and striate PPK.', 'It is autosomal recessive, involves a defect in the plakoglobin gene, and presents with woolly hair, arrhythmogenic right ventricular cardiomyopathy and diffuse PPK.', 'E', 'Woolly hair may be an inherited as an isolated condition (usually in an autosomal dominant fashion) or as part of a syndrome (typically in an autosomal recessive fashion).
Answer A is true for Carvajal syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (357, 9, 'A 12-month-old healthy boy was born with a large purplish erythematous raised tumour with central telangiectasia surrounded by a pale halo on his left upper arm which did not increase in size in the first eight months of his life. At the age of one year, his mother noticed significant flattening of the lesion and fading of the halo. In this condition, which of the following statements is incorrect?', 'Central ulceration is a possible complication in the first few months of life.', 'Kasabach-Merritt syndrome occurs in some cases.', 'The histology is characterised by small capillary lobules surrounded by dense fibrous tissue with abnormally thin walled blood vessels in the centre.', 'This entity is characteristically negative to the immunoreactive glucose transporter-1 (GLUT-1).', 'Treatment with oral steroids should be commenced during the first three months of life.', 'E', 'The diagnosis here is rapidly involuting congenital haemangioma (RICH).
Central ulceration, calicification and Kasabach-Merritt syndrome may all occur in this entity.
Both RICH and non-involuting congenital haemangioma (NICH) are negative for GLUT- 1; as opposed to infantile haemangiomas that are positive to GLUT-1.
Both RICH and NICH are fully developed at birth unlike infantile haemangiomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (358, 9, 'A 45-year-old patient with Darier''s disease is referred for evaluation of nail changes. Which of the following is not a recognized feature of nail disease in Darier''s disease?', 'Coarse pitting.', 'Distal V-shaped nick.', 'Fragile nails.', 'Red and white longitudinal stripes.', 'Subungual hyperkeratosis.', 'A', 'The nails in Darier''s disease are fragile and split easily.
Other features include - combination of red and white longitudinal stripes (erytnroand leukonychia).
Distal V-shaped nick and subungual hyperkeratosis dre commonly seen.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (359, 9, 'In which of the following syndromes are multiple fibrofolliculomas a pathognomonic feature?', 'Birt-Hogg-Dube syndrome.', 'Cowden syndrome.', 'Darier''s disease.', 'Gardner syndrome.', 'Von Hippel Lindau syndrome.', 'A', 'Fibrofolliculomas are tiny skin-colou;ed papules on the head, neck, and upper trunk.
Birt-Hogg-Dube syndrome is an autosomal dominant condition caused by a mutation in the protein folliculin.
Salient features include fibrofolliculomas, trichodiscomas, and acrochordons.
Birt-Hogg-Dube syndrome is associated with an increased risk of renal carcinomas and pneumothoraces.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (360, 9, 'Which of the following is the investigation of choice in fibromatosiscolli?', 'Excisional biopsy.', 'Fine needle aspiration cytology.', 'Incisional biopsy.', 'Magnetic resonance imaging.', 'Ultrasound.', 'B', 'Fibromiltosiscolli (sterr.omastoid tumour of infancy) is a self-limiting benign proliferation of fibroblasts in the lower one-third of the sternocleidomastoid muscle.
Presentation is in the first few weeks of life and the lesion can grow rapidly causing marked expansion of the sternocleidomastoid.
Clinical and radiographic differential diagnoses include rhabdomyosarcoma or neuroblastoma.
It is the most common cause of neonatal torticollis.
It usually resolves within the first year of life.
Excisional biopsy is not required except where malignancy is suspected.
Fine-needle aspiration is the preferred diagnostic technique and shows clusters of benign, spindled, plump fibroblasts with ovoid to elongated nuclei.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (361, 9, 'Which of the following is not a feature of Conradi-Hi.inermann syndrome?', 'Cataracts.', 'Frequent fractures.', 'Hyperpigmentation.', 'Ichthyosiform scaling erythroderma.', 'Stippled calcifications of the epiphyses.', 'B', 'Conradi-Hunermann syndrome is an X-linked dominant disorder.
Features include ichthyosiform scaling erythroderma patterned along the lines of Blaschko followed by bands of follicular atrophoderma, hyperpigmentation, cataracts, scarring alopecia, saddle-nose deformity, asymmetric limb reduction defects, and stippled calcifications of the epiphyses.
It is lethal in homozygous males.
Mutations occur in the emopamil binding protein gene at Xpll.23-pll.22.42.
ichthyosis, keratotic follicular plugging containing dystrophic calcification in newborns are also seen.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (362, 9, 'A neonate is born with distinctive features of harlequin ichthyosis. The gene defect is?', 'ABCA12.', 'ATP2C1.', 'FLG.', 'NEMO.', 'TGM1.', 'A', 'ATP2Cl is the gene defect in Hailey-Hailey disease.
The gene defect in lamellar ichthyosis is TGMl (transglut.;minase 1).
NEMO is the gene defect in incontinentia pigmenti and stands for NFKB Essential Modulator.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (363, 9, 'Cataracts are a feature of which of the following dermatological conditions?', 'Beh et''s disease.', 'Juvenile xanthogranuloma.', 'Mucous membrane pemphigoid.', 'Reiter''s disease.', 'Rothmund-Thompson syndrome.', 'E', 'Other conditions which can be associated with cataracts are Gorlin''s syndrome, incontinentia pigmenti, Neurofibromatosis type-2, trichothiodystrophy, vitamin 812 deficiency, Werner''s syndrome, Refsurn disease, Conradi-Hunermann syndrome, oral steroid use and PUVA therapy.
Beh et''s disease can be associated with uveitis, retinal vasculitis and hypopyon.
Mucous membrane pemphigoid can cause symblepharon. ""Juvenile xanthogranulomas can be associated with glaucoma. "'' Reiter''s disease is associated with conjunctivitis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (364, 9, 'Which of the following genes is defective in Darier''s disease?', 'ATP2A2', 'Calcium pump of the Golgi apparatus.', 'Keratin 1/16.', 'Keratin 2a.', 'PTCH.', 'A', 'Darier''s disease and Hailey-Hailey disease are acantholytic disorders.
Calcium pump of the sarco/ endoplasmic reticulum is defective in Darier''s disease.
Defect in calcium pump of the Golgi apparatus results in Hailey-Hailey disease.
toss of function mutations in ATP2A2, which encodes sarco/endoplasmic reticulum Ca2+ adenosine triphosphatase (ATPase) isoform 2 (SERCA2), a calcium pump transporting Ca2+ from the cytosol to the lumen of the endoplasmic reticulum results in Darier''s disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (365, 9, 'Defective calcium pump is not implicated in the pathogenesis of which of the following?', 'Acrokeratosis verruciformis of Hopf.', 'Darier White disease.', 'Epidermal dyskeratotic acantholytic naevi.', 'Grover''s disease.', 'Hailey-Hailey disease.', 'D', 'Darier White disease, epidermal dyskeratotic acantholytic naevi (localized form of Darier disease caused by somatic mosaicism), and aAcrokeratosis verruciformis of Hopf are caused by defects in the same gene encoding calcium pump of the endoplasmic reticulum.
Hailey-Hailey disease results from defective calcium pump of the Golgi apparatus.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (366, 9, 'Which ofthe following is not a feature of Piebaldism?', 'Deafness.', 'Depigmented patches on ventral trunk.', 'Mutations in the KIT proto-oncogene.', 'Poliosis.', 'Sparing of hands and feet.', 'A', 'Piebaldism is caused by mutations in the KIT proto-oncogene.
Depigmented patches are present on the ventral or lateral trunk.
Hands and feet are spared.
Poliosis iscommon.
Deafness is not a feature.
Piebaldism with deafness is known as Woolf syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (367, 9, 'Which of the following subtypes of Waardenburg syndrome has Hirschsprung disease as an additional feature?', 'Tietz syndrome.', 'Waardenburg syndrome type 1.', 'Waardenburg syndrome type 2.', 'Waardenburg syndrome type 3.', 'Waardenburg syndrome type 4.', 'E', 'Waardenburg syndrome type 4, is caused by heterozygous mutations in the transcription factor gene SOXl0 or by homozygous mutations in the gene encoding the peptide ligand endothelln-3, EDN3, or its receptor, EDNRB.
These genes are important in melanocyte development and in the development of the distal aspect of enteric nervous system cells.
Waardenburg syndrome type 4 has features of Waardenburg syndrome type 1 (pig mentary abnormalities, dystopia canthorum, broadening of the nasal root, the presence of hypoplastic alae nasi, synophrys, poliosis, heterochromia irides, partial heterochromia irides, or hypoplastic blue irides, premature greying and congenital deafness).
In addition it is associated with Hirschsprung disease (congenital aganglionosis of the colon).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (368, 9, 'Pulmonary fibrosis is a clinical feature of which of the following?', 'Chediak-Higashi syndrome.', 'Griscelli syndrome.', 'Hermansky- Pudlak syndrome.', 'Tietz syndrome.', 'Waardenburg syndrome.', 'C', 'Hermansky-Pudlak syndrome (HPS) patients have oculocutaneous albinism with variable hypopigmentation of the skin, hair, and irides, and ocular abnormalities.
Additional features include lack of platelet dense bodies, prolonged bleeding time, mucous membrane bleeding, and a predisposition to epistaxis, easy bruising, and metromenorrhagia.
Pulmonary fibrosis is a common and severe manifestation of HPSl and HPS4.
Pulmonary fibrosis causes death between the fourth and sixth decades of life.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (369, 9, 'A 13-year-old girl presents with multiple skin coloured nodules on the skin. In addition she has numerous coffee-coloured patches and macules on her skin. Her mother has similar patches on her skin. You diagnose the condition as neurofibromatosis type 1. Which of the following is the earliest skin sign of this condition?', 'Axillary freckling.', 'Cafe-au-lait macules.', 'Inguinal freckling.', 'Lisch nodules.', 'Neurofibromas.', 'B', 'The diagnostic criteria for neurofibromatosis-1are:
6 or more cafe-au-lait macules of >5 mm In greatest diameter in pre-puber tal children and >15 mr, i:1post-pubertal individuals.
2 or morP. neurofibromas of any type or 1 plexiform neurofibroma.
Freckling in axillary or inguinal regions.
2 or more Lisch nodules.
Optic gHomas.
Osseous lesions including sphenoid dysplasia or thinning of long bone cortex with or without pseudoarthrosis.
First degree relative with NF-1.
At least two of the above criteria should be present to make a diagnosis of NF-1.
Cafe-au-lait macules are sharply defined, light brown patches which may be present at birth or appear shortly after - noted in all children with NF-1by the age of 4 years.
Neurofibromas start to develop around puberty.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (370, 9, 'A 3-year-old boy presents to the dermatolofy department as his parents have concerns about several lesions on his face and trunk which he has had for over a year. Clinically, these consisted of yellow to orange coloured small nodules. There was no history of erosions, blisters, or change in size following rubbing. The child is otherwise well in himself; there is no family history of such lesions. Which would be the most appropriate next investigation?', 'CT scan of the head.', 'Measurement of CRP.', 'MRI scan of the chest.', 'Ophthalmic referral.', 'Serum tryptase level.', 'D', 'Juvenile xanthogranuloma is a histiocytic disorder.
It presents In children as solitary yellow to orange coloured lesions.
Ophthalmic involvement is the most common extra-cutaneous site and should be considered in children with more than three lesions.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (371, 9, 'A 3-year-old girl was referred by the endocrinologists with a rash on the scalp and vulva. Examination shows extensive seborrhea on the scalp with some vesicular crusted lesions and erosions on the vulva. Erosions, purpura and ulceration were also seen on the lower back. She has been diagnosed with diabetes insipidus. What is the most likely diagnosis?', 'Extensive candidiasis.', 'Histoplasmosis.', 'Letterer-Siwe syndrome.', 'Mastocytosis.', 'Multicentricreticulohistiocytosis.', 'C', 'Letterer-Siwe syndrome is the most severe form of Langerhan''s cell histiocytosis.
Usually seen in children, it is associated with exuda''Cive, ulcerative seborrhoeic dermatitis-like eruption and systemic signs including hepatosplenomegaly.
Suspicion of the diagnosis should arise in any child with seborrhoeic dermatitis-like picture and the presence of petechieae.
- intertriginous lesions are common.
Loss of teeth may occur if mandiblular and maxillary bones are involved. "''Lymphadenopathy, bonemarrow involvement and thrombocytopaenia are also seen. "'' Diabetes insipidus occurs secondary to involvement of the pituitary gland or hypothalamus.
Triad of proptosis, diabetes insipidus and skin rash are seen in Hand-Scholler- Christian disease.
The disease 1s commonly fulminnnt and fatal.
Vinblastine is the chemotherapeutic agent of choice.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (372, 9, 'A 6-month old girl is referred to the department of paediatric dermatology with a port-wine stain on the left side of her face. She is under the care of the neurologists for epilepsy. Which of the following best describes the Inheritance pattern of this condition?', 'Autosomal dominant.', 'Autosomal recessive.', 'Sporadic.', 'X-linked dominant.', 'X-linked recessive.', 'C', 'Sturge-Weber syndrome is a sporadic malformation of the vasculature of the leptomeninges, facial dermal capillaries and often ocular vessels.
It is characterized by facial port wine stain most commonly affecting areas innervated by the ophthalmic and maxillary divisions of the trigeminal nerve.
Homolateralleptomeningeal angiomatosis results in epilepsy in 75-90% of cases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (373, 9, 'A 10-month old baby presented with an 8-month history of a progressively worsening eruption consisting of red-to-light brown patches and plaques on the truni, and limbs. His mother reported that some of them have blistered, particularly following gentle rubbing. Whilst in clinic you can elicit the Darier''s sign on some of the plaques, which of the following should be avoided in this patient?', 'Cetirizine.', 'Erythromycin.', 'Ibuprofen.', 'Loratidine.', 'Paracetamol.', 'C', 'The diagnosis is urticaria pigmentosa which is a form of cutaneous mastocytosis.
Drugs which can trigger histamine release from mast cells should be avoided and these include NSAIDs, aspirin, opiates, atropine, procaine and polymyxin B.
Other forms of cutaneous mastocytosis Include solitary mastocytoma, diffuse cuta neous mastocytosis (rare) and telangiectasia macuiariseruptiva perstans.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (374, 9, 'A 5-year-old girl attends clinic with her parents. She has short and uneven blonde hair with areas of "hair thinning". Her mother is concerned as she has not had a haircut for over 2 years and her hair seem to fall off easily. There is no family history of any hair abnormalities. Hair pull test was positive with multiple hairs pulled off easily. Microscopic examination of the hair showed absence of inner or outer root sheath and distorted hair bulbs. The diagnosis is:', 'Anagen effluvium.', 'Loose anagen syndrome.', 'Monilethrix.', 'Pili torti.', 'Telogen effluvium.', 'B', 'The differential diagnosis includes short anagen syndrome but the hair pull test would be negative.
Pili torti isa malformation of the hair shaft which is twisted about its axis. The hair is brittle and short and may be inherited in an autosomal dominant pattern.
- Monilethrix is an autosomal dominant hair disorder in which the hair shaft is beaded and fragile.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (375, 9, 'You were asked to see a 3-week old baby born through forceps delivery. The paediatrician is concerned about a firm area on his upper back. Examination showed a mobile, firm, subcutaneous plaque. A biopsy taken by a paediatric dermatologist showed areas of necrosis in the adipocytes. The most important biochemical marker that needs regular monitoring is:', 'Calcium.', 'C-Reactive Protein.', 'Erythrocyte Sedimentation Rate.', 'Haemoglobin.', 'Magnesium.', 'A', '-The diagnosis is subcutaneous fat necrosis of the newborn, often occurring following traumatic delivery.
Hypercalcaemia can occur and serum calcium levels need to be monitored.
Signs of hypercalcaemia in a baby include poor feeding, irritability and vomiting.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (376, 9, 'A 15-year-old boy from Tunisia presented with a palmo-plantar keratoderma and recurrent episodes of impetigo. He had uffered severe periodontitis at the age of 3 and as a consequence has lost most of his teeth. His nails were unaffected. His sister and mother had similar presentations. Both his parents are first cousins. The most likely diagnosis is:', 'Bazex syndrome.', 'Huriez syndrome.', 'Pachonychia congenita type 1.', 'Pachonychia congenita type 2.', 'Papillon-Lefevre syndrome.', 'E', 'Papillon-Lefevre syndrome is an autosomal recessive disorder that presents with palmo-plantar keraoderma, periodontitis and recurrent skin infections. In some cases hearing loss may occur.
In pachonychia congenital (PC) the nails are always abnormal (thickened and curved)
in addition to the presence of palmo-plantar keratoderma.
Two types of this autosomal dominant condition exist: PC-1 and PC-2.
In PC-1 (also called "Jadassohn-Lewandowsky type"), leukoplakia and follicular keratosis occur in addition to the PPK and nail abnormality.
In PC-2 (also called "Jackson-Lawler type"), the affected patients have natal teeth and cutaneous cysts (no leukoplakia and/or follicular keratosis).
Huriez syndrome is a rare autosomal dominant disorder in which palmo-plantar keratoderma is associated with sclerodactly and a high incidence of squamous cell carcinomas.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (377, 9, 'A 30-year-old man if diagnosed with Fabry''s disease by the metabolic medicine consultant. Which of the following type of angiokeratomas is associated with Fabry''s disease?', 'Angiokeratoma circumscriptum.', 'Angiokeratomas corporis diffusum.', 'Angiokeratomas of Fordyce.', 'Angiokeratomas of Mibelli.', 'Solitary (papular) angiokeratoma.', 'B', 'These are the 5 types of angiokeratomas.
Angiokeratomas corporis diffusum is associated with Fabry''s disease and often pre sents with multiple tiny angiokeratomas on the trunk and thighs.
Angiokeratomas of Mibelli occur on the dorsal aspects of the fingers and toes; whereas angiokeratomas of Fordyce occurs on the vulva or scrotum.
Angiokeratoma circumscriptum presents at birth or early in life (predominantly on the legs) as a large unilateral hyperkeratotic plaque with confluent keratotic papules.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (378, 9, 'A 4-year-old girl suffers from joint hypermobiiity, easy bruising and the tendency to develop atrophic scarring. Her father suffered from the same condition and died at the age of 46. Genetic testing showed a mutation on the gene COLPQAl. Which of the following investigations is highly recommended in this child?', 'Chest X-ray.', 'Dental check.', 'Echocardiography.', 'Full blood count.', 'Urinalysis.', 'C', '-rhe history and findings here are suggestive of Ehlers-Danlos (EDS) type IV which is an autosomal dominant condition.
This is a vascular type of EDS with the risk of aortic dissection/rupture.
Echocardiography is essential in those patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (379, 9, 'Which of the following genodermatoses is not inherited in an X-linked dominant fashion?', 'Bazex syndrome.', 'Conradi-Hunermann syndrome.', 'Dyskeratosis congenita.', 'Goltz syndrome.', 'Incontinentia pigmenti.', 'C', 'Dyskeratosis congentia is an X-linked recessive disorder.
incontinentia pigmenti, Goltz syndrome, Conradi-Hunermann syndrome, Bazex syndrome, CHILD and MIDAS are some of the other X-linked dominant dermatological syndromes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (380, 9, 'You are asked to see a premature neonate as he is born encased in shiny yellow covering. What is the most likely underlying dermatological condition?', 'Ichthyosis bullosa.', 'Ichthyosis hystrix.', 'Ichthyosis vulgaris.', 'Lamellar ichthyosis.', 'Rud syndrome.', 'D', 'Collodion babies are usually premature and are born encased in skin resembling a yellow, tight and shiny film.
Desquamation is usually complete by 2 to 3 weeks by which time the underlying skin disorder reveals itself.
The most common underlying diseases are lamellar ichthyosis and non-bullous congenital erythroderma.
Rarer conditions include Sjogren-Larsen syndrome, Dorfman-Chanarin syndrome (Neutral lipid storage disease), Gaucher''s disease type-2, Trichothyodystrophy, Netherton syndrome, Hay-Well syndrome and Eciiodermal dysplasias.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (381, 9, 'A 7-month old boy presents with an itchy red rash on the skin that has been diagnosed as atopic dermatitis. He also has a distinctive circular scaling on the trunk. He was born with widespread red scaly skin. Examination of the scalp hair shows it to be short, spiky, lustreless and brittle. What is the hair abnormality in this condition?', 'Monilethrix.', 'Pili torti.', 'Trichorrhexis invaginata.', 'Trichorrhexis nodosa.', 'Trichothiodystrophy.', 'C', 'The clinical features described above are those of Netherton syndrome.
Patients are erythrodermic at birth and later develop ichthyosis-ichthyosis lineariscircumflexa -circular scaling on the skin and a changing margin.
Trichorrhexlslnvaginata or Bamboo hair -refers to ball-and-socket-type hair-shaft deformity, which results in sparse, short, spiky, lustreless and brittle hair.
Allergic manifestations are commonly present.
These Include food allergies, hay fever, asthma, atopic eczema, angioedema and urticaria.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (382, 9, 'A 12-month old girl presents with subungual hyperkeratosis lifting the right little finger nail from the nail bed. She was born with a vesicular rash on her right forearm and hand. Which of the following stages in the condition is most likely to follow next?', 'Atrophic.', 'Hyperpigmented.', 'Hypopigmented.', 'Verrucous.', 'Vesicular.', 'D', 'incontinentia pigmenti is an X-linked dominant neurocutaneous syndrome.
Cutaneous features are seen in the following stages:
Stage 1 (vesicular) - present at birth or develop within the first 2 weeks of life in the vast majority. Red papules and vesicles on an erythematous base along Blaschko''s lines and seen prP.dominantly on the extremities.
Stage 2 (verrucous) - develop in the first few weeks to months of life and resolve over weeks to months. Thickened, warty-appearing linear and whorled plaques on an erythematous base along Blaschko''s lines.
Stage 3 (hyperpigmented)- streaks and whorls of brown or slate-gray pigmentation along Blaschko''s lines. The location of the hyperpigmented lesions do not correlate with areas of prior skin involvement.
Stage 4 (atrophic/hypopigmented) - develop during adolescence and persist into adulthood. Hypopigmented, atrophic, and reticulate or linear patches can be observed on the lower extremities.
Besides cutaneous lesions, patients may have neurologic, ophthalmologic, and dental manifestations.
Mutations in the NEMO/IKK -gamma gene, on chromosome Xq28 are responsible for incontinentia pigmenti.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (383, 9, 'A 13-year-old girl presents with multiple skin-colored nodules. In addition she has numerous coffee-coloured patches and macules on her skin. Her mother has similar coffee-coloured patches and macules. You diagnose the condition as neurofibromatosis type-1 (NF-1). Her mother is concerned about the risk of malignancy. Which of the following is the commonest malignancy in NF-1?', 'Leukaemia.', 'Neurofibrosarcoma.', 'Phaeochromocytoma.', 'Rhabdomyosarcoma.', 'Wilm''s tumour.', 'B', 'The most common malignancy in NF-1 is neurofibrosarcoma.
Other malignancies include phaeochromocytoma, leukaemia, Wilm''s tumour and rhabdomyosarcoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (384, 9, 'A 2.0-year-old man presents with facial angiofibromas and flesh-coloured plaques on the back. He is under the care of the neurologists for epilepsy. What is the earliest skin sign of this condition?', 'Ash leaf hypomelanotic macules.', 'Facial angiofibromas.', 'Forehead fibromatous plaque.', 'Peri-ungual fibromas.', 'Shagreen patch.', 'A', 'Tuberous sclerosis is a neurocutaneous disorder with an autosomal dominant inheritance pattern.
The earliest skin sign in tuberous sclerosis is hypomelanotic macules.
Facial angiofibromas appear at the age of 4-9 years.
Peri-ungual and subungual fibromas develop at or after puberty.
Shagreen patch refers to an irregularly thickened, slightly elevated, flesh-coloured plaque, most commonly over the lumbosacral area. It develops in late childhood or adolescence.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (385, 9, 'A 20-year-old man presents with facial angiofibromas, hypomelanotic macules and flesh-coloured plaques on the back. He is under the care of the neurologists for epilepsy. The hypomelanotic macules appear polygonal or ash leaf in shape under Wood''s light examination. What is the histological defect accounting for the hypomelanotic macules in this condition?', 'Abnormal melanin synthesis.', 'Absent melanin.', 'Absent melanocytes.', 'Absent melanosomes.', 'Excess phaeomelanin.', 'A', 'Abnormal melanin synthesis and impaired melanosome transfer from melanocytes to keratinocytes accounts for the hypomelanotic macules seen in tuberous sclerosis.
These macules are best seen with Wood''s light examination and appear polygonal or ash leaf shaped.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (386, 9, 'One of the following is not an inherited form of epidermolysis bullosa?', 'Dystrophic.', 'Hemidesmosomal.', 'Junctional.', 'Plaque.', 'Simplex.', 'D', 'Inherited epidermolysis bullosa (EB) is subclassified according to the level of skin separation seen in skin blisters on transmission electron microscopic analysis.
EB Simplex - intra-epidermal blistering associated with keratin gene mutations.
Hemidesmosomal EB - blistering skin disease with a level of separation that is inter-mediate between EB simplex and junctional EB.
Junctional EB - blister formation within the lamina lucida of the basement membrane zone due to defects of anchoring filaments.
Dystrophic EB - defects of the anchoring fibril, which results in s ublamina densa separation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (387, 9, 'Which of the following is characterized by the development of peri-orificial granulation tissue?', 'Dystrophic epidermolysis bullosa.', 'Hemi-desmosomal epidemolysis bullosa.', 'Kindler syndrome.', 'Lethal junctional epidermolysis bullosa.', 'Simplex epidermolysis bullosa.', 'D', 'Lethal junctional epidermolysis bullosa or Herlitz junctional epidermolysis bullosa patients is a life threatening disease.
Death rates of up to 40 % are seen in the first year of life and most of the surviving patients succumb before the age of 5 years.
Lethal junctional epidermolysis bullosa is characterized by generalized extensive blistering at birth.
Patients develop peri-orificial granulation tissue in infancy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (388, 9, 'Which of the following syndromes has desmoid syndrome as an associated feature?', 'Birt-Hogg-Dube syndrome.', 'Cowden''s syndrome.', 'Darier''s disease.', 'Gardner''s syndrome.', 'Turner''s syndrome.', 'D', 'Desmoid tumours are deep-seated, aggressive, low-grade clonal benign musculoaponeurotic fibromatoses.
They have an infiltrative growth pattern and locally recur, but do not metastasize.
They have a mutation in the adenomatous polyposis coli (APC) gene (Sq21) and are associated with familial adenomatous polyposis (FAP) syndrome and Gardner''s syndrome.
They are classified as extra-abdominal or intra-abdominal.
Intra-abdominal desmoids have been associated in 10 to 15 % of patients with FAP and Gardner''s syndrome, with the latter usually presenting as retroperitoneal tumors.');

-- Photodermatology
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (389, 10, 'A 26-year-old man has been troubled with intense burning erythema with swelling on sun exposed sites within minutes of exposure to sunlight. This has been impacting negatively on his quality of life and he is therefore working and spending most of his time indoors. On further questioning, the erythema and swelling normally subsides within few hours. He has tried various sun avoidance measures and the use of high factor sun creams and is enquiring about systemic treatment. Which of the following systemic treatments is the first line treatment for this condition?', 'Antihistamines.', 'Azathioprine.', 'Ciclosporin.', 'Methotrexate.', 'Mycophenolate mofetil.', 'A', 'Although immunosuppressive therapies can certainly be used with some degree of success in patients with solar urticaria, antihistamines remain first choice treatment.
UVB desensitisation can also be used in this condition provided that patients do not show sensitivity to that particular wavelength.
Erythema and wheals in solar urticaria develop within seconds to minutes following exposure to sunlight and almost always subside within 24 hours.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (390, 10, 'A 3-month old baby of consanguineous parents suffered severe sunburn following a limited exposure to sunlight. Examination showed dry skin but otherwise no abnormalities.There is no family history of photosensitivity. Which condition should be suspP.cted and looked for?', 'Actinic prurigo.', 'Hydroa vacciniforme.', 'Photo-aggravated eczema.', 'Systemic lupus erythematosus.', 'Xeroderma Pigmentosum.', 'E', 'Xeroderma pigmentosum is an autosomal recessive disorder characterized by marked photosensitivity, dry skin (hence the name xeroderma), abnormal freckling (hence pigmentosum) and a markedly increased risk of cutaneous neoplasms.
A less severe form exist called "variant" form of XP.
In XP marked sensitivity is to the UVB range is present hence the easy sunburns.
XP should always be considered in any baby who suffers easy sunburns and/or the presence of freckling under the age of 2 years.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (391, 10, 'Which of the following does not trigger or worsen porphyria cutanea tarda (PCT)?', 'Alcohol.', 'Haemochromatosis.', 'Human immunodeficiency virus.', 'Oestrogen-containing contraceptives.', 'Phlebotomy.', 'E', 'Serial phlebotomy is a treatment for PCT which can give clinicc::Iand biochemical remission and is particularly helpfu: in PCT patients with iron overload or haemochromatosis.
Low dose hydroxychloroquine (e.g. 200 mgtwice weekly) can be used particulcJrly in patients with normal or low iron levels.
Other triggers for PCT include hepatitis 8/C, genetic mutation for the uroporphyrinogen decarboxylase enzyme (the familial form), and rarely hepatocellular carcinoma.
Although PCT is the commonest cutaneous porphyria, variegate porphyria should always be excluded as this can be associated with fatal acute attacks and may present with cutaneous features similar to PCT.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (392, 10, 'A 65-year-old woman presents with blisters on the back of her hands. Her rash is photosensitive and you suspect that she may have porphyria and carry out a porphyrin screen which is normal. You take a detailed drug history. Which of the following is the most likely cause of her rash?', 'Bendrofluothiazide.', 'Captopril.', 'Codeine.', 'Nifedipine.', 'Paracetamol.', 'A', 'The clinical picture is that of pseudoporphyria-porphyria cutanea tarda-like photosensitive blistering and skin fargility.
No hypertrichosis, hyperpigmentation or sclerodermoid changes are seen.
Causes of pseudoporphyria include- NSAID''s, tetracyclines, haemodialysis, tanning booths, thlazides and frusemide.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (393, 10, 'Which of the following photosensitive or photo-aggravated conditions does not present with "blistering" following UV or visible light exposure?', 'Actinic prurigo.', 'Hydroa vacciniforme.', 'Photo-aggravated erythema multiforme.', 'Phytophotodermatitis.', 'Porphyria cutanea tarda.', 'A', 'Erythema multiforme can be aggravated following ultraviolet exposure (in particular if it was due to herpes simplex virus) and the photo-aggravated variant can be bullous In morphology.
Other conditions resulting In blistering following UV exposure include pseudoporphyria and bullous lupus erythematosus.
Actinic prurigo presents with excoriated papules or nodules (sometimes with plaques or an eczematous appearance) but not with blistering.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (394, 10, 'A 7-year-old boy presents with pruritic papules on the face and dorsal hands following exposure to the sunlight. The symptoms require a minimum of 20 minutes exposure and appe,3r few hours afterwards. On examination there were excoriated papules on the nose, ears and cheeks with an excoriated lesion on the lower lip. Further history reveals conjunctival symptoms. There is no family history of photosensi tive disorders. What is the most likely diagnosis?', 'Actinic prurigo.', 'Chronic actinic dermatitis.', 'Hydroa vacciniforme.', 'Polymorphic light eruption (PLE).', 'Solar urticaria.', 'A', 'The history and findings of excoriated papules on the face with involvement of tne nose and cheilitis is typical of actinic prurigo.
Conjunctival involvement is common In this condition.
Unlike PLE, this condition tends to worsen as summer progresses and patients do not develop tolerance.
Hydroa vacciniforme presents with vesicles which become haemorrr,agic leaving pock-like scars.
Chronic actinic dermatitis is not seen in childhood and affects mostly middle-agea and old men.
Papules are the commonest morphological presentation of PLE (others ir,c.lude vesicles, urticarial, and eczematous variants) but are usually not excoriated and do not involve the lips and are not associ,fied with conjunctival symptoms.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (395, 10, 'In which of the following photosensitive disorders is sensitivity to the visible wavelength always present?', 'Chronic actinic dermatitis.', 'Hydroa vacciniforme.', 'Polymorphic light eruption.', 'Solar urticaria.', 'Variegate prophyria.', 'E', 'All porphyrias are sensitive to the visible wavelength of the radiation, hence sunblocks that only block UVB and to a lesser degree UVA are largely ineffective in this condition.
Solar urticaria is sensitive to predominantly UVA but the range of sensitivity can ex tend to involve both the UVB and visible light spectra.
Around half of the patients with chronic actinic dermatitis exhibit photosensitivity in the visible wavelength.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (396, 10, 'In which of the following photosensitive disorders is monochromator reading nearly always abnormal?', 'Actinic prurigo.', 'Chronic actinic dermatitis.', 'Hydroa vacciniforme.', 'Photo-aggravated eczema.', 'Polymorphic light eruption.', 'B', 'Although any photosensitive disorder can have abnormal monochromator readings, these are nearly always(technique dependent) abnormal in chronic actinic dermatitis, solar urticaria, porphyria, and to a lesser degree drug-induced photosensitivity.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (397, 10, 'Which of the following - predominantly childhood - photosensitive disorders is not inherited in an autosomal recessive pattern?', 'Actinic prurigo.', 'Bloom''s syndrome.', 'Cokayne syndrome.', 'Rothmund Thompson syndrome.', 'Xeroderma pigmentosum.', 'A', 'Although actinic prurigo has a strong association with HLA-DRBl*0407, the condition is not inherited through the Mendelian pattern.
Rothmund Thomson syndrome is associated with photosensitivity, poikiloderma, short stature, skeletal dysplasia and juvenile cataracts.
The condition can predispose to squamous cell carcinomas and osteosarcomas.
Bloom''s syndrome is characterized by photosensitivity and poikiloderma but growth retardation is more marked and the risk of developing malignancies is much greater but these tend to be leukaemias early in life and solid organ tumours later.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (398, 10, 'Which of the following surfaces reflect ultraviolet rays the most?', 'Grass.', 'Mud.', 'Sand.', 'Snow.', 'Water.', 'D', 'Snow can reflect around 90% of the UV rays followed by water and sand.
Sun protection advice should always include the risk of reflection from those surfaces.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (399, 10, 'Which of the following statements regarding photodynamic therapy is false?', 'Photodynamic therapy is associated with a better cosmetic outcome than cyrotherapy in the treatment of superficial basal cell carcinoma (sBCC).', 'Photodynamic therapy is recommended for the treatment of small squamous cell carcinomas (SCCs).', 'Surgical excision is more effective than photodynamic therapy for treatment of nodular basal cell carcinoma (nBCCs).', 'Topical methylarninolevulinate and 5-arninolevulinic acid photodynamic therapy are effective treatments for sBCCs.', 'Topical methylaminolevulinate and 5-aminolevulinic acid photodynamic therapy are equally effective in the treatment of small nBCCs.', 'B', 'Topical methyl aminolevulinate and 5-aminolevulinic acid photodynamic therapy are effecitive treatments for sBCCs.
Results of a study directly comparing these two photosensitisers in treatment of nBCCs showed no difference in efficacy.
Surgical excision is more effective than fractionated illuminated 5-aminolevulinic acid photodynamlc therapy for treatment of nBCCs.
For patients with sBCCs, methyl-aminolevulinate photodynamic therapy has a similar response to that of cryosurgery but cosmetic outcome is better with photodynamic therapy.
Since data are scarce for the efficacy of topical photodynamic therapy in primary cutaneous invasive SCCs, topical therapy cannot be recommended for sec.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (400, 10, 'Which of the following photosensitive disorders is typically inherited in a non-autosomal recessive pattern?', 'Erythropoietic protoporphyria.', 'Bloom''s syndrome.', 'Cockayne syndrome.', 'Kindler syndrome.', 'Congenital erythropoietic porphyria.', 'A', 'Porphyrias with cutaneous involvement are, without exception, photosensitive and can be classified depending on hepatic and/or e;ythropoietic involvement.
Hepatic porphyrias with cutaneous involvement present with i.?ss acute skin changes and concern:
Porphyria cutanea tarda: Inheritance: Autosomal dominant (20-30%) or acquired. Enzyme defect: Uroporphyrinogen decarboxylase
Hereditary coproporphyria: Inheritance: Autosomal dominant. Enzyme defect:
Coproporphyrinogen oxidase
Mixed hepatic c:1nd erythropoietic porphyria withcutaneous involvement also demonstrates less acute skin change and concerns:
Variegate Porphyria. Inheritance: Autosomal dominant. Enzyme defect: Pro toporphyrinogen oxidase
Erythropoietic porphyrias manifests with acute skin change and concern:
Erythropoietic protoporphyria: Inheritance: Mostly autosomal dominant (but autosomal recessive cases have been reported)
Congenital erythropoietic porphyria: Inheritance: Autosomal recessive. Enzyme defect: Ferrochelatase
X-linked sideroblastic anaemia: Inheritance: X-linked recessive defect in the ALAS2 gene. Enzyme defect: Erythroid ALA-synthase Other autosomal recessive photosensitive disorders to be aware of include:
Rothmund-Thompson syndrome
Smith-Lemi-Opitz syndrome
Trichothiodystrophy Xeroderma pigmentosum');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (401, 10, 'A 50-year-old woman develops a vesicular eruption over her lower lip after starting PUVA for vitiligo. What is the most likely cause?', 'Photosensitivity due to an associated autoimmune connective tissue disorder.', 'Fixed drug eruption to ingested psoralen.', 'Photoburn.', 'HSV reaction.', 'Coincidental.', 'D', 'Narrow-band UVB cian also elicit HSV reactivation
Other side effects shared by both treatment modalities include photo-aging and increased risk of skin cancer (although the risk with narrow-band UVB is considerably lower).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (402, 10, 'A 35-year-old man with skin phenotype 2 is to start narrow-band UVB for poorly controlled, chronic plaque psoriasis. What is the maximum number of sessions he can have in a lifetime?', '350.', '200.', '300.', '400.', '500.', 'C', 'The maximum number of sessions for narrow-band UVB is 300.
A 48-hour gap is needed between each session, allowing 3 sessions per week.
For PUVA a maximum of 250 sessions are allowed over a lifetime.
A 72-hour gap is needed between each session, allowing 2 sessions per week.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (403, 10, 'An 8-year-old boy presented with his mother with a history of extreme photosensitivity with a burning and painful sensation within minutes following sun exposure. He had on several occasions, been noted to have swelling of the hands following sun exposure. Hiselder brother has similar symptoms and is currently takingbeta-carotene tablets. The enzyme defect In this condition is:', 'Coproporphyrinogen oxidase.', 'Ferrochelatase.', 'Protoporphyrinogen oxidase.', 'Uroporphyrinogen decarboxylase.', 'Uroporphyrinogen synthase.', 'B', 'Ferrochelatase isthe enzyme defect in erythropoietic protoporphyria which typically presents with pain and burning sensation, extreme sun sensitivity within minutes to exposure of sunlight and may be associated with swelling of the hands.
Protoporphyrinogen oxidase is the enzyme defect in variegate porphyria.
Uroporphyrinogen decarboxylase is the enzyme defect in porphyrio cutanea tarda.
In hereditary coproporphyria the defect is in coproporphyrinogenoxidase.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (404, 10, 'A 64-year-old man has two patches of Bowen''s disease on the left lower leg, previously treated with cryotherapy with little success. A consultant dermatologist suggested treatment with photodynamic therapy and the use of methyl levulenic acid (MAL). What should be the approximate application time of the MAL for treatment with alight source?', '30 minutes.', '1 hour.', '3 hours.', '6 hours.', '24 hours.', 'C', 'The ideal application time for MAL is 3 hours, to ensure maximum affectivity.
Shorter duration of application may result in ineffective therapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (405, 10, 'Which of the following wavelengths is responsible for immediate tanning?', 'Infared.', 'Microwave.', 'UVA.', 'UVB.', 'Uvc.', 'C', 'Immediate tanning occurs within 5 to 10 minutes of exposure to UVA irradiation (often referred to as immediate pigment darkening "IPD").
It represents melanosomal relocation from the perikaryon to melanocytic dendrites.
It fades within minutes to days.
It does not provide photoprotection and does not increase epidermal melanin level.
It is predominantly visible in darker individuals.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (406, 10, 'Photosensitivity is not a presenting feature of one of the following?', 'Acute intermittent porphyria.', 'Congenital erythropoietic porphyria.', 'Erythropoietic protoporphyria.', 'Hereditary coprophorphyria.', 'Variegate porphyria.', 'A', 'Acute intermittent porphyria results from defects in porphobilinogen-deaminase.
Attacks are characterised by abdominal pain, psychiatric symptoms and peripheral neuropathy.
There are no skin manifestations in acute intermittent porphyria.
Variegate porphyria presents similarly to PCT but with the presence of acute symptoms; therefore it is essential to exclude this diagnosis in patients suspected of PCT through urine porphyrin measurements together with a plasma porphyrin scan.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (407, 10, 'A 10-year-old girl was referred to the dermatologist with a history of sun-sensitivity resulting in small papules and vesicles, often on the face and predominantly the nose. Some of the vesicles became haemorrhagic and had healed with crusting. Examination revealed some atrophic scars on the face and the arms where the haemorrhagic vesicles were present. Provocation tests later revealed a few papules and vesicles. What is the most likely diagnosis?', 'Actinic prurigo.', 'Acute lupus erythematosus.', 'Hydroa vacciniforme.', 'Polymorphic light eruption.', 'Xeroderma pigmentosum.', 'C', 'Hydroa vacciniforme isa photosensitive disorder which is often diagnosed in children and tends to improve later in adult life.
Typically, the lesions present with papules and vesicles, some of which may become haemorrhagic and heal with crusting and erosions. Atrophic scars can be seen as a result.
Xeroderma pigmentosum (XP) is an autosomal recessive photosensitive disorder which often presents with severe photosensitivity, dryness of the skin and abnormal freckling.
Patients with XP are at a greater risk of developing skin tumours at very early age.
.., Polymorphic light eruption is a non-scarring idiopathic photosensitive disorder.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (408, 10, 'In which of the following is the risk of developing squamous cell carcinomas the highest?', 'Acitretin followed by PUVA.', 'Ciclosporin followed by PUVA.', 'Mycophenolate mofetil.', 'PUVA.', 'UVB.', 'B', 'Multiple factors contribute to the development of squamous cell carcinomas, such as immunosuppression, ultraviolet therapy, chronic wounds, arsenic ingestion, pre-existent dysplastic lesions and previous radiotherapy.
The risk of developing skin cancers following treatment with PUVA is higher than that compared to UVB and this risk is particularly high when PUVA is administered in a patient who was previously treated with ciclosporin.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (409, 10, 'Which of the following photodermatoses is not seen in children?', 'Actinic prurigo.', 'Chronic actinic dermatitis.', 'Erythropoietic protoporphyria.', 'Hydroa vacciniforme.', 'Photo-aggravated eczema.', 'B', 'Chronic actinic dermatitis is mostly seen in elderly men, although women and young adults may also be affected.
It is not seen in children and the condition is often persistent.
Multiple contact allergies are often associated with thecondition.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (410, 10, 'Which of the following photosensitive disorders is least likely to give symptoms shortly following exposure to UV or visible light?', 'Drug-induced photosensitivity.', 'Erythropoietic protoporphyria.', 'Lupus erythematosus.', 'Rapid onset polymorphic light eruption.', 'Solar urticaria.', 'C', 'Lupus erythematosus, actinic prurigo and hydroa vacciniforme do not generally give immediate symptoms following exposure to light.
Polymorphic light eruption (PLE) typically has a latency period of several hours but a less common variant exist in which short exposure to light triggers the rash (rapid onset PLE).
Drugs should always be included in the differential of immediate photosensitivity, particularly if the symptoms occur in a patient who previously could tolerate UV and visible light exposure.');

-- Skin Biology & Research
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (411, 12, 'At which level does lm NaCl cause a split in the skin?', 'Desmoplakin.', 'Desmosome.', 'Hemidesmosome.', 'Lamina densa.', 'Lamina lucida.', 'E', 'Lamina lucida is the weakest part of the basement membrane.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (412, 12, 'Which of the following is a key component of inner dense plaque?', 'Desmocollin.', 'Desmoplakin.', 'Envoplakin.', 'Plakoglobin.', 'Plakophilin.', 'B', 'Desmosomal proteins fall into three major gene families:
Plakins -desmoplakin.
Armadillo proteins-plakoglobin and plakophilins.
Desmosomal cadherins-desmogleins and desmocollins.
Plakins and armadillo proteins are found in the plaque.
Desmosomal cadherins are extracellular amino-termini of transmembrane proteins, which comprise the desmogleins.
Desmoplakin is the major inner plaque component.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (413, 12, 'Sebaceous glands are absent in which of the following?', 'Nose.', 'Palms.', 'Penis.', 'Skin overlying the abdominal wall.', 'Skin overlying the shoulders.', 'B', 'Palms and soles do not contain sebaceous glands or hair follicles.
Facial skin and in particular the nose contain the largest number of sebaceous glands.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (414, 12, 'Epidermal desmosomes serve to adhere the cells together due to the presence of various glycoproteins. Which of the following components of the desmosomes is not targeted in paraneoplastic pemphigus?', 'Corneodesmosin.', 'Desmoglein.', 'Desmoplakin.', 'Periplakin.', 'Plakoglobin.', 'A', 'Corneodesmosin is targeted by the autosomal dominant rare condition hypotrichosis simplex of the scalp.
Plakoglobin is also targeted in the inherited disorder of Naxos disease.
Desmoglein-1 is targeted in pemphigus foliaceous, whereas desmoglein 3 (and desmoglein-1) are targeted in pemphigus vulgaris.
A rare variant of pemphigus called IgA-pemphigus results from antibodies targeting desmocollins.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (415, 12, 'Eccrine sweat glands are present in which one of the following sites?', 'Clitoris.', 'External auditory canal.', 'Fingertips.', 'Labia minora.', 'Lips.', 'C', 'External auditory canal, lips, clitoris and labia minora do not have eccrine glands.
Apart from the above, approximately 1.6 to 4.0 million eccrine sweat glands are distributed over the entire body skin surface.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (416, 12, 'Which of the following structures is involved in the Lewis reaction (also known as the hunter''s reflex)?', 'Pilosebaceous unit.', 'Eccrine unit.', 'Glomus body.', 'Pacinian corpuscle.', 'Meissner''s corpuscle.', 'C', '.., The Lewis reaction/ hunter''s reflex describes the normal pallor of fingers and other extremities in response to cold.
The glomus apparatus or body is a dermal structure consisting of an arteriovenous shunt under autonomic nervous system control. Most numerous in the extremities it plays an important role in temperature regulation by shunting blood away from the skin surface when exposed to cold temperature.
The eccrine and pilosebaceous units also play a role in temperature regulation but via sweat production and hair contracture, respectively.
The Pacinian corpuscle detects vibration and the Meissner''s corpuscle detects fine touch.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (417, 12, 'You wish to undertake a research study to assess circadian variation in keratinocyte RNA levels. Which of the following research techniques would be most appropriate?', 'Western blotting.', 'Northern blotting.', 'Southern blotting.', 'Eastern blotting.', 'Polymerase chain reaction.', 'A', 'A useful aid-memoire is SNoW DRoP, where southern blotting relates to DNA, Northern blotting to RNA and Western blotting to protein.
Eastern blotting allows analysis of post-translational protein modifications (PTM).
Reverse PCR would be used to amplify RNA.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (418, 12, 'What is the trans-epidermal cycle time in normal skin?', '24 days.', '18 days.', '28 days.', '14 days.', '32 days.', 'C', 'Starting in the basal layer it takes 14 days for the maturing keratinocyte to reach to stratum corneum and a further 14 days to reach to the very surface of thi,sayer, allow ing it to be shed.
The trans-epidermal time is considerably shorter in diseases such as psoriasis and is prolonged in the elderly.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (419, 12, 'A patient is carrying a CTLA-4 gene mutation. Which of the following diseases would you wish to exclude?', 'Tuberous sclerosis.', 'Atopic dermatitis.', 'Coeliac disease.', 'Desmoid tumours.', 'Amyloidosis.', 'C', 'The CTLA-4 protein is found on the surface of cytotoxic r cells and functions to down-regulate immune responses.
Mutations in the gene encoding this protein predispose to autoimmune disease including coeliac disease, insulin-dependent diabetes mellitus, autoimmune thyroid dis ease and lupus erythematosus.
Similarly, pharmacological inhibition of CTLA-4, with agents such as ipilimumab, can also trigger autoimmune phenomena.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (420, 12, 'Which type of collagen is the most abundant in the dermis?', 'Type I collagen.', 'Type II collagen.', 'Type III collagen.', 'Type V collagen.', 'None of the above.', 'A', 'The dermis is composed of type 1 collagen that forms nearly 80%, with nearly 15- 20% type 3 collagen and a small amount of type 5 collagen.
Collagens provide the tensile strength in the dermis, whereas the elastic fibres pro vide the elasticity of the dermis.
The origin of the collagen is from the fibroblasts which are found in the dermis.
There are 2.8 types of collagen.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (421, 12, 'Which of the following is not a ubiquitous component of the basement membrane?', 'Collagen IV.', 'Fibulins.', 'Lamin ins.', 'Nidogens.', 'Perlecan.', 'B', 'Basement membranes contain collagenous and non-collagenous glycoproteins and proteoglycans.
Collagen IV, laminin, nidogen, and heparan sulfate proteoglycanperlecan are ubiquitially present in all basement membrane.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (422, 12, 'Which of the following resultsfrom altered a6 4 integrin?', 'Cicatritial pemphigoid.', 'Epldermolysis bullosa acquisita.', 'Epldermolysis bullosa simplex.', 'Junctional epidermolysis bullosa-Herlitz type.', 'Linear IgA disease.', 'A', 'Keratin 5 and 14 mutations result in epidermolysis bullosa simplex.
Collagen XVII/BP180 - linear IgA disease.
Collagen VII - Epidermolysis bullosa acquisita.
Laminin 332/laminin-5 - Junctional epldermolysis bullosa - Herlitz and non-Herlitz.
a6P4 integrin - Cicatritial pemphigoid.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (423, 12, 'Filaggrin mutations are not associated with one of the following disorders?', 'Allergic rhinitis in patients with atopic dermatitis.', 'Asthma in patients with atopic dermatitis.', 'Bronchitis.', 'Ichthyosis vulgaris.', 'Keratosis pilaris.', 'C', 'Mutations in the filaggrin gene are associated with ichthyosisvulgaris.
Mutations in filaggrin are also a risk factor for atopic dermatitis and are associated with disease severity.
Among patients with atopic dermatitis, mutated filaggrin is associated with asthma, allergic rhinitis and allergic sensitisation.
Mutated filaggrin is not independently associated with asthma.
Mutated filaggrin predicts a more severe course in alopecia areata.');

-- Skin of Colour
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (424, 13, 'A 4-week old Afro-Caribbean boy presents to the dermatology clinic with pigmented macules on the trunk which followed clearance of pus-filled spots. The following statement is true:', 'Peripheral eosinophilia is common.', 'Skin biopsy shows subepidermal blister.', 'The clinical course is protracted and may last many years.', 'The rash is more common in Afro-Caribbean babies.', 'Topical corticosteroid should be prescribed.', 'D', 'The clinical picture described above is that of transient neonatal pustular melanosis.
It affects approximately 5% of black neonates and <1% of white neonates.
Transient vesiculopustules which resolve in 48 hours give way to pigmented macules.
The pigmented macules usually resolve within 3 months.
The pustule is subcorneal and neutrophilic.
Unlike erythema toxicumneonatorum, peripheral eosinophilia is absent.
The condition is self-limiting and no treatment is requiied.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (425, 13, 'Which of the following is not a cause of exogenous ochronosis?', 'Glycolic acid.', 'Mercury.', 'Phenol.', 'Picric acid.', 'Resorcinol.', 'A', 'Exogenous ochronosis results from the use of certain medications, including hydroquinone, anti-malarialsand products containing resorcinol, phenol, mercury, and piaic acid.
It presents as asymptomatic hyperpigmentation of the face, sides and back of the neck, back, and extensor sites of the extremities.
Yellowish-brown globules accumulate in the papillary dermis.
Unlike endogenous ochronosis, there is no articular, renal, or cardiovacular involvement.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (426, 13, 'A 21-year-old Afro-Caribbean man reported a five year history of persistent painful purulent draining scalp lesions accompanied by p ogressively worsening alopecia. Physical examination reveals pustules, nodules and fluctuant abscesses, and multiple palpable cervical lymph nodes. Pus waseasily drained from some of the abscesses and there were communicating sinuses visible. For thiscondition, which of the following statementsis incorrect?', 'Anti-fungal treatment is not indicated in this condition.', 'Arthralgia may occur in some cases.', 'Basal cell carcinoma may complicate long-standing disease.', 'Staphylococcus is often the most commonly cultured pathogen from secondarily infected lesions.', 'The pathogenesis of thiscondition relates to primary follicular occlusion disorder.', 'C', 'Dissecting cellulitis of the scalp belongs together with hidradenitis suppurativa and acne conglobata to the primary follicular occlusion disorders.
Arthralgia can occur in some cases as a systemic manifestation of the disease.
Squamous cell carcinoma and not basal cell carcinoma may complicate long-standing disease.
Treatment is often disappointing; however there is no role for anti-fungal therapy.');

-- Skin Oncology
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (427, 14, 'The dermatology registrar in the department excised an atypical looking mole on the shoulder of a 24-year-old sun worshipper. Histology showed superficial spreading melanoma with a Breslow thickness of 1.3 mm without ulceration. You are referring the patient to the plastic surgeon for re-excision. What should be the re-excision margins?', '5mm.', '1 cm.', '1.5cm.', '2 cm.', '3 cm.', 'C', '5 mm is the margin is employed for melanoma in-situ and lentigo maligna (melano ma in situ in sun-damaged skin).
The guidelines suggest that in thin melanomas (less than 1 mm in depth), these should be excised with a margin of at least 1 cm and for melanomas, between 1.01-2 mm a margin of 2 cm when pcs.sible.
2 mm margin is the initial margin used for atypical naevi as was the case here.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (428, 14, 'Which of the following tumours is most likely to develop in organ transplant recipients?', 'Basal cell carcinoma.', 'Brain tumour.', 'Cutaneous lymphoma.', 'Melanoma.', 'Squamous cell carcinoma.', 'E', 'Although the incidence of cutaneous tumours and dysplastic lesions is greatly in creased in patients with organ transplantation due to immune suppression, the risk of squamous cell carcinoma (SCC) in particular is greatly increased (x 60-250) and the usual basal cell carcinoma: sec incidence ratio of 4:1is reversed.
The risk of basal cell carcinoma and melanoma is also increased but to a lesser de gree compared to secs.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (429, 14, 'Which of the following presents with ''buttonholing'' or ''dimple sign'' on lateral pressure?', 'Angiofibroma.', 'Dermatofibroma.', 'Fibrofolliculoma.', 'Giant cellcollagenoma.', 'Solitary fibrous tumour.', 'B', 'Dermatofibromas are firm, indurated, but mobile common mesenchymal lesions.
Lateral compression of dermatofibroma produces a dimple-like depression in tht:
overlying skin ("buttonholing").');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (430, 14, 'Which of the following statements regarding leukaemia cutis is incorrect?', 'Children with leukaemia are more likely to be affected than adults.', 'Cutaneous signs can appear prior to systemic involvement.', 'Mostly associated with acute myeloid leukaemias.', 'Portends a good prognosis for theileukaemia.', 'Presence of leukaemia cutis is often associated with extra-medullary haemopolesis.', 'D', 'Leukaemia cutis is often associated with a poor prognosis and may precede the detection of systemic disease when it is then referred to as "aleukaemia cutis".
Treatment is very challenging and is mainly palliative.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (431, 14, 'Which of the following is the commonest clinical subtype of basal cell carcinoma?', 'Morphoeic.', 'Nodulocystic.', 'Pigmented.', 'Superficial.', 'Ulcerated.', 'B', 'Roughly 80% of all ba al-cell carcinomas occur on the head and neck.
In addition to the classic rodent ulcer with an indurated edge and ulcerated centre (nodular or cystic), superficial, morphoeic, and pigmented basal-cell carcinomas are other common subtypes.
10-40% of basal-cell carcinomas contain a mixed pattern of two or more of these histological subtypes, drawing attention to the need for a clinicopathological diagnosis.
By contrast with nodulocystic basal-cell carcinoma-which is the most common subtype, usually presenting on the head and neck-superficial basal-cell carcinomas predominantly present on the trunk.
5% of allbasal-cell carcinomas are morphoeic lesions, which have ill-defined borders, can be difficult to diagnose clinically, and often present late.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (432, 14, 'One of the following syndromes does not predispose to cutaneous squamous cell carcinoma?', 'Dystrophic epidermolysis bullosa.', 'Gorlin''s syndrome.', 'KID syndrome.', 'Muir-Torre syndrome.', 'Xeroderma pigmentosum.', 'B', 'The following are syndromes predisposing to cutaneous squamous cell carcinoma:
Xeroderma pigmentosum - autosomal recessive; multiple epidermal skin cancers in childhood; increased susceptibility to DNA damage; abnormal DNA base excision repair.
Albinism - part or complete failure to produce melanin in the skin and eyes.
Muir-Torre syndrome-autosomal dominant; germline mutations in genes involved in DNA mismatch repair; sebaceous neoplasms in association with internal malignancy.
KID (keratosis, icthyosis, deafness) syndrome - development of invasive squamous cell carcinoma within dysplastic lesions.
Dystrophic epidermolysis bullosa - autosomal recessive m''?.chano-bullous disorder; mutations in the human type VII collagen gene (COL.7Al).
Fanconi anaemia - autosomal recessive; congenital malformations; bone-marrow failure; development of squamous-cell carcinoma and other cancers.
Rothmund-Thompson syndrome - autosomal recessive; progressive poikiloderma including alopecia, dystrophic teeth and nails, juvenile cataracts, short stature, hypogonadism, and bone defects.
Werner syndrome - early ageing; excess cancer risk; high incidence of type 2 diabetes mellitus; early atherosclerosis; ocular cataracts; osteoporosis.
Others - Hereditary non-polyposis coli; dyskeratosis congenit-a; Huriez syndrome; LiFraumeni syndrome and chronic mucocutaneous candidiasis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (433, 14, 'Which of the following is not a poor prognostic factor in basal cell carcinomas?', 'Morphoeic lesions.', 'Perineural invasion.', 'Perivascular invasion.', 'Size >5 cm.', 'Truncal lesions.', 'E', 'Factors determining poor prognosis in basal cell carcinomas include: morphceic lesions, tumour size) 5 cm (giant), deeper lesions, centrofacial and ears, infiltrative and micronodular histological subtypes, histological features of aggression including perineural or perivascular involvement, or both and recurrent lesions.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (434, 14, 'Which of the following is not a risk factor for the development of Bowen''s disease?', 'Arsenic ingestion.', 'Gorlin''s syndrome.', 'Human-papilloma virus (HPV).', 'Immunosuppression.', 'Ultraviolet radiation.', 'B', 'Gorlin''s syndrome predisposes to multiple basal cell carcinomas and not Bowen''s disease or squamous cell carcinoma.
Other features of Gorlin''s syndrome include palmoplantar pits, odontogenic jaw cysts, frontal bossing, medulloblastomas, lipomas and hypogonadism.
HPV can cause Bowen''s disease and is one of the aetiologic factors for the development of squamous cell carcinomas in transplant patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (435, 14, 'Which one of the following factors does not confer a higher risk of recurrence for basal cell carcinomas?', 'Presence of perineural invasion histologically.', 'Truncal lesions,', 'Tumour around the lips or ears.', 'Tumour size) 2 cm.', 'Tumour with poorly defined clinical margins.', 'B', 'Recurrence risk for basal cell carcinomas depends on several factors iniluding size, site, clinical margins, histological subtype/features of aggressive tumour, and failure of previous treatments.
High-risk sites include areas around the eyes, nose, lips and ears.
The presence of a metaplastic, Infiltrative, morphoeic or micro-nodular histological subtype is regarded as a high risk tumour.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (436, 14, 'Regarding the use of radiotherapy in basal cell carcinoma (BCC), which statement is false?', 'Radiotherapy can be used as an adjuvant treatment.', 'Radiotherapy can be used in the treatment of primary BCC.', 'Suitable as a mode of treatment for radiorecurrent BCC.', 'Suitable as a mode of treatment for surgically recurrent BCC.', 'None of the above.', 'C', 'Radiorecurrent BCCs should not be retreated with radiotherapy and should be excised surgically.
Radiotherapy may be more preferable as first-line therapy in elderly or infirm pa tients in whom surgery may not be possible.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (437, 14, 'Which of the following benign lesions can arise from a congenital naevus sebaceous?', 'Intradermal naevus.', 'Juvenile xanthogranuloma.', 'Myxoid cyst.', 'Seborrhoeic keratosis.', 'Syringocystoadenomapapilliferum.', 'E', 'Naevus sebaceous represents a congenital hamartoma of sebaceous elements most commonly found on the scalp.
Although it is present at birth, it acquires a verrucous appearance at puberty.
Other lesions that may arise from it include basal cell carcinoma and trichoblastoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (438, 14, 'A 23-year-old woman presented with a 1 cm firm nodule on the lower leg which has been present for 8 months. She is unsure as to how thisappeared. Examination showed a firm flesh-coloured nodule with no surface change which puckered on gentle squeezing of the edges. The most likely diagnosis is:', 'Bowen''s disease.', 'Dermatofibroma.', 'Keratoacanthoma.', 'Nodular melanoma.', 'Seborrhoeic keratosis.', 'B', 'The description is of a dermatofibroma which is a histiocytic lesion that often occurs on the lower legs of women and may be related to an insect bite or trauma.
Nodular melanoma should always be included in the differential of a nodule on the leg as it can be amelanotic.
The firm consistency and puckering on squeezing should aid in the diagnosis of a dermatofibroma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (439, 14, 'Which of the following treatments is the least suitable treatment for superficial basal cell carcinoma?', 'Cryotherapy.', 'Curettage and cautery.', 'Diclofenac sodium gel.', 'Imiquimod.', 'Photodynamlc therapy.', 'C', 'Diclofenac sodium (Solaraze) gel is only licensed for the treatment of thin actinic keratoses.
Although all other treatments listed can be used, the choice will depend on the site, size, thickness and overall risk of recurrence.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (440, 14, 'In which anatomical sites do squamous cell carcinomas have worst prognosis?', 'Ear.', 'Forehead.', 'Lower leg.', 'Neck.', 'Nose.', 'A', 'The prognosis and risk of metastasis of squamous cell carcinoma depend on several factors which include size, histology (poorly-differentiated) and past medical history (transplant patients are at particular risk).
Squamous cell carcinoma arising on the ear is associated with a poor prognosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (441, 14, 'Which of the following is not a poor prognostic factor in cutaneou5 squamous cell carcinoma (SCC)?', 'Broders'' grade 2.', 'Desmoplastic lesions.', 'Host immunosuppression.', 'Tumour depth > 2 mm.', 'Tumour size) 2 cm.', 'A', 'Factors determining poor prognosis in cutaneous SCC include tumour size > 2 cm, tumour depth) 2 mm (especially 6 mm), tumour at sites of radiation, thermal damage, ulceration, sinuses, inflammation, scars or Bowen''s disease, non-exposed sites, ear, and lip.
Spindle cell (carcinosarcomas), acantholytic, desmoplastic histological subsets.
Histological features of aggression including perineural or perivascuiar involvement, or both, Broders'' grades 3 and 4, host immunosuppression and recurrent lesions, lymph-node involvement or distant metastasis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (442, 14, 'A 70-year-old man presents with a biopsy-proven basal cell carcinoma (BCC) on his forehead. He had this lesion treated with radiotherapy nearly 4 years ago. Which of the following is contra-indicated for the treatment of this lesion?', 'Curettage.', 'Mohs'' micrographic surgery.', 'Observation.', 'Radiotherapy.', 'Surgical Excision.', 'D', 'Side-effects of radiotherapy include dyspigmentation, telangiectasia, and radiodys trophy, resulting in a poor cosmetic outcome.
Radiotherapy is contra-indicated In the treatment of BCCs that have recurred after radiotherapy.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (443, 14, 'A 68-year-old patient has superficial basal cell carcinomas(sBCCs) on the upper chest. The dermatologist has prescribed a cream which acts by stimulating toll-like receptor 7. The active ingredient in the cream is:', '5-Fluorouracil.', '5-aminolevulinic acid.', 'Diclofenac sodium.', 'Imiquimod.', 'Methyl aminolevulinate.', 'D', 'imiquimod is a synthetic immune-response modifier belonging to the imidazoqulnolone family.
It acts by stimulating toll-like receptor 7, which is expressed on dendritic cells and monocytes, leading to increased production of cytokines and chemokines, which in turn promote both T-helper-1 innate and adaptive cell-mediated immune responses.
Topical 5% imiquimod cream is an emerging non-invasive therapeutic option for sBCCs.
Local skin reactions including erythema, oedema, pruritus, erosion, ulceration, dyspigmentation,and scabbing are common side-effects.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (444, 14, 'Whilst reading a histopathology report you come across the term Breslow thickness. You are aware that this determines the prognosis in cutaneous melanoma. Breslow thickness is measured from:', 'Stratum basale.', 'Stratum corneum.', 'Stratum granulosum.', 'Stratum lucidum.', 'Stratum spinosum.', 'C', 'Breslow tumour thickness is measured from the top of the granular layer or the base of an ulcer to the deepest point of tumour invasion using an optical micrometer.
As a general rule the thicker the Breslow thickness, the poorer the prognosis.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (445, 14, 'A 58-year-old man underwent excision of a yellow nodule on the upper eyelid that is histologically confirmed as sebaceous adenoma. He has a family history of colonic carcinoma. Which of the following is the most likely diagnosis?', 'Brit-Hogg-Dube syndrome.', 'Cowden''s syndrome.', 'Gardner''s syndrome.', 'Gorlin''s syndrome.', 'Muir-Torre syndrome.', 'E', 'Muir-Torre syndrome refers to the presence of sebaceous adenoma, sebaceoma, or sebaceous carcinoma with visceral cancer, usually gastrointestinal or genito-urinary.
Patients may also present with other cutaneous lesions including keratoacanthoma, squamous cell carcinoma, or multiple follicular cysts.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (446, 14, 'Which of the following is the most important prognostic factor in the diagnosis of melanoma?', 'Anatomical site of melanoma.', 'The presence of lymphocytic infiltrate.', 'The presence of mitoses.', 'Tumour thickness.', 'Ulceration.', 'D', 'The thickness, measured as Breslow thickness, is the most important prognostic factor in melanoma.
All other factors are also important but the surviv2I rate strongly correlates with the thickness of the tumour.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (447, 14, 'Which of the following is the most common site for sebaceous carcinoma?', 'Extremities.', 'Eyelids.', 'Ears.', 'Lips.', 'Genitalia.', 'B', 'Sebaceous carcinoma is a rare malignancy that typically affects the eyelids.
Around 25% of the cases can be extra-ocular.
Sebaceous carcinoma is the fourth most common eyelid malignancy after basal cell carcinoma, squamous cell carcinoma and melanoma.
Sebaceous carcinomas can metastasise and these tumours should be treated adequately through surgical excision.
The presence of sebaceous carcinoma (in addition to sebaceoma and/or sebaceous adenoma) raises a suspicion of the presence of Muir-Torre syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (448, 14, 'All of the following conditions can increase the risk of developing basal cell carcinomas in children except:', 'Albinism.', 'Giant congenital naevus.', 'Gorlin''s syndrome.', 'Naevus sebaceous.', 'Xeroderma pigmentosum.', 'B', 'There is an increased risk for the development of melanoma arising from giant con genital naevi and not basal cell carcinomas.
All other conditions have an increased risk of developing basal cell carcinomas.
The commonest benign tumour which arises from the naevus sebaceous is syringocystoadenomapapilliferum.
Patients with Gorlin''s syndrome are known to develop multiple basal cell carcinomas from an early age.
Patients with xeroderma pigmentosum are at increased risk of developing skin cancers including squamous cell carcinoma and melanoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (449, 14, 'Which of the following markers is a sensitive marker for Merkel cell carcinoma?', 'CD1a.', 'CD34.', 'CK20.', 'Factor XIIIa.', 'S100.', 'C', 'Merkel cell carcinoma is a rare neuro-endocrine cutaneous malignancy that may arise in transplant patients.
Recently a virus has been implicated as a possible factor in the development of Merkel cell carcinoma called polyoma virus.
CK20 is a very sensitive marker for Merkel cell carcinoma.
CD34 and Factor XIIIa are helpful to distinguish between dermatofibroma and dematofibrosarcoma protuberans.
CD1a and S100 are helpful to differentiate between Langerhan''s cells and melanocytes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (450, 14, 'A 36-year-old man has had a changing mole on his back removed. This was reported histologically to be a superficial spreading melanoma, Breslow thickness of 3.4 mm with no ulceration.Sentinel node biopsy did not show any evidence of positive lymph nodes and there were no systemic features to suggest distant metastases. The pathological staging of this tumour is:', 'lb.', 'Ila.', 'IIb.', 'Lie.', 'IV.', 'B', 'Stage Ila is Breslow thickness 1.01-2 mm with ulceration or a Breslow thickness be tween 2.01-4 mm without ulceration in the absence of clinical, radiographic or histological evidence of lymph node involvement.
Stage lb is Breslow thick,,ess less than 1 mm but with ulceration or mitoses equal to or more than 1 per mm2.
Stage IV is presence of distant metastases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (451, 14, 'A 50-year-old man presented with non-tender papules and nodules with no surface changes on the back. He had recently been complaining of night sweats and weight loss. Histology of the lesion showed a dense dermal infiltrate which stained negative for CD3, CD20, CD79a, bcl-2, bcl-6, CD4, CD30 and CDS and was positive for CD43 and myeloperoxidase. What is the most likely diagnosis?', 'Anaplastic large cell lymphoma.', 'Follicle centre B cell lymphoma.', 'Leukaemia cutis.', 'Marginal zone B cell lymphoma.', 'Mycosis fungoides.', 'C', 'The negative staining to the T-cell markers CD3, CD4 and CDSrules out mycosis fungoides.
The negative staining to the B-cell markers CD20 and CD79a rules out cutaneous 8 cell lymphomas.
CD43 positivity is a clue for myeloid leukaemia (leukaemia cutis in this case) in the absence of positivity to Band T cell markers.
Myeloid leukaemia also stains positive to myeloperoxidase.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (452, 14, 'You remove a suspicious mole on the shoulder of a young woman who had excessive sun exposure. The result showed a superficial spreading melanoma with a Breslow thickness of 0.7 mm with no mitoses or ulceration. You arrange for urgent action but the patient informs you that she is now 8 weeks pregnant. Which of the followihg actions should take place?', 'Defer any further intervention until after delivery of the baby.', 'Recommend radiotherapy only.', 'Wide local excision with 1 cm margin.', 'Wide local excision with 2 cm margin.', 'Wide local excision with 5 mm.', 'C', 'Whilst It is good practice to defer most non-urgent and benign lesions removal till after delivery, pregnancy should not be a contra-indication for a wide local excision of a melanoma.
Melanoma is not very radiosensitive however adjunctive radiotherapy may be i.;sed post positive sentinel lymph node lymphadenectomy particularly if th II? was extra-capsular spread of the tumour or more than 3 lymph nodes were involved.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (453, 14, 'You see a 61-year-old Australian man with a 3 cm ulcerated nodule below his left eye that has been growing over the last 5 months. On further examination the nodule appears tethered and attached the underlying:,tructures. A biopsy performed a week earlier showed a poorly-differentiated squamous cell carcinoma. What should be the next action?', 'Arrange imaging.', 'Repeat the biopsy.', 'Refer for radiotherapy.', 'Surgical excision with a margin of 1 cm.', 'Surgical excision with amargin of 6 mm.', 'A', 'In cases of skin tumours which are large and/or tethered and attached to underlying structures imaging should be arranged to assess for local invasion.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (454, 14, 'You are looking after a patient with cutaneous T-cell lymphoma. At what stage of their disease would you consider introducing Bexarotene?', 'Stage 3 or above.', 'Stage 2a or above.', 'Stage lb or above.', 'Stage 2b or above.', 'Stage 4.', 'D', 'Bexarotene is a retinoid receptor agonist.
It is often combined,..,.ith other therapies such as PUVA or extrariorporeal photopheresis.
Side effects include hypothyroidism and dyslipidaemia, requiring regular monitoring of thyroid function and lipids.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (455, 14, 'Which of the following statements regarding Vismodegib is true?', 'It inhibits the hedgehog receptor and Its most common side effect is muscle cramps.', 'It inhibits the smoothened receptor and its most common side effect is nausea.', 'It inhibits the smoothened receptor and its most common side effect is muscle cramps.', 'It inhibits the hedgehog receptor and its most common side effect is nausea.', 'Ncne of the above.', 'C', 'Vismodegib inhibits the smoothened receptor, a key mediator in the Hedgehog signalling pathway.
Other commonly-seen side-effects include altered taste sensation anorexia, diarrhoea, fatigue and alopecia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (456, 14, 'Which HPV serotype is most commonly associated with subungual squamous cell carcinoma?', 'HPV 16.', 'HPV 18.', 'HPV 26.', 'HPV 31.', 'HPV 56.', 'A', 'Periungual skin is the most common extr2-genital site for cutaneous squamous cell carcinoma.
Subungal squamous cell carcinoma is commonly a diagnostic challenge, presenting with a variety of nail changes including verruciform hyperkeratosis, dystrophy, longitudinal ridging, onycholysis, erythronychia, subungal haematomas and paronychia.
Whilst all subtypes listed are high-risk for subungal squamous cell carcinoma, the most important carcinogenic factor is HPV 16.
Longitudinal nail biopsy is the gold standard diagnostic approach as this allows sampling of the nail bed. matrix and fold.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (457, 14, 'What is the second most common site for melanoma in British Caucasian men?', 'Upper limbs.', 'Trunk.', 'Head and neck.', 'Lower limbs.', 'Acral sites.', 'C', 'As reported by the Statistical Information Team at Cancer Research UK, the commonest site for melanoma in men is the trunk (accounting for 41% of cases), followed by the head and neck (22%) and arms (19%).
For women, the commonest s;te is the legs (39%), followed by the arms (24%) and trunk (20%).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (458, 14, 'A 14-year-old boy with red hair and freckled skin is referred by hisGP due to concern regarding a number of atypical moles. On taking a family history you establishthat his father, older sister and paternal uncle, all of a similar complexion, had malignant melanoma before the age of 40. Mutation in which gene is most likely to underlie the strong family history of malignant melanoma?', 'CDKN2A.', '8-RAF.', 'BRACA.', 'PTEN.', 'MClR.', 'A', 'Hereditary or familial melanoma is currently estimated to account for approximately 10% of all cases of melanoma.
It is defined by families in which at least 2 first-degree relatives (or alternatively at least 3 members with any degree of relationship) have had melanoma.
Germ-line mutation in the CDKN2A gene, a regulator of celldivision, is the most common cause of hereditary melanoma.
The lifetime risk for malignant melanoma In someone carrying a CDKN2A gene mutation is nearly 30%.
Other heritable mutations that carry an increased risk of malignant melanoma include CDK4, RBl, MDm2TYR, TYRPl, ASIP and MClR genes.
The MClR gene encodes the melanocortin-1 receptor. This promotes eumelanin production, thereby controlling the ratio of eumelanin and pheomelanin. Polymorphisms that reduce the ability of the melanocortin-1 receptor result in melanocytes making mostly pheomelanin. These are associated with red hair, fair skin and freckles. Whilst such polymorphisms are associated with increased risk of melanoma and non-melanoma skin cancers, the relative risk is much smaller.
Non-inherited or somatic gane mutations that increase the risk of melanoma include those in NRAS, B-RAF and C-KIT. Interestingly, NRAS mutations are more frequent in mucosal melanomas in the head and neck region, in comparison to 8-RAF and C-KIT.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (459, 14, 'A 31-year-old woman has BRAF-positive stage 4 malignant melanomc1. Which of the following treatments offers her the best prognosis?', 'Vemurafenib - IV.', 'Ipilimumab - orally.', 'Vemurafenib - orally.', 'Rituximab - IV.', 'Ipilimumab - IV.', 'C', 'Vemurafenib is a small molecule inhibitor of the B-RAF enzyme.
Delivery is via the oral route.
ipilumumab would be first line for BRAF-negative disease.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (460, 14, 'A 53-year man has BRAF-negative stage 4 malignant melanoma. Which of the following treatments would afford him the best prognosis?', 'Ipilimumab - orally.', 'Ipilimumab - IV.', 'Vemurafenib - IV.', 'Vemurafenib - orally.', 'Rituximab - IV.', 'B', 'ipilimumab is monoclonI antibody that up-regulates immune-surveillanceby targeting CTLA-4 (an inhibitory protein on cytotoxic T cells)
Delivery is via the intravenous route
Vemurafenib would not be indicated for BRAF-negative disease');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (461, 14, 'A 31-year-old woman is to start ipilimumab for BRAf-negative stage 4 malignant melanoma. What is the most common complicating autoimmune reaction seen with this monoclonal antibody?', 'Pneumonitis.', 'Dermatitis.', 'Uveitis.', 'Hepatitis.', 'Colitis.', 'E', 'CTLA-4 inhibition can trigger numerous autoi-mmune phenomena
The most common of these is autoimmune colitis, manifesting with such symptoms as abdominal pain and bloody diarrhoea');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (462, 14, 'A patient with stage 4 melanoma presents with her second squamous cell carcinoma since starting a new medication. Which of the following therapies is she most likely to be receiving?', 'Dacarbazine.', 'Ipilimumab.', 'Interferon.', 'Dabrafenib.', 'Radiotherapy.', 'D', 'Dabrafenib and Vemurafenib are B-RAF enzyme inhibitors.
Their most common side effects concern photosensitivity, other skin eruptions and flu-like symptoms.
Approximately 25% of patients develop skin cancers, espe::ially squamous cell carcinoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (463, 14, 'A 40-year-old woman presented with longstanding translucent yellow, small papules appearing predominantly on her peri-orbital skin. Clinically, you make the diagnosis of syringomas. Which of the following statements is incorrect?', 'Carbon dioxide laser can be used for treating thiscondition.', 'Electron microscopy studies have identified deposits of calcium.', 'The eruptive forms can be associated with Ehlers-Danlos syndrome.', 'These lesions arise from the intradermal portions of the eccrine sweat ducts.', 'These lesions arise from the outer hair root sheath.', 'E', 'Tricholemmomal cysts arise from the outer hair root sheath.
Typically, the histology is of dermal tumours comprising of smali ducts of cuboidal cells with moderately eosinophilic cytoplasmic cords set in a fibrous s·troma creating a comma-shaped appearance.
The eruptive forms of syringomas have also been linked with Marfan''s and Down''s syndromes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (464, 14, 'Which of the following statements regarding dermatofibrosarcoma protuberans is correct?', 'Chromosomal abnormality, which can be present in this condition, is EWS- Fll1.', 'Erlotinib can be used in some cases.', 'Metastases are extremely common in this condition.', 'Positive CD34 with negative Factor XIIIa.', 'This condition is characterised immunohistochemically by CD34 negative and Factor XIIIa positive.', 'D', 'Dermatofibrosarcoma protuberans is a spindle cell tumour with its main differential being dermatofibroma.
Dermatofibromas are classically Factor XIIIa positive and CD34 negative (the reverse is true for dermatofibrosarcoma protuberans).
Chromosomal abnormalities may occur due to translocation of chromosomes 17 and 22, leading to over-ei-pression of platelet-derived growth factor receptor and treatment with imatinib, (particularly if unresectable, recurrent and metastatic), can be used in this condition.
Erlotinib is an epidermal growth factor receptor antagonist and can be used in certain cases of solid tumours.
Dermatofibrosarcoma protuberans can metastasise in about 10 - 15% of cases and surgical excision is the first line treatment of choice (Mohs mlcrographic surgery when available).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (465, 14, 'A 57-year-old Caucasian woman presented with anine month history of a5 x 5 cm solitary erythematous plaque with overlying telangiectasia on her right shoulder. She did not have any associated pruritus or lymphadenopathy. An incisional biopsy from the plaque showed diffuse dermal subcutaneous lymphocytic infiltrate that spared the epidermis and the cells were positive for CD20, bcl-2 and negative for CD3, CDS, CD10 and bcl-6. The most likely diagnosis here is:', 'Mycosis fungoides.', 'Non-Hodgkin lymphoma skin metastases.', 'Primary cutaneous B-cell lymphoma of diffuse large cell lymphoma type.', 'Primary cutaneous B-cell lymphoma of marginal zone type.', 'Primary cutaneous B-cell lymphoma of the follicle centre type.', 'D', 'Cutaneous lymphomas are divided into T and B-cell lymphomas.
B-cell lymphomas are sub-divided into diffuse large cell B-lymphoma leg type, marginal B-cell lymphoma and follicle centre.
Marginal zone lymphomas are characterised by positivity to bcl-2 and negativity for bcl-6.
Follicle centre B-cell lymphomas are characterised by positivity to bcl-6 with negativity to bcl-2.
CD20 and CD79a are both markers of B-cells.
B-cell lymphomas, unlike T-cefl lymphomas, do not exhibit epiderrnotroplsm except in rare occasions.
Mycosis fungoides is the commonest type of cutaneous T cell lymphoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (466, 14, 'Which of the following drugs may result in resolution of actinic keratoses?', 'Capecitabine.', 'Hydroxychloroquine.', 'Hydroxyurea.', 'Ramipril.', 'Tacrolimus.', 'A', 'Capecitabine is a chemotherapy agent, which is used in the treatment of certain solid tumours.
Capecitabine is a pro-drug of 5-Fluorouracil (5-FU), which is well known to be effective in the treatment of actinic keratosis in its topical form efudlx cream.
Hydroxyurea has been reported to induce squamous cell carcinomas in some cases.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (467, 14, 'A 54-year-old man presents with a squamous cell carcinoma. Which of the following is not a risk factor for non-melanoma skin cancers?', 'Actinic keratoses.', 'Exposure to arsenic.', 'Fair skin colour.', 'Hodgkin''s lymphoma.', 'Light hair colour.', 'D', 'The risk of development of non-melanoma skin cancer depends on genotypic, phenotypic, and environmental factors.
The risk is the greatest in residents of high ambient solar irradiance who have markers of ultraviolet (UV) susceptibility, such as light skin, eye, and hair colour, or an inability to tan, and those with benign sun-related skin disorders-e.g., actinic keratoses and solar lentigines.
The following are risk factors for non melanoma skin cancers: Solar UV radiation, human papillomavirus, iatrogenic immunosuppression, HIV/AIDS and non-Hodgkin lymphoma, PUVA therapy, photosensitising drugs, UVB radiation, ionising radiation, occupational factors, arsenic and tobacco smoking.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (468, 14, 'A 35-year-old patient with naevoid basal-cell carcinoma svndrome presents with a cluster of basal cell carcinomas on the back. Which of the following treatments is contra-indicated in the treatment of these basal cell carcinomas?', 'Carbon dioxide laser ablation.', 'Curettage.', 'Photodynamic therapy.', 'Radiotherapy.', 'Topical imiquimod.', 'D', 'Patients withnaevoid basal-cell carcinoma syndrome have increased sensitivity to radiation and a tendency to develop several basal-cell carcinomas in the irradiated field; radiotherapy is therefore contra-indicated in these patients.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (469, 14, 'A 40-year-old man has had two sebaceous carcinomas excised within the last 5 years and reports that both his father and sister have had several sebaceous carcinomas and sebaceous adenomas excised. The most common malignancy associated with this disorder is:', 'Brair. tumour.', 'Breast cancer.', 'Colorectal cancer.', 'Melanoma.', 'Squamous cell carcinoma.', 'C', 'Muir-Torre syndrome is an autosomal dominant syndrome where patients develop sebaceous adenomas or carcinomas and this is associated with internil malignancies with colorectal cancers accounting for nearly half of all the tumours.
Genito-urinary, breast and lung cancers can also occur with this disease.
Sebaceous hyperplasia is not associated with Muir-Torre syndrome.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (470, 14, 'A 60-year-old man who is on warfarin for metallic aortic valve replacement presents with a 1.5cm nodular basal cell carcinoma on the dorsal aspect of his hand. He is very reluctant to have this treated surgically and wishes for alternative treatment. You discuss the option of radiotherapy and have decided to refer him to the radiotherapist. Which mode of radiotherapy is used for the treatment of basal cell carcinoma7', 'Brachytherapy.', 'Gamma X-ray.', 'Photodynamic therapy.', 'Superficial x-ray.', 'None of the options.', 'D', 'Radiotherapy can be used for basal cell and squamous cell carcinomas if there are contra-indications for surgery.
Superficial x-ray is the treatment of choice in basal cell carcinoma with the use of high dose radical radiation.
Brachytherapy is a method used where an implant is placed followed by high dose radiation. This is often used for Kaposi''s sarcoma.
Photodynamic therapy can be used for superficial basal cell carcinomas but not those 0f the nodular type.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (471, 14, 'A patient presents with nail pigmentation. There is no history of trauma. Which of the following features in a nail would make the diagnosis of acral melanoma more likely than longitudinal melanonychia?', 'Accompanying nail dystrophy.', 'Clear distinct margins.', 'Presence in childhood.', 'The involvement of multiple digits.', 'Uniform in colour.', 'A', 'Digital or acral melanoma can be tricky to diagnose and any suspicious pigmented streak in a nail should be biopsied to exclude this diagnosis.
Longitudinal melanonychia is its main differential and often presents with multiple digital involvement, skin type V/VI, narrow bands with clear margins, uniform colour, and presence since childhood or puberty.
Accompanying nail dystrophy is not a feature in benign melanonychia and should alert the dermatologist to the possible diagnosis of melanoma.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (472, 14, 'A 37-year-old man with background of HIV infection presented with a 3-month history of asymptomatic purple-coloured plaques on the lower legs which have failed to respond to topical therapy given by his GP. Biopsy showed a vascular lesion and further immunostaining confirmed the endothelial nature of the lesion. Which of the following is implicated in the pathogenesis of this disease?', 'Human Herpes Virus 2.', 'Human Herpes Virus 4.', 'Human Herpes Virus 5.', 'Human Herpes Virus 6.', 'Human Herpes Virus 8.', 'E', 'The diagnosis here is Kaposi''s sarcoma which is an angioproliferative tumour arising from endothelial cells.
Human Herpes Virus (HHV) 8 is Implicated in the pathogenesis.
Kaposi''s sarcoma has 4 forms: classic, endemic (African), iatrogenic (secondary to immunosuppressive therapy) and AIDS-related.
HHV 8 is also implicated in the pathogenesis of Castleman''s disease.
HHV 2 is HSV-2 subtype, HHV 4 is Epstein-Barr virus, and HHV 6 is implicated in the pathogenesis of roseola infantum.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (473, 14, 'A 76-vear old man presnnted with a 6-month history of a slowly growing plaque on the forehead. Examination showed a purplil;h plaque mimicking a bruise with some vascular-looking papules. A biopsy showed a tumour arising from the vascular bed with marked atypia and mitoses. The most likely diagnosis is:', 'Angiosarcoma.', 'Basal cell carcinoma.', 'Haemangioma.', 'Kaposi''s sarcoma.', 'Spitz naevus.', 'A', 'Angiosarcoma is an aggressive vascular tumour with high recurrence rate and potential for metastasis to the lung, liver and brain.
The 3 clinical settings of angiosarcoma are: (i) in the elderly (predominantly head and neck), (ii) at sites of lymphoedema, and (iii) radiotherapy-related.
Kaposi''s sarcoma is in the differential but there is no atypia and the tumour arises from both the endothelial and spindle cells and unlike angiosarcoma, shows positivity for HHV 8.');

-- Skin Surgery & Cosmetic Dermatology
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (474, 15, 'A patient with a metallic mitral valve attends the dermatological surge,-y department for an excision of a small nodular basal cell carcinoma on his chest. What should be the most appropriate action with regards to antibiotic prophylaxis for his metallic valve?', 'A one-week course of penicillin after the procedure.', 'No antibiotic prophylaxis is required.', 'Penicillin and metronidazole single doses should be given.', 'Referral to a cardiothoracic surgeon.', 'Single penicillin dose one hour prior to the procedure.', 'B', 'The current consensus is that dermatological surgical procedures confer a low risk for endocarditis, and therefore, no prophylactic antibiotics are required.
An assessment should however, still take place based on individual circumstances.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (475, 15, 'A 30-year-old patient with polycystic ovarian syndrome was referred for laser treatment of facial hirsutism. The following hair-skin combination is considered best for laser treatment:', 'Skin phototype 2 - dark terminal hair.', 'Skin phototype 2 - Ginger hair.', 'Skin phototype 3 - dark terminal hair.', 'Skin phototype 5 - brown hair.', 'Skin phototype 6 - grey hair.', 'A', 'Skin phototype 2 - dark terminal hair is considered the best combination for successful laser hair removal with the currently available lasers and light devices including intense pulsed light, long pulsed Nd:YAG, diode and Alexandrite lasers.
This combination results in best clinical outcomes with least side effects.
Skin phototype 1 patients rarely have dark terminal hairs.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (476, 15, 'A 30-year-old patient with polycystic ovarian syndrome was referred for laser treatment of facial hirsutism. She is currently using topical eflornithine cream. Your advice, based on current recommendation is:', 'Continue treatment with eflornithine cream.', 'Continue treatment with eflornithine cream, but stop for few days after laser treatment.', 'Stop eflornithine cream for 3 months prior to laser treatment.', 'Stop eflornithine cream for 6 months prior to laser treatment.', 'Stop eflornithine cream for 12 months prior to laser treatment.', 'A', 'Av.:1ilable evidence suggests that addition of eflornithine to laser treatment results in a more rapid and complete reduction of unwanted facial hair in women when the combination is used for up to 6 months.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (477, 15, 'A 45-year-old woman wants treatment of her tattoo. Which laser would be the most appropriate for the treatment of her red professional tattoo?', 'Long pulsed Nd:YAGlaser.', 'Q-switched 1064 nm Nd:YAG laser.', 'Q-switched 532 nm Nd:YAG laser.', 'Q-switched 755 nm laser.', 'Q-switched Ruby laser.', 'C', 'QS Nd:YAG (532 nm) emits green light and is the treatment of chioce for red tattoos.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (478, 15, 'A 25-year-old woman has facial pigmentation, which has been formally diagnosed as melasma. Which of the following is the recommended laser treatment for melasma?', 'Q-switched 1064 nm Nd:YAG laser.', 'Q-switched 532 nm Nd:YAG laser.', 'Q-switched 755 nm laser.', 'a-switched Ruby laser.', 'None.', 'E', 'Treatment of melasma with pigment specific lasers is disappointing and as such i.s not recommended.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (479, 15, 'Which of the following types of botulinum toxin is most commonly used in the treatment of hyperkinetic facial lines?', 'Type A', 'Type B', 'Type D', 'Type E', 'Type F', 'A', 'Tliere are seven distinct serotypes of botulinum toxin: A, B, Cl, D, E, F and G.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (480, 15, 'A 40-year-old woman attends for botulinum toxin injection to treat glabellar lines. Which of the following concurrent treatment would not be considered a contra-indication for botulinum toxin injection?', 'Aminogiycosides.', 'Calcium channel blockers.', 'Diogoxin.', 'Penicillamine.', 'Quinine.', 'E', 'The listed drugs can potentiate the action of botox, which should be avoided if the patient is on any of these medications.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (481, 15, 'A GO-year old patient is interested in treatment of his deep glabellar lines. Which of the following is considered the safest in the treatment of deep glabellar lines?', 'Autologous fat injection.', 'Bovine collagen injection.', 'Calcium hydroxylapatite.', 'Hyaluronic acid injection.', 'Silicone injection.', 'E', 'Local skin necrosis has been reported following deep glabellar injection of bovine collagen induced vascular occlusion.
Loss of vision due to arterial embolization has been reported with both bovine collagen and alltologous fat injected into the glabellar region.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (482, 15, 'Which of the following chemical peels is associated with a risk of cardiac toxicity?', 'Glycolic acid.', 'Phenol.', 'Pyruvic acid.', 'Resorcinol.', 'Trichloroacetic acid.', 'B', 'Cardiac arrhythmias and laryngeal oedema have been reported with phenoi peels. Precautions recommended at the time of phenol peels inc.lude appropriate analgesia, adequate hydration, and availability of cardiac monitoring and resusc.itation Equipment.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (483, 15, 'A 56-year-old, normally fit and well, man presented with a 2 cmtelangiectatic pearly lesion on the forehead but with rather indistinctive scar-like margin. What would be the most appropriate therapeutic intervention?', 'Cryotherapy.', 'Imiquimod.', 'Mohs'' micrographic surgery.', 'Photodynamlc therapy.', 'Simple excision with a 4 mm margin.', 'C', 'This is a morphoeic basal cell carcinoma and therefore Mohs'' micrographit surgery is the most appropriate intervention.
Other indications for this type of surgery include recurrent basal cell carcinomas, large tumours (size > 2 cm), aggressive histology (metaplastic, infiltrative, morphoeic and micro-nodular) and high-risk sites (forehead and around the eyes, nose and ears).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (484, 15, 'A 3-year-old girl is referred to paediatric dermatology with a vascular malformation on the left side of the face. She is under the care of the neurologists for epilepsy. The condition is diagnosed as Sturge-Weber syndrome. Which of the following lasers will be most appropriate for treating this vascular deformity?', 'Carbon dioxide laser.', 'KTPlase', 'Nd:YAG laser.', 'Pulsed dye laser.', 'Ruby laser.', 'D', 'Pulsed dye laser (PDL) was the first vascular specific laser used for the treatment of port-wine stains.
It is still the gold standard for the treatment of port-wine stains.
The chromophore for 585 nm and 595 nm wavelengths (PDL) is haemoglobin.
The selective heating of haemoglobin by these wavelengths results in destructlcn of the aberrant vessels.
Deeper vascular malformations may respond to the Nd:YAG laser.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (485, 15, 'A 70-year-old woman presents with bluish-grey pigmentation on the forehead. She had been on long-term minocycline for bullous pemphigoid She is seeking your advice on laser treatment. Which of the following lasers is likely to be effective in the treatment of her forehead pigmentation?', 'Carbon dioxide.', 'Copper vapour.', 'KTP.', 'Pulsed dye laser.', 'Qswitched Nd:YAG.', 'E', 'Minocycline pigmentation would resolve without active intervention and adequate sun protection.
The Q-switched lasers (Nd:YAG, Alexandrite and Ruby)111 be effective in lightening the pigmentation.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (486, 15, 'In which of the following conditions would you institute prophylactic antibiotics prior to dermatological surgery procedures on a contaminated wound?', 'All procedures.', 'Congenital heart disease.', 'Prior history of infective endocarditis.', 'Prosthetic heart valve.', 'Prosthetic joint in immunosuppressed patients.', 'A', 'Antibiotic prophylaxis for dermatologic surgery is indicated for:
High risk cardiac conditions:
Prosthetic cardiac valve or prosthetic material used for valve repair.
Prior infective endocarditis.
Cardiac transplant recipients who develop valvulopathy.
Congenital heart disease.
High risk prosthetic joint indications:
First 2 years post joint replacement.
immunosuppressed patients.
Malnourishment, malignancy, haemophilia, type 1 diabetes.
Prophylaxis is not indicated for simple biopsies, curettage or excision. It is, however, indicated for procedures, especially Mohs'' surgery, ar,d when reconstruction lasts >20 minutes and when the wound is contaminated or infected.
132');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (487, 15, 'You are going to operate on a very anxious patient. All the following help to reduce pain from local anaesthetic injections except:', 'Buffered solution.', 'Finer needle.', 'Pinching the skin before injecting.', 'Superficial injections.', 'Warm solution.', 'D', 'Beside the above the following tips help to decrease pain with local anaesthetic injections:
Topical anaesthetic.
Buffer with sodium bicarbonate.
l''lject slowly through a dilated pore or wound edge.
Deeper injections into subcutaneous area.
Minimal needle punctures.
Consider ringblocks.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (488, 15, 'Which of the following is not an amide anaesthetic?', 'Bupivacaine.', 'Lignocaine.', 'Mepivacaine.', 'Prilocaine.', 'Procaine.', 'E', 'Procaine, chloroprocaine and tetracaine are Ester anaesthetics.
Lignocaine, mepivacaine, prilocaine and bupivacaine are Amide anaesthetics.
Amide anaesthetics are more commonly used in skin surgery and can easily be remembered as they contain the letter "I".');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (489, 15, 'A 35-year-old woman presents with ptosis of her left upper eyelid 4 days following botulinum toxin injections for forehead wrinkles. What is the best treatment?', 'Aproclonidine.', 'Clonidine.', 'Doxazocin.', 'Glutaraldehyde.', 'Propranolol.', 'A', 'Apraclonidine eye drops (alpha 2 adrenergic agonist) are used to reverse the ptosis induced by botulinum toxin injections.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (490, 15, 'Which of the following nerves is not a branch of the trigeminal nerve?', 'Infratrochlear.', 'Lacrimal.', 'Marginal mandibular.', 'Supraorbital.', 'Supratrochlear.', 'C', 'Marginal mandibular is a branch of the facial nerve, which is a motor nerve.
The trigeminal nerve is a sensory nerve.
All the above branches of the trigeminal nerve supply the eyelids and skin around the eyes.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (491, 15, 'The sensory innervation of the vertex of the scalp is predominantly by which nerve?', 'Auriculotemporal.', 'Lesser occipital.', 'Supra-orbital.', 'Supra-trochlear.', 'Zygomaticotemporal.', 'C', 'Th supra-trochlear nerve innervates part of the frontal scalp.
The auriculotemporal nerve innervates the parietal part and the lesser occipital parieto-occipital part of the scalp behind the ear. PQ.2');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (492, 15, 'Which of the following nerves is not a branch of the ophthalmic division of trigeminal (Vl.) nerve?', 'Infra-orbital nerve.', 'Infra-trochlear nerve.', 'Lacrimal nerve.', 'Supra-orbital nerve.', 'Supra-trochlear nerve.', 'A', 'The infra-orbital nerve is a branch of the maxillary branch (V2) of the trigeminal nerve.
Other branches of the maxillary branch (V2) include the zygomaticofaclal and zvgomaticotemporal nerves.
The external nasal nerve 1s a branch of the ophthalmic division of trigeminal (Vl) nerve.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (493, 15, 'You remove a tumour from the right nasal ala and decide to reconstruct the defect with a full thickness skin graft. One of the following factors does not reduce the survival of the graft:', 'Cartilage at the base of the defect.', 'Donor site from sun-exposed skin.', 'Poorly controlled diabetes mellitus.', 'Smoking.', 'The presence of a fat layer at the base of the graft.', 'B', 'Full thickness skin graft can be used as a method of reconstruction for certain defects particularly on the nasal alae, ears, lower eyelids and temple.
Several factors cari influence the survival Clf the graft tissue and it is important to be aware of these.
Donor sites skin should match the skin colour and texture of the recipient site and are is often harvested from the pre-or post-auricular or sites or from the supra-clavicular area.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (494, 15, 'A tumour was removed from theconchal bowl. This defect measures 10x8 mm and is fairly superficial with intact periosteum. Which of the following reconstructive options is the most suitable in thiscase:', 'Bilobed transposition flap.', 'Paramedian forehead flap.', 'Primary closure.', 'Rhombic transposition flap.', 'Secondary intention healing.', 'E', 'Secondary intention healing can be a suitable option particularly in the conchal bowl, medial canthus, scalp, forehead and the dorsum of the hands and feet.
As the wound heals a degree of contraction will occur and it is essential to monitor that the contraction force does not result in an unwanted pull on a free margin such as the eyebrow or nasal ala.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (495, 15, 'Which of the following is an ablative laser?', 'Alexandrite.', 'Erbium YAG.', 'Intense pulsed light (IPL).', 'Pulsed dye.', 'Q-switched Nd:YAG 532 nm.', 'B', 'Ablation is simply the removal of tissue and in the cases of laser ablation is due to vaporization of the tissue.
Other ablative laser modality is carbon dioxide laser.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (496, 15, 'Which of the following is the most commonly observed side effect of pulsed dye laser treatment?', 'Blistering.', 'Bruising.', 'Dyschromia.', 'Herpes simplex reactivation.', 'Keloid scarring.', 'B', 'Bruising may last up to 2 weeks if a purpuric mode has been used.
In some instances, if a non-purpuric mode (often with longer pulse duration and lower fluence) is used, results may take require several more treatments to achieve a similar outcomes as to the purpuric mode.
All other side-effects mentioned in the answers are possible, but are less frequent.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (497, 15, 'Which of the following isa sensory nerve?', 'Buccal nerve.', 'Cervical nerve.', 'Marginal mandibular nerve.', 'Temporal nerve.', 'Zygomaticofacial nerve.', 'E', 'All facial sensory nerves are branches of the trigeminal nerve.
The motor nerves of the face are branches of the facial nerve and are the tempo.al, zygomatic, buccal, marginal mandibular, and cervical nerves.
In facial skin surgery the Z danger zones t:1at every dermatologist should be ciware of are the anatomic location of both the temporal and marginal mandibuiar nerves.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (498, 15, 'How does the novel oral anticoagulant dabigatran work?', 'Inhibition of activated vitamin K synthesis.', 'Inhibition of factor Xa.', 'Inhibition of thrombin (factor Ila).', 'Activation of antithrombin III.', 'None of the above.', 'C', 'Unlike warfarin, novel oral anticoagulants act independently of the vitamin K pathway and, because of shorter half-lives and more predictable pharmacokinetics, do not require routine therapeutic monitoring
Answer B is true for the novel oral anticoagulants rivaroxiban and apixaban
Answer A is true for warfarin
Answer D is true for heparin');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (499, 15, 'Which of the following absorbable and non-absorbable suture combinations will minimise the suture reaction and scarring·?', 'PDS (polydioxanone) and Ethilon.', 'Monocryl and Ethilon.', 'Vicryl and Prolene.', 'Monocryl and Prolene.', 'PDS (polydioxanone) and Prolene.', 'D', 'PDS (polydioxanone) eliclt3 the greatest scar reaction amongst the absorbable sutures listed and Monocryl the least.
Ethllon elicits a greater scar reaction than Prolene.
The extent of the scar reaction can also be reduced by using a smaller calibre suture anC: avoiding delayed suture removal.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (500, 15, 'What is the protein target of local anaesthetics?', 'Sodium channels.', 'Calcium channels.', 'Gap junctions.', 'Potassium channels.', 'Chloride channels.', 'A', 'Local anaesthetics comprise a lipophilic aromatic region attached to a basic amine side chain. For aminoesters this is via an ester link and for aminoamides this is via amide link.
Local anaesthetics block propagation of action potentials of sensory neurons by use-dependent inhibition of voltage-gated Na receptors, binding to a site within the open pore.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (501, 15, 'Following surgery for excision of a basal cell carcinoma, an 85-year-old patient presents with asymmetrical smile. Injury to the following nerve is most likely:', 'Buccal nerve.', 'Marginal mandibular nerve.', 'Maxillary nerve.', 'Spinal accessory nerve.', 'Temporal nerve.', 'B', 'The marginal mandibular nerve lies along the body of the mandible-(80%) or within 1-2 cm below (20%). Although it lies deep to the platysma throughout much of its course it becomes more superficial approximately 2 cm lateral to the corner of the mouth and ends on the under surface of the muscles.
Injury to the marginal mandibular nerve results in paralysis of the depressors of the corner of the mouth.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (502, 15, 'A 35-year-old woman has residual telangiectasiae and erythema following i;uccessful treatment of the papulo-pustular element of rosacea wi h iymecycline. She is keen for treatment of her facial telangiectasiae and erythema. Which of the following is the best treatment?', 'Erbium: Glass laser.', 'Erbium: YAG laser.', 'Fractional lasers.', 'Pulsed dye laser.', 'Qswitched Nd:YAG laser.', 'D', 'Pulsed dye laser at 595nm is the treatment of choice for most vascular lesions. An other laser that is commonly used for the treatment of telangiectasiae is the KTP laser (frequency doubled, Nd:YAG laser).');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (503, 15, 'A 55-year-old lady is undergoing excision of an atypical naevus on her shoulder. You are about to inject 2%llgnocaine with adrenaline. Contra-indication for this anaesthetic would include?', 'Aspirin.', 'Codeine.', 'Paracetamol.', 'Propranolol.', 'Warfarm.', 'D', 'Anaesthetic solutions containing adrenaline should not be used if patients are taking non-selective beta-blockers, such as propranolol.
In these situations plain lignocaine should be used instead.
A risk of developing a hypotensive crisis is small, nevertheless it is considered good and safe practice to enquire about medications; in particular, for propranolol.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (504, 15, 'Q-Switched <1lexandrite laser is reported to be useful for removal of green tattoos. The wave length of Q-Switched alexandrite laser is:', '404 nm.', '694 nm.', '755 nm.', '2940 nm.', '10600 nm.', 'C', 'Q-Switched Ruby laser has a wave length of 694 nm whilst Erbium YAG has a wave length of 2940 nm.
CO2 laser has a wavelength the far infrared region of 10600 nm.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (505, 15, 'The maximum adult dose for plain lignocaine as a local anaesthetic is:', '3mg/kg.', 'Smg/kg.', '7mg/kg.', '10 mg/kg.', '20mg/kg.', 'A', 'Lignocaine is widely used as a local anaesthetic In dermatology and the maximum safe volumes need to be known.
For plain lignocaine, the maximum safe adult does is 3mg/kg, however this is 7mg/kg when mixed with adrenaline. This is based on 1% lignocaine concentration.
Symptoms of lignocainE:toxicity include drowsiness, tingling, numbness of the lips, tinnitus and a metallic taste.
In severe toxicity, convulsions and respiratory arrest can occur.
1 ml of 1% lignocaine contains 10 mg of lignocaine.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (506, 15, 'The least painful local anaesthetic is:', '0.5% plain lignocaine.', '1% lignocaine combined with adrenaline.', '1% plain lignocaine.', '2% lignocaine combined with adrenaline.', 'Bupivacaine 0.75%.', 'A', 'o.s% plain lignocaine is the least painful of the local anaesthetics; however, its action may be too short for complicated procedures.
1% lignocaine combined with adrenaline has a longer action; larger amounts are required for reaching the maximum safe volume compared to 2% lignocaine with adrenaline.
Bupivacaine has a prolonged duration of action and is therefore used for long procedures and post-operative analgesia.');
INSERT INTO questions (id, topic_id, stem, option_a, option_b, option_c, option_d, option_e, correct_option, explanation) VALUES (507, 15, 'A 63-year-old man presented with a nc,dular oasal cell carcinoma on the left side: of his forehead above his eyebrow which was excised. Two weeks following the excision, he is still complaining of the inability to raise his left eyebrow which results in a droopy left eyebrow. Which nerve has been damaged during the procedure?', 'Great auricular nerve.', 'Marginal mandibular branch of facial nerve.', 'Sciatic nerve.', 'Spinal accessory nerve.', 'Temporal branch of facial nerve.', 'E', 'The temporal branch of the facial nerve innervates the frontalis and the upper portion of the orbicularis oculi.
Damage to the marginal mandibular branch of the facial nerve will result in drooping of the mouth and the inability to evert the lip laterally and inferiorly.
Damage to the great auricular nerve will result in numbness of the inferior two thirds of the ear and the adjacent cheek and neck area.
Damage to the spinal accessory nerve will result in a winged scapula (the inability to shrug the shoulder and abduct the arm).');

COMMIT;
